NEXT_PUBLIC_RALLYPOINT_SUPABASE_KEY=<publishable or anon key>
RALLYPOINT_GITHUB_REPO=<owner>/<name>      # Rallypoint lanes, delivery, skills
RALLYPOINT_GITHUB_TOKEN=<optional token>   # rate limits, private repos`}
