/**
 * Beam budget: which events earn a beam along the graph's edges, and how many can fly at once.
 *
 * Pure and renderer-agnostic, so the caps are unit-tested. The renderer asks `beamTier` whether an
 * event deserves a beam at all, then asks the gate (`createBeamGate`) whether it may fire one now.
 *
 * - Routine events (progress, game results, sessions, posts, plans) get no beam: a tick on the
 *   replay timeline and a soft pulse on their node at most.
 * - Beams are reserved for claims, pull requests opened, verdicts, merges and milestones. Merges,
 *   rungs cleared and rating jumps are the "big" tier: the only beams allowed a little glow.
 * - Coalescing: a beam for the same (sector, kind) within `windowMs` of the last one folds into it
 *   (its count grows) instead of firing again. A burst of 30 game results is one beam with a count.
 * - Hard caps: at most `maxInFlight` beams in flight and one new beam per `minGapMs`. Anything over
 *   a cap folds into the next beam that does fire.
 *
 * The same gate serves the live graph, the replay and the catch-up after a hidden tab.
 */

import type { SwarmEventKind } from './model';

export type BeamTier = 'none' | 'beam' | 'big';

/** Event kinds that may carry a beam. Everything else is routine. */
const BEAM_KINDS: ReadonlySet<SwarmEventKind> = new Set<SwarmEventKind>([
  'claim',
  'pr',
  'review',
  'reject',
  'merge',
  'milestone',
  'rating',
]);

/** The effects (from `effectOf`) that count as big moments. */
const BIG_EFFECTS = new Set(['merge', 'rung', 'rating']);

/**
 * Whether an event earns a beam. `effect` is the host's reading of it (`effectOf`); a rating with
 * no change is routine, as is a milestone the host chose not to mark.
 */
export const beamTier = (
  flow: { kind: SwarmEventKind; delta?: number | null },
  effect: string | null,
): BeamTier => {
  if (!BEAM_KINDS.has(flow.kind)) return 'none';
  if (flow.kind === 'rating' && !flow.delta) return 'none';
  if (effect && BIG_EFFECTS.has(effect)) return 'big';
  return 'beam';
};

export type BeamGateOptions = {
  /** Most beams in flight at once. Default 2. */
  maxInFlight?: number;
  /** Least time between two new beams, ms. Default 400. */
  minGapMs?: number;
  /** A beam for the same key within this long of the last folds into it, ms. Default 1500. */
  windowMs?: number;
};

export type BeamOffer =
  /** Fire a beam now; `id` reads its count later (it grows as events fold into it). */
  | { fire: true; id: number; count: number }
  /** No new beam: the event folded into beam `into` (null: into the next one to fire). */
  | { fire: false; into: number | null };

export type BeamGate = {
  /**
   * Offer one event: `key` is what coalesces (sector and kind), `durationMs` how long its beam
   * would fly. Returns whether to fire a beam and with what count.
   */
  offer: (key: string, now: number, durationMs: number) => BeamOffer;
  /** How many events beam `id` carries now (1 if it is unknown or long gone). */
  count: (id: number) => number;
  /** Beams in flight at `now`. */
  inFlight: (now: number) => number;
  /** Events waiting to fold into the next beam. */
  held: () => number;
  /** Forget everything (a replay seek, a new run). */
  reset: () => void;
};

type Beam = { id: number; key: string; start: number; end: number; count: number };

export const createBeamGate = (options: BeamGateOptions = {}): BeamGate => {
  const maxInFlight = options.maxInFlight ?? 2;
  const minGapMs = options.minGapMs ?? 400;
  const windowMs = options.windowMs ?? 1500;
  // Beams still in flight or within the coalescing window of their start. Tiny: at most a few.
  let beams: Beam[] = [];
  let lastFire = -Infinity;
  let held = 0;
  let nextId = 1;

  // A landed beam is kept a moment longer, so its count can still be read where it lands.
  const keep = (b: Beam, now: number) => b.end + 1000 > now || now - b.start < windowMs;
  const prune = (now: number) => {
    if (beams.some((b) => !keep(b, now))) beams = beams.filter((b) => keep(b, now));
  };
  const inFlight = (now: number) => {
    let n = 0;
    for (const b of beams) if (b.end > now) n++;
    return n;
  };

  return {
    offer(key, now, durationMs) {
      prune(now);
      // Coalesce: the newest beam with this key, still within the window, takes the event.
      for (let i = beams.length - 1; i >= 0; i--) {
        const b = beams[i]!;
        if (b.key === key && now - b.start < windowMs) {
          b.count++;
          return { fire: false, into: b.id };
        }
      }
      if (inFlight(now) >= maxInFlight || now - lastFire < minGapMs) {
        held++;
        return { fire: false, into: null };
      }
      const beam: Beam = {
        id: nextId++,
        key,
        start: now,
        end: now + Math.max(0, durationMs),
        count: 1 + held,
      };
      held = 0;
      lastFire = now;
      beams.push(beam);
      return { fire: true, id: beam.id, count: beam.count };
    },
    count(id) {
      return beams.find((b) => b.id === id)?.count ?? 1;
    },
    inFlight,
    held: () => held,
    reset() {
      beams = [];
      held = 0;
      lastFire = -Infinity;
    },
  };
};

/**
 * Particle effects for the swarm graph: pure, framework-free, renderer-agnostic. A host's GPU
 * layer (three.js on the arena's fleet page) owns the drawing; this module owns the particles.
 *
 * - `createParticlePool(capacity)`: a fixed-size pool. Every attribute lives in a preallocated
 *   typed array laid out for upload as GPU buffers, live particles stay packed at the front, and
 *   nothing allocates per frame.
 * - Emitters (`emitComet`, `emitMergeBurst`, …): one per effect the graph shows, each a few
 *   lines of initial conditions written into the pool.
 * - `createQuality()`: picks a quality level from measured frame times, with hysteresis, so a
 *   slow machine sheds particles and post-processing instead of dropping frames.
 * - `createActivity()`: how busy each node has been lately (a decaying count), for lighting.
 *
 * Coordinates are the graph's own (the SVG's user space, origin at the centre); `z` is depth for
 * parallax only (negative is behind the graph, positive in front).
 */

export type Rgb = { r: number; g: number; b: number };

/** Sprite shapes the fragment shader draws: a soft dot, a shaded ring, a flare, a spinning shard. */
export const SHAPE = { dot: 0, ring: 1, flare: 2, shard: 3 } as const;
export type ParticleShape = (typeof SHAPE)[keyof typeof SHAPE];

/** One particle's initial conditions. Velocities are px/s, accelerations px/s². */
export type ParticleSpec = {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  /** Lifetime, ms. */
  life: number;
  /** Sprite size at birth and at death, px. */
  size: number;
  sizeEnd: number;
  r: number;
  g: number;
  b: number;
  /** Peak opacity. */
  alpha: number;
  shape: ParticleShape;
  /** Rotation speed, rad/s (shards). */
  spin: number;
  /** Fraction of velocity kept per second (1 keeps all). */
  drag: number;
  /** Downward acceleration (negative rises). */
  gravity: number;
  /** Pull towards (px, py), per second; 0 for none. Merge sprays settle into their node. */
  pull: number;
  px: number;
  py: number;
};

/** Floats per particle in each GPU-ready array. */
export const STRIDE = { position: 3, color: 4, extra: 4 } as const;

export type ParticlePool = {
  readonly capacity: number;
  /** Live particles, packed at indexes [0, count). */
  readonly count: number;
  /** x, y, z per particle. */
  readonly position: Float32Array;
  /** r, g, b, alpha per particle (alpha already faded by age). */
  readonly color: Float32Array;
  /** size, shape, angle, life fraction per particle. */
  readonly extra: Float32Array;
  /** A scratch spec, reset by `spec()`, for emitters that want to avoid allocating. */
  spec: () => ParticleSpec;
  /** Add one particle; false when the pool (or its current limit) is full. */
  emit: (p: ParticleSpec) => boolean;
  /** Advance every particle by `dtMs`, retiring the dead. */
  step: (dtMs: number) => void;
  /** Cap the live count below the capacity (adaptive quality); never grows the arrays. */
  setLimit: (n: number) => void;
  readonly limit: number;
  clear: () => void;
};

const blank = (): ParticleSpec => ({
  x: 0,
  y: 0,
  z: 0,
  vx: 0,
  vy: 0,
  life: 600,
  size: 4,
  sizeEnd: 0,
  r: 1,
  g: 1,
  b: 1,
  alpha: 1,
  shape: SHAPE.dot,
  spin: 0,
  drag: 1,
  gravity: 0,
  pull: 0,
  px: 0,
  py: 0,
});

/** Simulation-only floats per particle: vx, vy, age, life, size0, size1, alpha, spin, drag,
 * gravity, pull, px, py. */
const SIM = 13;

export const createParticlePool = (capacity: number): ParticlePool => {
  const cap = Math.max(1, Math.floor(capacity));
  const position = new Float32Array(cap * STRIDE.position);
  const color = new Float32Array(cap * STRIDE.color);
  const extra = new Float32Array(cap * STRIDE.extra);
  const sim = new Float32Array(cap * SIM);
  const defaults = Object.freeze(blank());
  const scratch = blank();
  let count = 0;
  let limit = cap;

  const copy = (from: number, to: number) => {
    position.copyWithin(to * 3, from * 3, from * 3 + 3);
    color.copyWithin(to * 4, from * 4, from * 4 + 4);
    extra.copyWithin(to * 4, from * 4, from * 4 + 4);
    sim.copyWithin(to * SIM, from * SIM, from * SIM + SIM);
  };

  const pool: ParticlePool = {
    capacity: cap,
    get count() {
      return count;
    },
    get limit() {
      return limit;
    },
    position,
    color,
    extra,
    spec: () => Object.assign(scratch, defaults),
    emit: (p) => {
      if (count >= limit) return false;
      const i = count++;
      position[i * 3] = p.x;
      position[i * 3 + 1] = p.y;
      position[i * 3 + 2] = p.z;
      color[i * 4] = p.r;
      color[i * 4 + 1] = p.g;
      color[i * 4 + 2] = p.b;
      color[i * 4 + 3] = 0;
      extra[i * 4] = p.size;
      extra[i * 4 + 1] = p.shape;
      extra[i * 4 + 2] = Math.random() * Math.PI * 2;
      extra[i * 4 + 3] = 0;
      const s = i * SIM;
      sim[s] = p.vx;
      sim[s + 1] = p.vy;
      sim[s + 2] = 0;
      sim[s + 3] = Math.max(1, p.life);
      sim[s + 4] = p.size;
      sim[s + 5] = p.sizeEnd;
      sim[s + 6] = p.alpha;
      sim[s + 7] = p.spin;
      sim[s + 8] = p.drag;
      sim[s + 9] = p.gravity;
      sim[s + 10] = p.pull;
      sim[s + 11] = p.px;
      sim[s + 12] = p.py;
      return true;
    },
    step: (dtMs) => {
      const dt = Math.max(0, Math.min(100, dtMs)) / 1000;
      let i = 0;
      while (i < count) {
        const s = i * SIM;
        const age = sim[s + 2]! + dt * 1000;
        const life = sim[s + 3]!;
        if (age >= life) {
          // Swap the last live particle into this slot: the live set stays packed.
          count--;
          if (i !== count) copy(count, i);
          continue;
        }
        sim[s + 2] = age;
        const keep = sim[s + 8]! >= 1 ? 1 : Math.pow(sim[s + 8]!, dt);
        let vx = sim[s]! * keep;
        let vy = sim[s + 1]! * keep + sim[s + 9]! * dt;
        const pull = sim[s + 10]!;
        const p = i * 3;
        if (pull > 0) {
          vx += (sim[s + 11]! - position[p]!) * pull * dt;
          vy += (sim[s + 12]! - position[p + 1]!) * pull * dt;
        }
        sim[s] = vx;
        sim[s + 1] = vy;
        position[p]! += vx * dt;
        position[p + 1]! += vy * dt;
        const t = age / life;
        const e = i * 4;
        extra[e] = sim[s + 4]! + (sim[s + 5]! - sim[s + 4]!) * t;
        extra[e + 2]! += sim[s + 7]! * dt;
        extra[e + 3] = t;
        color[e + 3] = sim[s + 6]! * fade(t);
        i++;
      }
    },
    setLimit: (n) => {
      limit = Math.max(0, Math.min(cap, Math.floor(n)));
      if (count > limit) count = limit;
    },
    clear: () => {
      count = 0;
    },
  };
  return pool;
};

/** Opacity over a particle's life: a quick rise, then an ease-out fade. */
export const fade = (t: number) => {
  if (t <= 0 || t >= 1) return 0;
  if (t < 0.08) return t / 0.08;
  const u = (t - 0.08) / 0.92;
  return 1 - u * u;
};

// ---- emitters ---------------------------------------------------------------------------------

/** A tiny seeded-or-not random source; emitters take one so tests can pin it. */
export type Random = () => number;

const tint = (p: ParticleSpec, c: Rgb, k = 1) => {
  p.r = Math.min(1, c.r * k);
  p.g = Math.min(1, c.g * k);
  p.b = Math.min(1, c.b * k);
};

/** One point of a comet's tail, dropped where the spark's head is now. */
export const emitComet = (
  pool: ParticlePool,
  x: number,
  y: number,
  c: Rgb,
  size: number,
  rand: Random = Math.random,
) => {
  const p = pool.spec();
  p.x = x + (rand() - 0.5) * 1.5;
  p.y = y + (rand() - 0.5) * 1.5;
  p.z = 0.4;
  p.life = 360 + rand() * 120;
  p.size = size * 2.4;
  p.sizeEnd = size * 0.4;
  p.alpha = 0.85;
  tint(p, c, 1.15);
  return pool.emit(p);
};

/** A merge: a radial spray out of the sector node that slows and settles back into it. */
export const emitMergeBurst = (
  pool: ParticlePool,
  x: number,
  y: number,
  radius: number,
  c: Rgb,
  count = 60,
  rand: Random = Math.random,
) => {
  for (let i = 0; i < count; i++) {
    const p = pool.spec();
    const a = (i / count) * Math.PI * 2 + rand() * 0.3;
    const v = 140 + rand() * 220;
    p.x = x + Math.cos(a) * radius * 0.5;
    p.y = y + Math.sin(a) * radius * 0.5;
    p.z = 0.2 + rand() * 0.6;
    p.vx = Math.cos(a) * v;
    p.vy = Math.sin(a) * v;
    p.drag = 0.02;
    p.pull = 24;
    p.px = x;
    p.py = y;
    p.life = 700 + rand() * 350;
    p.size = 3 + rand() * 4;
    p.sizeEnd = 1;
    tint(p, c, 1.25);
    if (!pool.emit(p)) return;
  }
};

/** A rating rise: a short upward fountain, sized by the delta. A fall is a few sinking motes. */
export const emitRatingFountain = (
  pool: ParticlePool,
  x: number,
  y: number,
  radius: number,
  c: Rgb,
  delta: number,
  rand: Random = Math.random,
) => {
  const up = delta > 0;
  const count = Math.round(Math.min(70, 10 + Math.abs(delta) * (up ? 0.35 : 0.1)));
  for (let i = 0; i < count; i++) {
    const p = pool.spec();
    const spread = (rand() - 0.5) * 0.9;
    const v = up ? 160 + rand() * 160 : 30 + rand() * 40;
    p.x = x + spread * radius;
    p.y = y - (up ? radius * 0.6 : -radius * 0.2);
    p.z = 0.3 + rand() * 0.6;
    p.vx = spread * v * 0.6;
    p.vy = up ? -v : v;
    p.gravity = up ? 260 : 20;
    p.drag = 0.4;
    p.life = up ? 800 + rand() * 400 : 900;
    p.size = 2.5 + rand() * 3;
    p.sizeEnd = 0.5;
    tint(p, c, up ? 1.2 : 0.6);
    if (!pool.emit(p)) return;
  }
};

/** A rung cleared: an expanding shockwave of particles, and one shaded ring billboard. */
export const emitShockwave = (
  pool: ParticlePool,
  x: number,
  y: number,
  radius: number,
  c: Rgb,
  count = 56,
  rand: Random = Math.random,
) => {
  const ring = pool.spec();
  ring.x = x;
  ring.y = y;
  ring.z = 0.5;
  ring.shape = SHAPE.ring;
  ring.life = 850;
  ring.size = radius * 2;
  ring.sizeEnd = radius * 2 + 260;
  ring.alpha = 0.9;
  tint(ring, c, 1.2);
  pool.emit(ring);
  for (let i = 0; i < count; i++) {
    const p = pool.spec();
    const a = (i / count) * Math.PI * 2;
    const v = 190 + rand() * 25;
    p.x = x + Math.cos(a) * radius;
    p.y = y + Math.sin(a) * radius;
    p.z = 0.5;
    p.vx = Math.cos(a) * v;
    p.vy = Math.sin(a) * v;
    p.drag = 0.15;
    p.life = 700;
    p.size = 3;
    p.sizeEnd = 1;
    tint(p, c, 1.3);
    if (!pool.emit(p)) return;
  }
};

/** A buried idea: it comes apart gently into drifting embers and a few turning shards. */
export const emitEmbers = (
  pool: ParticlePool,
  x: number,
  y: number,
  radius: number,
  c: Rgb,
  rand: Random = Math.random,
) => {
  for (let i = 0; i < 26; i++) {
    const p = pool.spec();
    const a = rand() * Math.PI * 2;
    const d = rand() * radius;
    p.x = x + Math.cos(a) * d;
    p.y = y + Math.sin(a) * d;
    p.z = 0.2 + rand() * 0.4;
    p.vx = (rand() - 0.5) * 24;
    p.vy = -12 - rand() * 22;
    p.gravity = -6;
    p.life = 1400 + rand() * 900;
    p.size = 1.5 + rand() * 2;
    p.sizeEnd = 0.3;
    p.alpha = 0.7;
    // Embers glow warm, whatever the sector's colour.
    p.r = Math.min(1, 0.55 + c.r * 0.45);
    p.g = Math.min(1, 0.32 + c.g * 0.3);
    p.b = Math.min(1, 0.12 + c.b * 0.15);
    if (!pool.emit(p)) return;
  }
  for (let i = 0; i < 8; i++) {
    const p = pool.spec();
    const a = (i / 8) * Math.PI * 2 + rand();
    p.x = x;
    p.y = y;
    p.z = 0.6;
    p.vx = Math.cos(a) * (30 + rand() * 30);
    p.vy = Math.sin(a) * (30 + rand() * 30) - 10;
    p.shape = SHAPE.shard;
    p.spin = (rand() - 0.5) * 9;
    p.drag = 0.5;
    p.life = 1200 + rand() * 500;
    p.size = 7 + rand() * 5;
    p.sizeEnd = 2;
    p.alpha = 0.8;
    tint(p, c, 0.9);
    if (!pool.emit(p)) return;
  }
};

/** A version landing: a brief cross-shaped glint. */
export const emitFlare = (pool: ParticlePool, x: number, y: number, radius: number, c: Rgb) => {
  const p = pool.spec();
  p.x = x;
  p.y = y;
  p.z = 0.9;
  p.shape = SHAPE.flare;
  p.life = 520;
  p.size = radius * 3.2;
  p.sizeEnd = radius * 1.2;
  tint(p, c, 1.5);
  return pool.emit(p);
};

/** A small puff where a spark passes through a node on its way. */
export const emitPuff = (
  pool: ParticlePool,
  x: number,
  y: number,
  c: Rgb,
  count = 8,
  rand: Random = Math.random,
) => {
  for (let i = 0; i < count; i++) {
    const p = pool.spec();
    const a = rand() * Math.PI * 2;
    const v = 40 + rand() * 60;
    p.x = x;
    p.y = y;
    p.z = 0.4;
    p.vx = Math.cos(a) * v;
    p.vy = Math.sin(a) * v;
    p.drag = 0.05;
    p.life = 420;
    p.size = 2.5;
    p.sizeEnd = 0.5;
    tint(p, c);
    if (!pool.emit(p)) return;
  }
};

/** A slow sparkle on a node's rim: agents are on it. */
export const emitSparkle = (
  pool: ParticlePool,
  x: number,
  y: number,
  radius: number,
  c: Rgb,
  rand: Random = Math.random,
) => {
  const p = pool.spec();
  const a = rand() * Math.PI * 2;
  p.x = x + Math.cos(a) * radius * (0.9 + rand() * 0.4);
  p.y = y + Math.sin(a) * radius * (0.9 + rand() * 0.4);
  p.z = 0.3;
  p.vy = -8;
  p.life = 900 + rand() * 500;
  p.size = 2 + rand() * 2;
  p.sizeEnd = 0.2;
  p.alpha = 0.75;
  tint(p, c, 1.3);
  return pool.emit(p);
};

/** Ambient dust: faint motes drifting behind the graph (deeper ones slower). */
export const emitMote = (
  pool: ParticlePool,
  width: number,
  height: number,
  c: Rgb,
  rand: Random = Math.random,
) => {
  const p = pool.spec();
  const z = -0.3 - rand() * 0.7;
  p.x = (rand() - 0.5) * width;
  p.y = (rand() - 0.5) * height;
  p.z = z;
  const speed = 6 + (1 + z) * 10;
  const a = rand() * Math.PI * 2;
  p.vx = Math.cos(a) * speed;
  p.vy = Math.sin(a) * speed;
  p.life = 4000 + rand() * 4000;
  p.size = 1.5 + rand() * 2;
  p.sizeEnd = p.size;
  p.alpha = 0.22;
  tint(p, c, 0.9);
  return pool.emit(p);
};

// ---- adaptive quality -------------------------------------------------------------------------

export type QualityLevel = 'high' | 'medium' | 'low';
const LEVELS: QualityLevel[] = ['low', 'medium', 'high'];

/**
 * What each level allows: a share of the host's particle budget, the canvases' resolution, how
 * often the background redraws (every n-th frame) and which extras run.
 */
export const QUALITY: Record<
  QualityLevel,
  {
    particles: number;
    resolution: number;
    backgroundEvery: number;
    trails: boolean;
    post: boolean;
    bloom: boolean;
    ambient: boolean;
  }
> = {
  high: {
    particles: 1,
    resolution: 1,
    backgroundEvery: 1,
    trails: true,
    post: true,
    bloom: true,
    ambient: true,
  },
  medium: {
    particles: 0.55,
    resolution: 0.75,
    backgroundEvery: 2,
    trails: true,
    post: true,
    bloom: true,
    ambient: false,
  },
  low: {
    particles: 0.25,
    resolution: 0.5,
    backgroundEvery: 4,
    trails: false,
    post: false,
    bloom: false,
    ambient: false,
  },
};

export type QualityOptions = {
  initial?: QualityLevel;
  /** Highest level allowed. */
  max?: QualityLevel;
  /** Smoothed frame time above this steps down. Default 20 ms (a slipping 60 fps). */
  slowMs?: number;
  /** Smoothed frame time below this, held long enough, steps back up. Default 13 ms. */
  fastMs?: number;
  /** How long (ms of frames) a condition must hold first. Default 1.5 s down, 8 s up. */
  downAfterMs?: number;
  upAfterMs?: number;
  /** At the lowest level, frames this slow for `giveUpAfterMs` mean the layer should stop. */
  giveUpMs?: number;
  giveUpAfterMs?: number;
};

export type Quality = {
  readonly level: QualityLevel;
  /** The smoothed frame time, ms. */
  readonly frameMs: number;
  /**
   * Even the lowest level cannot keep up (frames slower than `giveUpMs` for `giveUpAfterMs`):
   * the host should switch its effects off and leave the graph alone.
   */
  readonly hopeless: boolean;
  /** Feed one frame's time; returns the (possibly new) level. */
  sample: (frameMs: number) => QualityLevel;
  setMax: (max: QualityLevel) => void;
};

export const createQuality = (options: QualityOptions = {}): Quality => {
  let max = LEVELS.indexOf(options.max ?? 'high');
  let level = Math.min(max, LEVELS.indexOf(options.initial ?? 'high'));
  const slow = options.slowMs ?? 20;
  const fast = options.fastMs ?? 13;
  const downAfter = options.downAfterMs ?? 1500;
  const upAfter = options.upAfterMs ?? 8000;
  const giveUp = options.giveUpMs ?? 50;
  const giveUpAfter = options.giveUpAfterMs ?? 4000;
  let ema = 16.7;
  let slowFor = 0;
  let fastFor = 0;
  let hopelessFor = 0;
  return {
    get level() {
      return LEVELS[level]!;
    },
    get frameMs() {
      return ema;
    },
    get hopeless() {
      return hopelessFor >= giveUpAfter;
    },
    sample: (raw) => {
      // A frame after a hidden tab or a breakpoint says nothing about the machine.
      if (!(raw > 0) || raw > 1000) return LEVELS[level]!;
      const ms = Math.min(raw, 250);
      ema += (ms - ema) * 0.1;
      slowFor = ema > slow ? slowFor + ms : 0;
      fastFor = ema < fast ? fastFor + ms : 0;
      hopelessFor = level === 0 && ema > giveUp ? hopelessFor + ms : 0;
      if (slowFor >= downAfter && level > 0) {
        level--;
        slowFor = 0;
        // Give the lighter level a fair start.
        ema = (slow + fast) / 2;
      } else if (fastFor >= upAfter && level < max) {
        level++;
        fastFor = 0;
      }
      return LEVELS[level]!;
    },
    setMax: (m) => {
      max = LEVELS.indexOf(m);
      level = Math.min(level, max);
    },
  };
};

// ---- activity ---------------------------------------------------------------------------------

export type Activity = {
  /** Something happened at a node. */
  bump: (id: string, amount?: number) => void;
  /** Let every node's activity decay by `dtMs`. */
  decay: (dtMs: number) => void;
  /** 0 (quiet) to 1 (busy), saturating. */
  level: (id: string) => number;
};

/** How busy each node has been lately: a count with a half-life, squashed into [0, 1). */
export const createActivity = (halfLifeMs = 20_000, saturation = 4): Activity => {
  const raw = new Map<string, number>();
  return {
    bump: (id, amount = 1) => raw.set(id, (raw.get(id) ?? 0) + amount),
    decay: (dtMs) => {
      const k = Math.pow(0.5, Math.max(0, dtMs) / halfLifeMs);
      for (const [id, v] of raw) {
        const next = v * k;
        if (next < 0.01) raw.delete(id);
        else raw.set(id, next);
      }
    },
    level: (id) => {
      const v = raw.get(id) ?? 0;
      return v / (v + saturation);
    },
  };
};

// The fleet graph engine: Swarm Arena's @rallypoint/swarm-graph (swarm-graph/src), framework-free
// D3. Changed only by non-null assertions on indexed reads, for noUncheckedIndexedAccess. The
// scaffold's adapter is ../_lib/fleet-graph.ts; its mount is ../_components/fleet-graph.tsx.
export * from './model';
export * from './render';
export * from './replay';
export * from './intro';
export * from './effects';
export * from './beams';
export * from './lifecycle';

/**
 * The graph's first-load reveal, as pure timing: which node starts moving when, and where it is
 * at any moment of the tween. The renderer settles the layout off-screen first, so every node's
 * end position is known; the intro then fans the nodes out from the hub along their radial
 * direction — the hub first, the sectors one after another clockwise from the top, then the work
 * and agents around each sector — and the edges draw on as their endpoints arrive.
 *
 * No DOM and nothing game-specific: nodes come in as ids, a role (hub, sector, other), the
 * sector they belong to, and their settled position.
 */

export type IntroNode = {
  id: string;
  role: 'hub' | 'sector' | 'other';
  /** For `other` nodes: the id of the sector node they belong to, if any. */
  sectorId?: string | null;
  /** Settled position, relative to the hub at (0, 0). */
  x: number;
  y: number;
};

export type IntroTiming = {
  /** When the node starts moving, in ms from the start of the intro. */
  delay: number;
  /** How long its tween lasts, in ms. */
  duration: number;
};

export type IntroPlan = {
  timing: Map<string, IntroTiming>;
  /** When the last node arrives at its place: nothing moves after this. */
  totalMs: number;
  /** When labels start fading in (they come last). */
  labelsAt: number;
  /** How long the camera pulls back from its opening zoom on the hub. */
  cameraMs: number;
};

export type IntroOptions = {
  /** Length of one node's tween. About 900–1400 ms for the full intro, ~300 for the short one. */
  nodeMs?: number;
  /** Gap between consecutive sectors around the ring. */
  sectorStaggerMs?: number;
  /** Gap between the hub starting and the first sector starting. */
  hubLeadMs?: number;
  /** Lag of a sector's satellites behind the sector itself. */
  satelliteLagMs?: number;
  /** Extra stagger per satellite, by distance from the hub, within one sector. */
  satelliteStaggerMs?: number;
};

/** The full first-load intro: about 1.1 s per node, sectors 80 ms apart. */
export const FULL_INTRO: Required<IntroOptions> = {
  nodeMs: 1100,
  sectorStaggerMs: 80,
  hubLeadMs: 120,
  satelliteLagMs: 160,
  satelliteStaggerMs: 25,
};

/** The shorter version for coming back to the page: everything in about half a second. */
export const SHORT_INTRO: Required<IntroOptions> = {
  nodeMs: 320,
  sectorStaggerMs: 14,
  hubLeadMs: 20,
  satelliteLagMs: 40,
  satelliteStaggerMs: 4,
};

/** Clockwise angle from 12 o'clock, in [0, 2π), with y pointing down (screen coordinates). */
export const clockAngle = (x: number, y: number): number => {
  const a = Math.atan2(y, x) + Math.PI / 2;
  const full = Math.PI * 2;
  return ((a % full) + full) % full;
};

/** At most this many satellites per sector get their own stagger step; the rest share the last. */
const MAX_STEPS = 8;

export const planIntro = (nodes: IntroNode[], options: IntroOptions = {}): IntroPlan => {
  const o = { ...FULL_INTRO, ...options };
  const timing = new Map<string, IntroTiming>();
  const at = (delay: number) => ({ delay, duration: o.nodeMs });

  for (const n of nodes) if (n.role === 'hub') timing.set(n.id, at(0));

  const sectors = nodes
    .filter((n) => n.role === 'sector')
    .sort((a, b) => clockAngle(a.x, a.y) - clockAngle(b.x, b.y) || a.id.localeCompare(b.id));
  const sectorDelay = new Map<string, number>();
  sectors.forEach((s, i) => {
    const d = o.hubLeadMs + i * o.sectorStaggerMs;
    sectorDelay.set(s.id, d);
    timing.set(s.id, at(d));
  });

  // Satellites follow their sector, nearest the hub first; unattached ones (gate roles around
  // the hub) go with the first sector.
  const bySector = new Map<string, IntroNode[]>();
  for (const n of nodes) {
    if (n.role !== 'other') continue;
    const key = n.sectorId && sectorDelay.has(n.sectorId) ? n.sectorId : '';
    const list = bySector.get(key) ?? [];
    list.push(n);
    bySector.set(key, list);
  }
  for (const [key, list] of bySector) {
    const base = (key ? sectorDelay.get(key)! : o.hubLeadMs) + o.satelliteLagMs;
    list
      .sort((a, b) => Math.hypot(a.x, a.y) - Math.hypot(b.x, b.y) || a.id.localeCompare(b.id))
      .forEach((n, i) =>
        timing.set(n.id, at(base + Math.min(i, MAX_STEPS) * o.satelliteStaggerMs)),
      );
  }

  let last = 0;
  for (const t of timing.values()) last = Math.max(last, t.delay + t.duration);
  return {
    timing,
    totalMs: last,
    labelsAt: Math.max(0, last - o.nodeMs * 0.45),
    cameraMs: last,
  };
};

/** Raw progress of one node's tween at `t` ms into the intro, in [0, 1]. Unknown nodes are done. */
export const introProgress = (timing: IntroTiming | undefined, t: number): number => {
  if (!timing) return 1;
  if (timing.duration <= 0) return t >= timing.delay ? 1 : 0;
  return Math.max(0, Math.min(1, (t - timing.delay) / timing.duration));
};

/** Ease-out cubic: fast out of the hub, settling softly at the end, never overshooting. */
export const easeOut = (p: number): number => 1 - (1 - Math.max(0, Math.min(1, p))) ** 3;

/**
 * Where a node is drawn at `t`: on the straight line from the hub to its settled spot (its
 * radial direction), with scale and opacity rising from 0.
 */
export const introPose = (
  node: Pick<IntroNode, 'x' | 'y'>,
  timing: IntroTiming | undefined,
  t: number,
): { x: number; y: number; scale: number; opacity: number } => {
  const e = easeOut(introProgress(timing, t));
  return {
    x: node.x * e,
    y: node.y * e,
    scale: 0.05 + 0.95 * e,
    opacity: Math.min(1, introProgress(timing, t) * 2.5),
  };
};

/** How much of an edge is drawn: it follows whichever endpoint arrives later. */
export const introEdge = (
  source: IntroTiming | undefined,
  target: IntroTiming | undefined,
  t: number,
): number => easeOut(Math.min(introProgress(source, t), introProgress(target, t)));

/** The opening zoom on the hub easing back to the fitted view (scale 1). */
export const introCamera = (plan: IntroPlan, t: number, from = 1.15): number =>
  1 + (from - 1) * (1 - easeOut(plan.cameraMs > 0 ? t / plan.cameraMs : 1));

/** Label opacity: labels fade in over the last stretch of the intro. */
export const introLabels = (plan: IntroPlan, t: number): number => {
  const span = plan.totalMs - plan.labelsAt;
  if (span <= 0) return t >= plan.totalMs ? 1 : 0;
  return Math.max(0, Math.min(1, (t - plan.labelsAt) / span));
};

/**
 * The positioning engine (#221): where every node of the swarm graph stands, computed off-screen
 * and to convergence before anything is drawn. The renderer never runs physics on screen; it
 * only tweens each node from where it is to the place this module gives it.
 *
 * The engine is d3-force's model run headless to rest (see `layoutGraph`), chosen over
 * cytoscape-fcose, WebCola and ELK on stability under incremental change, determinism, speed and
 * bundle size (the numbers are in the pull request for #221). Two rules give the stability,
 * whatever the solver:
 *
 * - **Sectors and the hub are fixed** (`fixed`): the ring, set by the canvas, never by the data.
 * - **Every node already laid out is pinned** (`pinned`): only new or re-placed nodes are free.
 *   A node arriving or leaving anywhere moves nothing else; pinned nodes never give way to
 *   each other. (Growth has room reserved: a sector is laid out at its largest size.) Only a
 *   re-fit (`settle`, a resized canvas) lets a pinned node that overlaps another move out, by
 *   exactly the overlap and no further.
 *
 * Deterministic: the same nodes, links and pins give the same positions (a seeded random source,
 * start points derived from ids, no clock). Pure: no DOM, so it can run in a test or a worker.
 */

export type LayoutPoint = { x: number; y: number };

export type LayoutNode = {
  id: string;
  /** Room the node keeps clear around its centre: its body, its ring and a margin. */
  r: number;
  /** Where its sector pulls it (a free node only), and how hard. */
  anchor: LayoutPoint;
  anchorStrength: number;
  /** Many-body strength (negative repels). */
  charge: number;
  /** Held here whatever happens: the sectors on their ring, the hub at the centre. */
  fixed?: LayoutPoint;
  /** Already laid out: it stays exactly here (unless `settle` must clear an overlap). */
  pinned?: LayoutPoint;
  /** Where a free node starts (its last place, for a re-placed node). Default: beside `parent`. */
  start?: LayoutPoint;
  /** What a new node is placed beside: its sector, its work item. */
  parent?: string;
  /** Half the box it must stay inside, centred on the origin. */
  limit: LayoutPoint;
};

export type LayoutLink = { source: string; target: string; distance: number; strength: number };

export type LayoutResult = {
  positions: Map<string, LayoutPoint>;
  /** Nodes the solver placed (neither fixed nor pinned). */
  free: number;
  /** Solver ticks it took to rest (0 when nothing was free). */
  ticks: number;
};

export type LayoutOptions = {
  /** Seed of the random source that splits coincident nodes. */
  seed?: number;
  /** Most solver ticks; it stops earlier once the free nodes rest. */
  maxTicks?: number;
  /**
   * Clear overlaps between held nodes too (the smaller pinned one gives way by the overlap).
   * For a re-fit after a resize; never for a data update, so nothing pinned moves then.
   */
  settle?: boolean;
};

type Body = { node: LayoutNode; mobile: boolean; x: number; y: number };

/** FNV-1a: a stable number per id, for start angles. */
export const hashId = (s: string) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
};

/** A small seeded generator (an LCG), so the solver's jiggle is reproducible. */
const lcg = (seed: number) => {
  let s = seed >>> 0 || 1;
  return () => (s = (Math.imul(1664525, s) + 1013904223) >>> 0) / 4294967296;
};

/** Where a new node starts: just outside its parent, turned towards its anchor. */
export const besideParent = (
  parent: LayoutPoint & { r: number },
  anchor: LayoutPoint,
  id: string,
  r: number,
): LayoutPoint => {
  let dx = anchor.x - parent.x;
  let dy = anchor.y - parent.y;
  if (Math.hypot(dx, dy) < 1) {
    // No pull away from the parent: head outward, away from the centre.
    dx = parent.x || 1;
    dy = parent.y;
  }
  const spin = ((hashId(id) % 1000) / 1000 - 0.5) * 1.6;
  const a = Math.atan2(dy, dx) + spin;
  const d = parent.r + r + 6;
  return { x: parent.x + Math.cos(a) * d, y: parent.y + Math.sin(a) * d };
};

const clampTo = (b: Body) => {
  if (b.node.fixed) return;
  const { x, y } = b.node.limit;
  b.x = Math.max(-x, Math.min(x, b.x));
  b.y = Math.max(-y, Math.min(y, b.y));
};

/**
 * Push overlapping nodes apart by exactly their overlap. Fixed nodes never move; free nodes give
 * way first; with `settle`, of two held nodes the smaller pinned one gives way. A few sweeps over
 * all pairs: the graph has a few hundred nodes.
 */
export const separate = (bodies: Body[], settle = false, sweeps = 24) => {
  for (let s = 0; s < sweeps; s++) {
    let moved = false;
    for (let i = 0; i < bodies.length; i++) {
      const a = bodies[i]!;
      for (let j = i + 1; j < bodies.length; j++) {
        const b = bodies[j]!;
        const min = a.node.r + b.node.r;
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        if (Math.abs(dx) >= min || Math.abs(dy) >= min) continue;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d >= min - 0.01) continue;
        // Who gives way: free nodes first; between two held ones, the smaller pinned one.
        let wa = a.mobile ? 1 : 0;
        let wb = b.mobile ? 1 : 0;
        if (!wa && !wb) {
          if (!settle) continue;
          const pa = a.node.fixed ? 0 : a.node.r;
          const pb = b.node.fixed ? 0 : b.node.r;
          if (!pa && !pb) continue;
          if (pa && (!pb || pa <= pb)) wa = 1;
          else wb = 1;
        }
        if (d < 1e-6) {
          // Coincident: split along a direction fixed by the ids.
          const t = ((hashId(a.node.id + b.node.id) % 360) * Math.PI) / 180;
          dx = Math.cos(t);
          dy = Math.sin(t);
        } else {
          dx /= d;
          dy /= d;
        }
        const push = min - d;
        const share = wa + wb;
        a.x -= (dx * push * wa) / share;
        a.y -= (dy * push * wa) / share;
        b.x += (dx * push * wb) / share;
        b.y += (dy * push * wb) / share;
        // Inside the canvas as it goes, so the last clamp never undoes a separation.
        clampTo(a);
        clampTo(b);
        moved = true;
      }
    }
    if (!moved) break;
  }
};

/**
 * The solver: d3-force's forces, integrated for the free bodies only, on flat typed arrays (the
 * inner loops are O(free × all) and run up to `maxTicks` times). `step(k)` runs at most `k` more
 * ticks and says whether it is done; once done, the bodies hold their places.
 */
const createSolver = (
  bodies: Body[],
  links: readonly LayoutLink[],
  maxTicks: number,
  seed: number,
) => {
  const n = bodies.length;
  const X = new Float64Array(n);
  const Y = new Float64Array(n);
  const VX = new Float64Array(n);
  const VY = new Float64Array(n);
  const R = new Float64Array(n);
  const Q = new Float64Array(n);
  const AX = new Float64Array(n);
  const AY = new Float64Array(n);
  const AS = new Float64Array(n);
  const LX = new Float64Array(n);
  const LY = new Float64Array(n);
  const M = new Uint8Array(n);
  const index = new Map<string, number>();
  bodies.forEach((b, i) => {
    index.set(b.node.id, i);
    X[i] = b.x ?? 0;
    Y[i] = b.y ?? 0;
    R[i] = b.node.r;
    Q[i] = b.node.charge;
    AX[i] = b.node.anchor.x;
    AY[i] = b.node.anchor.y;
    AS[i] = b.node.anchorStrength;
    LX[i] = b.node.limit.x;
    LY[i] = b.node.limit.y;
    M[i] = b.mobile ? 1 : 0;
  });
  const free = Int32Array.from(bodies.flatMap((b, i) => (b.mobile ? [i] : [])));
  const PX = new Float64Array(n);
  const order = Array.from({ length: n }, (_, i) => i);
  const rank = new Int32Array(n);
  const maxR = Math.max(...R);
  const springs = links
    .filter((l) => l.strength > 0 && index.has(l.source) && index.has(l.target))
    .map((l) => ({
      a: index.get(l.source)!,
      b: index.get(l.target)!,
      d: l.distance,
      k: l.strength,
    }))
    .filter((l) => M[l.a]! || M[l.b]!);
  const jiggle = lcg(seed);
  const split = () => (jiggle() - 0.5) * 1e-6;
  const DIST_MAX2 = 320 * 320;
  const KEEP = 0.6; // velocity kept per tick (d3's velocityDecay 0.4)
  const alphaDecay = 1 - Math.pow(0.001, 1 / maxTicks);
  let alpha = 1;
  let ticks = 0;
  let done = free.length === 0;
  const tick = () => {
    alpha += (0 - alpha) * alphaDecay;
    ticks++;
    // Springs: each pulls its ends towards its rest length; a held end does not give.
    for (const l of springs) {
      let dx = X[l.b]! + VX[l.b]! - X[l.a]! - VX[l.a]! || split();
      let dy = Y[l.b]! + VY[l.b]! - Y[l.a]! - VY[l.a]! || split();
      const d = Math.sqrt(dx * dx + dy * dy);
      const k = ((d - l.d) / d) * alpha * l.k * (M[l.a]! && M[l.b]! ? 0.5 : 1);
      dx *= k;
      dy *= k;
      if (M[l.b]!) {
        VX[l.b]! -= dx;
        VY[l.b]! -= dy;
      }
      if (M[l.a]!) {
        VX[l.a]! += dx;
        VY[l.a]! += dy;
      }
    }
    // Charge reaches DIST_MAX: walk out from each free node along x, both ways, until beyond it.
    order.sort((i, j) => X[i]! - X[j]!);
    for (let o = 0; o < n; o++) rank[order[o]!] = o;
    for (let f = 0; f < free.length; f++) {
      const a = free[f]!;
      // Pull to the anchor.
      let vx = VX[a]! + (AX[a]! - X[a]!) * AS[a]! * alpha;
      let vy = VY[a]! + (AY[a]! - Y[a]!) * AS[a]! * alpha;
      // Charge from every other node within reach (each repels with its own strength).
      const ax = X[a]!;
      const ay = Y[a]!;
      for (let dir = -1; dir <= 1; dir += 2)
        for (let o = rank[a]! + dir; o >= 0 && o < n; o += dir) {
          const b = order[o]!;
          let dx = X[b]! - ax;
          if (dx * dx >= DIST_MAX2) break;
          let dy = Y[b]! - ay;
          let l = dx * dx + dy * dy;
          if (l >= DIST_MAX2) continue;
          if (l === 0) {
            dx = split();
            dy = split();
            l = dx * dx + dy * dy;
          }
          if (l < 1) l = Math.sqrt(l);
          const w = (Q[b]! * alpha) / l;
          vx += dx * w;
          vy += dy * w;
        }
      VX[a] = vx;
      VY[a] = vy;
    }
    // Collision on the predicted positions, twice per tick (d3's iterations(2)): a sweep along
    // x, so only nodes near each other are compared.
    for (let it = 0; it < 2; it++) {
      for (let i = 0; i < n; i++) PX[i] = X[i]! + VX[i]!;
      order.sort((i, j) => PX[i]! - PX[j]!);
      for (let oi = 0; oi < n; oi++) {
        const a = order[oi]!;
        const reach = R[a]! + maxR;
        for (let oj = oi + 1; oj < n; oj++) {
          const b = order[oj]!;
          if (PX[b]! - PX[a]! >= reach) break;
          if (!M[a]! && !M[b]!) continue;
          const r = R[a]! + R[b]!;
          let dx = PX[a]! - PX[b]!;
          let dy = Y[a]! + VY[a]! - Y[b]! - VY[b]!;
          let l = dx * dx + dy * dy;
          if (l >= r * r) continue;
          if (l === 0) {
            dx = split();
            dy = split();
            l = dx * dx + dy * dy;
          }
          l = Math.sqrt(l);
          const k = (r - l) / l;
          const sa = M[a]! ? (M[b]! ? 0.5 : 1) : 0;
          const sb = M[b]! ? (M[a]! ? 0.5 : 1) : 0;
          VX[a]! += dx * k * sa;
          VY[a]! += dy * k * sa;
          VX[b]! -= dx * k * sb;
          VY[b]! -= dy * k * sb;
        }
      }
    }
    let v = 0;
    for (let f = 0; f < free.length; f++) {
      const a = free[f]!;
      VX[a]! *= KEEP;
      VY[a]! *= KEEP;
      X[a] = Math.max(-LX[a]!, Math.min(LX[a]!, X[a]! + VX[a]!));
      Y[a] = Math.max(-LY[a]!, Math.min(LY[a]!, Y[a]! + VY[a]!));
      v = Math.max(v, Math.abs(VX[a]!), Math.abs(VY[a]!));
    }
    // At rest: nothing free moves more than a twentieth of a pixel a tick (the tween to the
    // place is what the viewer sees, so sub-pixel settling is not worth the time).
    if ((ticks > 12 && v < 0.05) || ticks >= maxTicks) done = true;
  };
  const step = (k: number) => {
    for (let i = 0; i < k && !done; i++) tick();
    if (done)
      for (let f = 0; f < free.length; f++) {
        const a = free[f]!;
        bodies[a]!.x = X[a]!;
        bodies[a]!.y = Y[a]!;
      }
    return done;
  };
  return { step, ticks: () => ticks };
};

/** A layout in progress: `step(k)` runs up to `k` solver ticks; `result()` once it is done. */
export type LayoutJob = {
  /** Nodes the solver places (neither fixed nor pinned). */
  free: number;
  /** Run up to `ticks` more solver ticks. True once the layout is at rest. */
  step: (ticks: number) => boolean;
  /** The places, once `step` has returned true. */
  result: () => LayoutResult;
};

/**
 * Start a layout that can be run in slices (a few ticks per frame), so a big batch never blocks
 * the main thread for long. Run to the end, it gives exactly what `layoutGraph` gives.
 */
export const startLayout = (
  nodes: readonly LayoutNode[],
  links: readonly LayoutLink[],
  options: LayoutOptions = {},
): LayoutJob => {
  const maxTicks = options.maxTicks ?? 90;
  const byId = new Map(nodes.map((n) => [n.id, n]));

  // Start points: held nodes where they are held; new ones beside their parent.
  const start = new Map<string, LayoutPoint>();
  const startOf = (n: LayoutNode, depth = 0): LayoutPoint => {
    const known = start.get(n.id);
    if (known) return known;
    const held = n.fixed ?? n.pinned ?? n.start;
    let p: LayoutPoint;
    if (held) p = held;
    else {
      const parent = n.parent ? byId.get(n.parent) : undefined;
      p =
        parent && depth < 4
          ? besideParent({ ...startOf(parent, depth + 1), r: parent.r }, n.anchor, n.id, n.r)
          : n.anchor;
    }
    start.set(n.id, p);
    return p;
  };

  const bodies: Body[] = nodes.map((node) => {
    const p = startOf(node);
    const held = node.fixed ?? node.pinned;
    return { node, mobile: !held, x: held?.x ?? p.x, y: held?.y ?? p.y };
  });
  const free = bodies.filter((b) => b.mobile).length;
  const solver = createSolver(bodies, links, maxTicks, options.seed ?? 221);
  let out: LayoutResult | null = null;
  const step = (ticks: number) => {
    if (out) return true;
    if (!solver.step(ticks)) return false;
    separate(bodies, options.settle);
    for (const b of bodies) clampTo(b);
    const positions = new Map<string, LayoutPoint>();
    for (const b of bodies) positions.set(b.node.id, { x: b.x, y: b.y });
    out = { positions, free, ticks: solver.ticks() };
    return true;
  };
  const result = () => {
    if (!out) throw new Error('layout not finished: step it until it returns true');
    return out;
  };
  return { free, step, result };
};

/**
 * Lay the graph out to rest. Same input, same output./**
 * Lay the graph out to rest. Same input, same output.
 *
 * The solver is d3-force's model (many-body charge, collision, a pull to the anchor, springs on
 * the links, velocity decay and a cooling alpha) run headless, but it only integrates the free
 * nodes: fixed and pinned ones are obstacles that push and pull, never move, and cost nothing to
 * step. A tick is O(free × all); d3's own loop rebuilds a Barnes–Hut quadtree over every node
 * each tick, which at a few hundred nodes costs more than it saves (and an arrival would pay for
 * the whole graph). At rest early once nothing free moves a twentieth of a pixel a tick.
 */
export const layoutGraph = (
  nodes: readonly LayoutNode[],
  links: readonly LayoutLink[],
  options: LayoutOptions = {},
): LayoutResult => {
  const job = startLayout(nodes, links, options);
  job.step(Infinity);
  return job.result();
};

// ---- sector arrangement (#272) --------------------------------------------------------------

/** Below this canvas width the sectors leave their ring for a grid (phones, #272). */
export const COMPACT_WIDTH = 560;

export type SectorArrangementInput = {
  /** How many sectors. */
  count: number;
  /** The canvas, px. */
  width: number;
  height: number;
  /** A sector's largest body radius at full size (`sectorRadius.max`). */
  maxBody: number;
  /** Room a sector keeps beyond its body: its progress arc and a margin (the layout's `r` less the body). */
  ringRoom: number;
  /** Room the hub keeps around its centre (its collision radius). */
  hubRoom: number;
};

export type SectorArrangement = {
  /** `ring`: an ellipse round the hub (wide canvases); `grid`: rows above and below it (phones). */
  kind: 'ring' | 'grid';
  /** Each sector's fixed place, in input order, centred on the hub at the origin. */
  slots: LayoutPoint[];
  /** What sector bodies are scaled by (1 = `maxBody`). */
  scale: number;
  /**
   * The arrangement's half extent: places are stored relative to it, so a resize that keeps the
   * kind scales every place with the sectors.
   */
  radii: LayoutPoint;
  /** Grid only. */
  cols: number;
  rows: number;
};

/**
 * Where the sectors stand. Pure and deterministic: the canvas and the count decide everything,
 * never the data, so live updates move no sector (#192, #202, #221).
 *
 * - **Ring** (`width >= COMPACT_WIDTH`): an ellipse fitted to the canvas, the first sector at
 *   the top, leaving room for satellites outside it. Sectors shrink on small canvases.
 * - **Grid** (narrower, #272): the ring's six circles cannot share a phone's column without
 *   overlapping, so they stand in rows of up to three, half above the hub and half below it, with
 *   a band in the middle for the hub and the branches and pull requests forked from it, and a
 *   band above and below for open issues. Each sector's radius is the largest that fits its cell,
 *   so no two sectors (arcs included) can overlap at any width. A short last row is centred.
 */
export const arrangeSectors = (input: SectorArrangementInput): SectorArrangement => {
  const { count, width, height, maxBody, ringRoom, hubRoom } = input;
  if (width >= COMPACT_WIDTH || count === 0) {
    const scale = Math.max(0.6, Math.min(1, Math.min(width, height) / 620));
    const radii = {
      x: Math.max(100, width / 2 - 140 * scale),
      y: Math.max(100, height / 2 - 120 * scale),
    };
    const slots = Array.from({ length: count }, (_, i) => {
      const a = (i / count) * Math.PI * 2 - Math.PI / 2;
      return { x: Math.cos(a) * radii.x, y: Math.sin(a) * radii.y };
    });
    return { kind: 'ring', slots, scale, radii, cols: 0, rows: 0 };
  }
  const EDGE = 6; // canvas edge to the outermost arc
  const OUTER = 36; // band above the top row and below the bottom row (issues, agents)
  const MIDDLE = Math.max(hubRoom + 14, 56); // half the band through the hub (agents, branches)
  const cols = count <= 2 ? count : count <= 4 ? 2 : 3;
  const rows = Math.ceil(count / cols);
  const upper = Math.ceil(rows / 2);
  const lower = rows - upper;
  const tallest = Math.max(upper, lower);
  // A cell's half size: what one sector (body, arc, margin) may take.
  const cell = Math.max(
    ringRoom + 8,
    Math.min((width / 2 - EDGE) / cols, (height / 2 - EDGE - OUTER - MIDDLE) / (2 * tallest)),
  );
  const body = Math.min(maxBody, cell - ringRoom);
  const slots: LayoutPoint[] = [];
  for (let i = 0; i < count; i++) {
    const row = Math.floor(i / cols);
    const inRow = Math.min(cols, count - row * cols);
    const col = i % cols;
    const x = (col - (inRow - 1) / 2) * 2 * cell;
    // Rows above the hub count outwards from it; the first row is the top one.
    const y =
      row < upper
        ? -(MIDDLE + cell + 2 * cell * (upper - 1 - row))
        : MIDDLE + cell + 2 * cell * (row - upper);
    slots.push({ x, y });
  }
  return {
    kind: 'grid',
    slots,
    scale: body / maxBody,
    radii: { x: Math.max(cell, (cols - 1) * cell), y: MIDDLE + cell + 2 * cell * (tallest - 1) },
    cols,
    rows,
  };
};

/**
 * Nodes arriving on, leaving and moving across the live graph, as pure timing. The same easing
 * family as the radial intro (`intro.ts`), so the intro, arrivals, departures and moves read as
 * one system. Nothing here is physics: the layout engine (`layout.ts`) decides where a node
 * stands, and these tweens are the only way it gets there (#221). Every one, stagger included,
 * is over within `TRANSITION_MS`.
 *
 * Arriving: a node appears at its place, at 40% size and transparent, and grows and fades in
 * with an ease-out; its label follows just after the circle and its edges draw on from the
 * parent end.
 *
 * Leaving: the node's opacity goes to 0 and its radius to 60% in place, with an ease-in-out; its
 * label fades a little ahead of the circle, its edges thin and fade at the circle's rate. Only
 * then does it leave the graph. Nothing else moves into the room it leaves.
 *
 * Moving (a node the layout re-placed, or a resize re-fitting the canvas): a straight line from
 * where it stands to its new place with one ease-out cubic, so its distance to the target only
 * ever shrinks: no overshoot, no settling.
 */

import { easeOut } from './intro';

/** The longest any arrival, departure or move takes, its stagger included. */
export const TRANSITION_MS = 700;

export const ARRIVAL = {
  durationMs: 560,
  staggerMs: 35,
  /** Stagger steps at most; a big burst shares the last one. */
  maxSteps: 4,
  startScale: 0.4,
  /** The label starts once the circle is this far along. */
  labelLag: 0.25,
} as const;

export const DEPARTURE = {
  durationMs: 600,
  staggerMs: 25,
  maxSteps: 4,
  endScale: 0.6,
  /** The label is gone by this point of the circle's fade. */
  labelLead: 0.7,
} as const;

export const MOVE = {
  durationMs: 500,
} as const;

const clamp = (p: number) => Math.max(0, Math.min(1, p));

/** Ease-in-out cubic: a soft start and a soft landing. */
export const easeInOut = (p: number): number => {
  const x = clamp(p);
  return x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2;
};

/** When the i-th of a batch starts, in ms after the batch. */
export const staggerAt = (i: number, step: number, maxSteps: number) =>
  Math.min(i, maxSteps) * step;

/** Raw progress `t` ms after a tween that starts at `delay` and lasts `duration`. */
export const progressAt = (t: number, delay: number, duration: number) =>
  duration <= 0 ? (t >= delay ? 1 : 0) : clamp((t - delay) / duration);

export type Pose = {
  scale: number;
  opacity: number;
  label: number;
  /** Edge visibility: how much is drawn (arriving) or its opacity and width factor (leaving). */
  edge: number;
};

export const arrivalPose = (p: number): Pose => {
  const e = easeOut(p);
  return {
    scale: ARRIVAL.startScale + (1 - ARRIVAL.startScale) * e,
    opacity: e,
    label: easeOut((clamp(p) - ARRIVAL.labelLag) / (1 - ARRIVAL.labelLag)),
    edge: e,
  };
};

export const departurePose = (p: number): Pose => {
  const e = easeInOut(p);
  return {
    scale: 1 - (1 - DEPARTURE.endScale) * e,
    opacity: 1 - e,
    label: 1 - easeInOut(clamp(p) / DEPARTURE.labelLead),
    edge: 1 - e,
  };
};

/** A move `p` of the way along (0 → 1): how far from start to target, never past it. */
export const moveAt = (p: number): number => easeOut(p);

/** Where a moving node stands: on the straight line from `from` to `to`. */
export const movePoint = (
  from: { x: number; y: number },
  to: { x: number; y: number },
  p: number,
): { x: number; y: number } => {
  const k = moveAt(p);
  return { x: from.x + (to.x - from.x) * k, y: from.y + (to.y - from.y) * k };
};

/**
 * The swarm graph model. Pure and framework-free: it turns what a Rallypoint swarm already
 * records (agents and their roles, issues and the pull requests that deliver them, the events
 * agents log) into a graph that follows the protocol:
 *
 *   issue ──claim──▶ agent/<issue>-<slug> branch (forked from the integration branch, worked in
 *   a worktree) ──▶ pull request ──independent review──▶ merge into the integration branch,
 *   landing in the sector of the codebase the branch touched.
 *
 * Nothing reaches the integration branch except a merge. Nothing here knows about a particular
 * project: a host maps its own data onto these types and decides what a sector is (a directory,
 * a package, a label). The renderer in `render.ts` draws whatever this returns.
 */

/** The Rallypoint roles (`.rallypoint/roles/`). Hosts may add their own. */
export type SwarmRole =
  | 'worker'
  | 'reviewer'
  | 'merger'
  | 'fixer'
  | 'improver'
  | 'planner'
  | 'janitor'
  | 'tester'
  | 'orchestrator'
  | 'referee'
  | (string & {});

export type SwarmAgentStatus = 'working' | 'idle' | 'stopped';

/** A part of the codebase (paths in the integration branch) that work lands in. */
export type SwarmSector = {
  id: string;
  label: string;
  /** Any CSS colour; the renderer falls back to a neutral when absent. */
  color?: string;
  /** Repository paths the sector covers, for display only. */
  paths?: string[];
  /**
   * The number drawn inside the sector: a stable count the host reads from its own records (merged
   * pull requests, landed versions), not the effort of whatever events reached the model. Absent,
   * the renderer shows no number.
   */
  count?: SwarmCount | null;
};

/** A labelled all-time count with its recent part, e.g. 48 merged · 3 today. */
export type SwarmCount = {
  value: number;
  /** What the number counts, e.g. `merged`, `versions`. */
  unit: string;
  recent?: number | null;
  /** The recent window, e.g. `today`. */
  recentUnit?: string | null;
};

export type SwarmAgent = {
  id: string;
  label?: string;
  role: SwarmRole;
  /** `working` only while the session is live; a host marks stale seats idle. */
  status: SwarmAgentStatus;
  /** The sector the agent is in this session, if any. */
  sector: string | null;
  /** The work item (issue) the agent holds, if any. */
  workItem?: string | null;
  /** The pull request the agent is on (a reviewer's or merger's subject), if any. */
  pr?: number | null;
  /** One line: what the agent is doing this minute. */
  activity?: string | null;
  lastSeen: string;
};

/**
 * Where a work item is in the Rallypoint lifecycle; the same stages the protocol's labels give.
 * `backlog`/`held` are issues, `claimed` is a branch, `review`/`changes`/`approved` an open pull
 * request, `merged` landed on the integration branch, `closed` abandoned.
 */
export type SwarmStage =
  'backlog' | 'held' | 'claimed' | 'review' | 'changes' | 'approved' | 'merged' | 'closed';

/** How a stage is drawn: an issue, a branch in a worktree, a pull request, or landed code. */
export type SwarmPhase = 'issue' | 'branch' | 'pr' | 'landed';

export const phaseOf = (stage: SwarmStage): SwarmPhase | null => {
  switch (stage) {
    case 'backlog':
    case 'held':
      return 'issue';
    case 'claimed':
      return 'branch';
    case 'review':
    case 'changes':
    case 'approved':
      return 'pr';
    case 'merged':
      return 'landed';
    case 'closed':
      return null;
  }
};

/** One unit of work: a Rallypoint issue, its branch and, later, its pull request. */
export type SwarmWorkItem = {
  id: string;
  sector: string;
  title: string;
  stage: SwarmStage;
  issue?: number | null;
  pr?: number | null;
  /** The branch it is worked on, e.g. `agent/29-mcts-uct-with-random-eye-respecting`. */
  branch?: string | null;
  /** When it reached its current stage; orders the merged history. */
  at?: string | null;
};

/**
 * What an event means on the graph. Only `merge` moves work into the integration branch.
 * `result` is a measurement finishing (a game, a match), `rating` a score changing, `session` an
 * agent's session starting, changing step or ending, `post` something said on a discussion
 * board, `pr` a pull request opening or moving.
 */
export type SwarmEventKind =
  | 'plan'
  | 'claim'
  | 'progress'
  | 'review'
  | 'merge'
  | 'reject'
  | 'milestone'
  | 'protocol'
  | 'result'
  | 'rating'
  | 'session'
  | 'post'
  | 'pr';

/** How a measured result went for the sector's side. */
export type SwarmOutcome = 'win' | 'loss' | 'draw';

export type SwarmEvent = {
  id: string;
  at: string;
  kind: SwarmEventKind;
  agent: string | null;
  sector: string | null;
  workItem: string | null;
  title: string;
  /** A host's finer label for the event (what a filter or preset keys on). */
  sub?: string | null;
  /**
   * Events that belong to one burst (the games of one match, say) share a group, so a host can
   * show them as one updating line. `title` names the burst.
   */
  group?: { id: string; title: string } | null;
  outcome?: SwarmOutcome | null;
  /** A signed change the event carries (a rating delta). */
  delta?: number | null;
};

export type SwarmInput = {
  /** Rallypoint's `integrationBranch`: the trunk every branch forks from and merges into. */
  integrationBranch: string;
  sectors: SwarmSector[];
  agents: SwarmAgent[];
  workItems: SwarmWorkItem[];
  events: SwarmEvent[];
  /** The clock the snapshot was read at. */
  asOf: string;
};

export type SwarmGraphOptions = {
  /** Idle agents seen within this window stay on the graph (dimmed). Default 6 h. */
  recentAgentMs?: number;
  /** Merged work items kept per sector, newest first. Default 3. */
  mergedPerSector?: number;
  /** Keep idle agents that hold no work and logged no events (default false: they are noise). */
  showIdleWithoutEffort?: boolean;
  /** Effort weight per event kind. */
  weights?: Partial<Record<SwarmEventKind, number>>;
  /**
   * Drop dead nodes: ended agents, merged items and abandoned branches past their lifetime (see
   * `LIFETIMES`). Absent, nothing is pruned beyond `recentAgentMs` and `mergedPerSector`.
   */
  lifetimes?: SwarmLifetimes | null;
  /** The clock pruning is measured against (a live view ticks it). Default `input.asOf`. */
  now?: string | null;
  /**
   * The host's one liveness rule (#200): whether a seat that says `working` still is at `nowMs`
   * (a recent heartbeat). It is asked again at every `now`, so a seat that goes quiet while a live
   * view is open turns idle and the `lifetimes` take it off. Absent, a `working` status is trusted.
   * Either way, a seat whose work item has merged or closed is not working.
   */
  isLive?: ((agent: SwarmAgent, nowMs: number) => boolean) | null;
};

/**
 * How long a dead node stays on the graph. Sectors and the hub never leave. A node spends its
 * last `fadingMs` in a `fading` state (drawn dimmer) before it goes.
 */
export type SwarmLifetimes = {
  /** An ended or stale agent, from its last activity. */
  agentMs: number;
  /** A merged or closed work item, from when it closed. */
  closedMs: number;
  /** An open branch nobody has touched, from its last activity. */
  branchMs: number;
  fadingMs: number;
};

const MINUTE = 60_000;

/** Every pruning threshold in one table: the live views, and the longer-memoried `Everything`. */
export const LIFETIMES = {
  live: {
    agentMs: 10 * MINUTE,
    closedMs: 60 * MINUTE,
    branchMs: 60 * MINUTE,
    fadingMs: 3 * MINUTE,
  },
  everything: {
    agentMs: 6 * 60 * MINUTE,
    closedMs: 6 * 60 * MINUTE,
    branchMs: 6 * 60 * MINUTE,
    fadingMs: 10 * MINUTE,
  },
} as const satisfies Record<string, SwarmLifetimes>;

export type SwarmLife = 'alive' | 'fading' | 'gone';

/** Where a dead node is in its wind-down, `deadMs` after it died (stopped, closed, went quiet). */
export const lifeOf = (deadMs: number, lifetimeMs: number, fadingMs: number): SwarmLife => {
  if (!(deadMs <= lifetimeMs)) return 'gone';
  return deadMs > lifetimeMs - fadingMs ? 'fading' : 'alive';
};

export type SwarmNodeKind = 'hub' | 'sector' | 'work' | 'agent';

export type SwarmNode = {
  id: string;
  kind: SwarmNodeKind;
  label: string;
  color: string | null;
  /** Effort that landed on this node (sector, hub) or that this node spent (agent). */
  effort: number;
  /** Live agent, or a sector / work item a live agent is in. */
  active: boolean;
  /** Dead and about to leave the graph: drawn dimmer (see `SwarmLifetimes.fadingMs`). */
  fading?: boolean;
  /** For work nodes: how it is drawn. A node keeps its id as it moves through phases. */
  phase?: SwarmPhase;
  /** The original record, for tooltips and links. */
  sector?: SwarmSector;
  agent?: SwarmAgent;
  workItem?: SwarmWorkItem;
  /** For agent and work nodes: the sector they belong to. */
  sectorId?: string | null;
  /** For sectors: every work item aimed at it, by phase (closed ones left out). */
  tally?: SwarmTally;
};

/** Work items counted by phase: waiting issues, open branches and pull requests, merged. */
export type SwarmTally = {
  issue: number;
  branch: number;
  pr: number;
  landed: number;
  total: number;
};

const emptyTally = (): SwarmTally => ({ issue: 0, branch: 0, pr: 0, landed: 0, total: 0 });

export type SwarmLinkKind =
  /** sector — hub: the sector is a set of paths in the integration branch. */
  | 'trunk'
  /** issue → sector it asks to change. */
  | 'target'
  /** hub → branch / pull request: forked from the integration branch's tip. */
  | 'fork'
  /** branch / pull request → the sector whose paths it changes. */
  | 'scope'
  /** landed work → its sector. */
  | 'landed'
  /** agent → what it is on now (its branch, the pull request it reviews, or the hub). */
  | 'assignment'
  /** agent → a sector it has spent effort on, weighted by that effort. */
  | 'contribution';

export type SwarmLink = {
  id: string;
  kind: SwarmLinkKind;
  source: string;
  target: string;
  weight: number;
  active: boolean;
};

/** One event as a movement on the graph: along `path`, node by node. */
export type SwarmFlow = {
  id: string;
  at: string;
  kind: SwarmEventKind;
  title: string;
  sub: string | null;
  group: { id: string; title: string } | null;
  outcome: SwarmOutcome | null;
  delta: number | null;
  agent: string | null;
  sector: string | null;
  /** At least two node ids. A merge runs branch → integration branch → sector. */
  path: string[];
  weight: number;
};

export type SwarmGraph = {
  hubId: string;
  nodes: SwarmNode[];
  links: SwarmLink[];
  /** Events in time order, each resolved to the nodes its effort moves between. */
  flows: SwarmFlow[];
  totals: {
    effort: number;
    live: number;
    agents: number;
    sectors: number;
    branches: number;
    pullRequests: number;
    /** Every work item by stage, merged history included, for a progress bar. */
    stages: Record<SwarmStage, number>;
  };
};

export const DEFAULT_WEIGHTS: Record<SwarmEventKind, number> = {
  plan: 0.5,
  claim: 1,
  progress: 1,
  review: 1,
  merge: 3,
  reject: 1,
  milestone: 2,
  protocol: 1,
  // Frequent and small: a gate plays dozens of games, a session heartbeats.
  result: 0.1,
  rating: 1,
  session: 0.2,
  post: 0.3,
  pr: 0.5,
};

/** Rallypoint's branch slug (`.rallypoint/scripts/lib/claim.mjs`), so names match the real ones. */
export const branchSlug = (title: string) =>
  title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 42);

/** The branch `claim.mjs` prescribes for an issue: `<branchPrefix><issue>-<slug>`. */
export const rallypointBranch = (issue: number, title: string, branchPrefix = 'agent/') =>
  `${branchPrefix}${issue}-${branchSlug(title)}`;

const HOUR = 3_600_000;

export const hubNodeId = (branch: string) => `hub:${branch}`;
export const sectorNodeId = (id: string) => `sector:${id}`;
export const workNodeId = (id: string) => `work:${id}`;
export const agentNodeId = (id: string) => `agent:${id}`;

/** Roles that work inside a branch's worktree. */
const BRANCH_ROLES = new Set(['worker', 'fixer', 'improver', 'janitor', 'tester']);
/** Roles that act on an open pull request. */
const GATE_ROLES = new Set(['reviewer', 'merger']);

/** Build the graph a renderer draws. Deterministic: the same input gives the same graph. */
export const buildSwarmGraph = (input: SwarmInput, options: SwarmGraphOptions = {}): SwarmGraph => {
  const recentMs = options.recentAgentMs ?? 6 * HOUR;
  const mergedPerSector = options.mergedPerSector ?? 3;
  const weights = { ...DEFAULT_WEIGHTS, ...options.weights };
  const now = Date.parse(options.now ?? input.asOf);
  const life = options.lifetimes ?? null;
  const fading = new Set<string>();
  const hubId = hubNodeId(input.integrationBranch);

  const sectors = new Map(input.sectors.map((s) => [s.id, s]));
  const items = new Map(input.workItems.map((w) => [w.id, w]));
  // Working means said and still true now: live by the host's rule, on work that is still open.
  // Everyone else is idle from here on, and the lifetime rules below apply to them.
  const finished = (a: SwarmAgent) => {
    const stage = a.workItem ? items.get(a.workItem)?.stage : undefined;
    return stage === 'merged' || stage === 'closed';
  };
  const stillWorking = (a: SwarmAgent) =>
    a.status === 'working' && (options.isLive?.(a, now) ?? true) && !finished(a);
  const inputAgents = input.agents.map((a): SwarmAgent =>
    a.status === 'working' && !stillWorking(a) ? { ...a, status: 'idle' } : a,
  );
  const agents = new Map(inputAgents.map((a) => [a.id, a]));
  const events = [...input.events].sort(
    (a, b) => a.at.localeCompare(b.at) || a.id.localeCompare(b.id),
  );

  const sectorOfEvent = (e: SwarmEvent) => {
    const s = e.sector ?? (e.workItem ? items.get(e.workItem)?.sector : null) ?? null;
    return s && sectors.has(s) ? s : null;
  };

  // Effort per sector, per agent, and per (agent, sector). Only merges count for the trunk.
  const sectorEffort = new Map<string, number>();
  const agentEffort = new Map<string, number>();
  const pairEffort = new Map<string, Map<string, number>>();
  let hubEffort = 0;
  let total = 0;
  const lastEventAt = new Map<string, string>();
  for (const e of events) {
    const w = weights[e.kind];
    total += w;
    const s = sectorOfEvent(e);
    if (s) sectorEffort.set(s, (sectorEffort.get(s) ?? 0) + w);
    if (e.kind === 'merge') hubEffort += w;
    if (e.agent) {
      agentEffort.set(e.agent, (agentEffort.get(e.agent) ?? 0) + w);
      lastEventAt.set(e.agent, e.at);
      if (s) {
        const m = pairEffort.get(e.agent) ?? new Map<string, number>();
        m.set(s, (m.get(s) ?? 0) + w);
        pairEffort.set(e.agent, m);
      }
    }
  }

  // Agents on the graph: live ones, idle ones seen recently that did something, and event-only
  // actors (a referee that never registers a seat) that acted recently.
  // With lifetimes, an agent that is not working leaves `agentMs` after its last activity.
  const shown = new Map<string, SwarmAgent>();
  const keepIdle = (id: string, seen: number) => {
    if (now - seen > recentMs) return false;
    if (!life) return true;
    const state = lifeOf(now - seen, life.agentMs, life.fadingMs);
    if (state === 'fading') fading.add(agentNodeId(id));
    return state !== 'gone';
  };
  for (const a of inputAgents) {
    const seen = Math.max(Date.parse(a.lastSeen), Date.parse(lastEventAt.get(a.id) ?? '') || 0);
    const idleNoise = !a.workItem && !agentEffort.has(a.id) && !options.showIdleWithoutEffort;
    if (a.status === 'working' || (!idleNoise && keepIdle(a.id, seen))) shown.set(a.id, a);
  }
  for (const [id, at] of lastEventAt) {
    if (agents.has(id) || !keepIdle(id, Date.parse(at))) continue;
    shown.set(id, { id, role: id, status: 'idle', sector: null, lastSeen: at });
  }

  // Progress: every work item counted once, by sector and by stage.
  const tallies = new Map(input.sectors.map((s) => [s.id, emptyTally()]));
  const stages: Record<SwarmStage, number> = {
    backlog: 0,
    held: 0,
    claimed: 0,
    review: 0,
    changes: 0,
    approved: 0,
    merged: 0,
    closed: 0,
  };
  for (const w of input.workItems) {
    if (!sectors.has(w.sector)) continue;
    stages[w.stage]++;
    const phase = phaseOf(w.stage);
    const t = tallies.get(w.sector);
    if (!phase || !t) continue;
    t[phase]++;
    t.total++;
  }

  // Work items: every open issue, branch and pull request, plus the newest merged per sector.
  // With lifetimes, merged work leaves `closedMs` after it merged and a branch nobody is in leaves
  // `branchMs` after its last activity (its stage change, an event on it, a seat holding it).
  const itemActivity = new Map<string, number>();
  const touch = (id: string | null | undefined, at: string) => {
    const t = Date.parse(at);
    if (id && t > (itemActivity.get(id) ?? -Infinity)) itemActivity.set(id, t);
  };
  for (const e of events) touch(e.workItem, e.at);
  const heldLive = new Set<string>();
  for (const a of inputAgents) {
    if (a.workItem) touch(a.workItem, a.lastSeen);
    if (a.workItem && a.status === 'working') heldLive.add(a.workItem);
  }
  const survives = (w: SwarmWorkItem, phase: SwarmPhase) => {
    if (!life || (phase !== 'landed' && phase !== 'branch')) return true;
    if (phase === 'branch' && heldLive.has(w.id)) return true;
    const at = Math.max(Date.parse(w.at ?? '') || -Infinity, itemActivity.get(w.id) ?? -Infinity);
    const state = lifeOf(
      now - (phase === 'landed' ? Date.parse(w.at ?? '') : at),
      phase === 'landed' ? life.closedMs : life.branchMs,
      life.fadingMs,
    );
    if (state === 'fading') fading.add(workNodeId(w.id));
    return state !== 'gone';
  };
  const kept: SwarmWorkItem[] = [];
  const mergedBySector = new Map<string, SwarmWorkItem[]>();
  for (const w of input.workItems) {
    const phase = phaseOf(w.stage);
    if (!phase || !sectors.has(w.sector) || !survives(w, phase)) continue;
    if (phase !== 'landed') kept.push(w);
    else mergedBySector.set(w.sector, [...(mergedBySector.get(w.sector) ?? []), w]);
  }
  for (const list of mergedBySector.values())
    kept.push(
      ...list
        .sort((a, b) => (b.at ?? '').localeCompare(a.at ?? '') || a.id.localeCompare(b.id))
        .slice(0, mergedPerSector),
    );
  const keptById = new Map(kept.map((w) => [w.id, w]));
  const byPr = new Map(kept.filter((w) => w.pr).map((w) => [w.pr!, w]));

  const agentSector = (a: SwarmAgent) => {
    const s = a.sector ?? (a.workItem ? items.get(a.workItem)?.sector : null) ?? null;
    return s && sectors.has(s) ? s : null;
  };

  /** Where an agent is right now, by role: its branch, the pull request it gates, or the hub. */
  const placeOf = (a: SwarmAgent): string => {
    const own = a.workItem ? keptById.get(a.workItem) : undefined;
    const onPr = a.pr ? byPr.get(a.pr) : undefined;
    const open = (w?: SwarmWorkItem) =>
      w && (phaseOf(w.stage) === 'branch' || phaseOf(w.stage) === 'pr');
    if (GATE_ROLES.has(a.role)) {
      const subject = onPr ?? own;
      if (subject && phaseOf(subject.stage) === 'pr') return workNodeId(subject.id);
      return hubId;
    }
    if (BRANCH_ROLES.has(a.role)) {
      if (open(own)) return workNodeId(own!.id);
      if (open(onPr)) return workNodeId(onPr!.id);
      const s = agentSector(a);
      return s ? sectorNodeId(s) : hubId;
    }
    if (a.role === 'planner') return hubId;
    if (open(own)) return workNodeId(own!.id);
    const s = agentSector(a);
    return s ? sectorNodeId(s) : hubId;
  };

  const places = new Map([...shown.values()].map((a) => [a.id, placeOf(a)]));
  const liveTargets = new Set<string>();
  const liveSectors = new Set<string>();
  for (const a of shown.values()) {
    if (a.status !== 'working') continue;
    const target = places.get(a.id)!;
    liveTargets.add(target);
    const s = agentSector(a);
    if (s) liveSectors.add(s);
  }

  const nodes: SwarmNode[] = [
    {
      id: hubId,
      kind: 'hub',
      label: input.integrationBranch,
      color: null,
      effort: hubEffort,
      active: false,
    },
  ];
  const links: SwarmLink[] = [];

  for (const s of input.sectors) {
    const id = sectorNodeId(s.id);
    nodes.push({
      id,
      kind: 'sector',
      label: s.label,
      color: s.color ?? null,
      effort: sectorEffort.get(s.id) ?? 0,
      active: liveSectors.has(s.id),
      sector: s,
      sectorId: s.id,
      tally: tallies.get(s.id),
    });
    links.push({
      id: `trunk:${s.id}`,
      kind: 'trunk',
      source: id,
      target: hubId,
      weight: sectorEffort.get(s.id) ?? 0,
      active: false,
    });
  }

  let branches = 0;
  let pullRequests = 0;
  for (const w of kept) {
    const id = workNodeId(w.id);
    const phase = phaseOf(w.stage)!;
    const active = liveTargets.has(id);
    const sid = sectorNodeId(w.sector);
    if (phase === 'branch') branches++;
    if (phase === 'pr') pullRequests++;
    nodes.push({
      id,
      kind: 'work',
      phase,
      label:
        phase === 'issue' || phase === 'landed'
          ? w.title
          : phase === 'pr' && w.pr
            ? `#${w.pr}`
            : (w.branch ?? w.title),
      color: sectors.get(w.sector)?.color ?? null,
      effort: 0,
      active,
      ...(fading.has(id) ? { fading: true } : {}),
      workItem: w,
      sectorId: w.sector,
    });
    if (phase === 'issue')
      links.push({
        id: `target:${w.id}`,
        kind: 'target',
        source: id,
        target: sid,
        weight: 1,
        active: false,
      });
    else if (phase === 'landed')
      links.push({
        id: `landed:${w.id}`,
        kind: 'landed',
        source: id,
        target: sid,
        weight: 1,
        active: false,
      });
    else {
      links.push({
        id: `fork:${w.id}`,
        kind: 'fork',
        source: hubId,
        target: id,
        weight: 1,
        active,
      });
      links.push({
        id: `scope:${w.id}`,
        kind: 'scope',
        source: id,
        target: sid,
        weight: 1,
        active: false,
      });
    }
  }

  for (const a of [...shown.values()].sort((x, y) => x.id.localeCompare(y.id))) {
    const id = agentNodeId(a.id);
    const s = agentSector(a);
    const live = a.status === 'working';
    const target = places.get(a.id)!;
    nodes.push({
      id,
      kind: 'agent',
      label: a.label ?? a.id,
      color: s ? (sectors.get(s)?.color ?? null) : null,
      effort: agentEffort.get(a.id) ?? 0,
      active: live,
      ...(fading.has(id) ? { fading: true } : {}),
      agent: a,
      sectorId: s,
    });
    links.push({
      id: `assign:${a.id}`,
      kind: 'assignment',
      source: id,
      target,
      weight: 1,
      active: live,
    });
    for (const [sec, w] of pairEffort.get(a.id) ?? []) {
      if (target === sectorNodeId(sec)) continue;
      links.push({
        id: `contrib:${a.id}:${sec}`,
        kind: 'contribution',
        source: id,
        target: sectorNodeId(sec),
        weight: w,
        active: false,
      });
    }
  }

  const nodeIds = new Set(nodes.map((n) => n.id));
  const flows: SwarmFlow[] = [];
  for (const e of events) {
    const s = sectorOfEvent(e);
    const sectorNode = s ? sectorNodeId(s) : null;
    const itemNode = e.workItem && keptById.has(e.workItem) ? workNodeId(e.workItem) : null;
    const agentNode = e.agent && nodeIds.has(agentNodeId(e.agent)) ? agentNodeId(e.agent) : null;
    const actor = agentNode ?? hubId;
    let path: (string | null)[];
    switch (e.kind) {
      case 'merge':
        // The only way into the integration branch: the branch merges, the code lands in its sector.
        path = [itemNode ?? agentNode, hubId, sectorNode];
        break;
      case 'claim':
        // The claim prescribes a branch at the integration branch's tip.
        path = [hubId, itemNode ?? sectorNode];
        break;
      case 'plan':
        path = [actor, itemNode ?? sectorNode ?? hubId];
        break;
      case 'result':
      case 'rating':
        // Measured on the branch when there is one, otherwise on what the sector ships.
        path = itemNode ? [actor, itemNode] : [agentNode ?? hubId, sectorNode];
        break;
      case 'milestone':
        // Gate matches measure a branch; rungs are cleared by what is on the integration branch.
        path = itemNode ? [actor, itemNode] : [hubId, sectorNode];
        break;
      default:
        path = [actor, itemNode ?? sectorNode ?? hubId];
    }
    const clean = path.filter((p): p is string => Boolean(p));
    const deduped = clean.filter((p, i) => i === 0 || p !== clean[i - 1]!);
    if (deduped.length < 2) continue;
    flows.push({
      id: e.id,
      at: e.at,
      kind: e.kind,
      title: e.title,
      sub: e.sub ?? null,
      group: e.group ?? null,
      outcome: e.outcome ?? null,
      delta: e.delta ?? null,
      agent: e.agent,
      sector: s,
      path: deduped,
      weight: weights[e.kind],
    });
  }

  return {
    hubId,
    nodes,
    links,
    flows,
    totals: {
      effort: total,
      live: [...shown.values()].filter((a) => a.status === 'working').length,
      agents: shown.size,
      sectors: input.sectors.length,
      branches,
      pullRequests,
      stages,
    },
  };
};

/**
 * The swarm graph renderer: plain D3 on an SVG, no framework. Positions come from an off-screen
 * layout engine (`layout.ts`), computed to rest before anything is drawn; the renderer only tweens
 * each node from where it stands to its place, never with physics on screen (#221). A host calls
 * `update()` with every new snapshot (a realtime push, a poll): what was already there stays put,
 * new nodes fade in at their place, and only nodes whose placement changed glide to their new one.
 *
 * Effort is drawn as motion: live agents stream particles into the work they hold, work flows
 * into its sector, sectors feed the integration branch, and every new event fires a spark from
 * whoever logged it to where it landed. `replay()` plays a planned window of the event history
 * back (see `replay.ts`), from the state the graph had when that window opened.
 */
import * as d3 from 'd3';
import type { SwarmAgent, SwarmFlow, SwarmGraph, SwarmLink, SwarmNode, SwarmStage } from './model';
import {
  FULL_INTRO,
  SHORT_INTRO,
  easeOut,
  introCamera,
  introEdge,
  introLabels,
  introPose,
  planIntro,
  type IntroPlan,
} from './intro';
import {
  ARRIVAL,
  DEPARTURE,
  MOVE,
  arrivalPose,
  departurePose,
  movePoint,
  progressAt,
  staggerAt,
  type Pose,
} from './lifecycle';
import {
  arrangeSectors,
  startLayout,
  type LayoutJob,
  type SectorArrangement,
  type LayoutLink,
  type LayoutNode,
  type LayoutPoint,
} from './layout';
import {
  applyFlow,
  indexAtTime,
  parkedAtEnd,
  planReplay,
  seekIndex,
  seekOffset,
  sparksAt,
  stateAt,
  stepPlayhead,
  type SwarmReplayPlan,
  type SwarmReplaySnapshot,
} from './replay';
import { beamTier, createBeamGate } from './beams';

export type SwarmGraphTheme = {
  fg: string;
  fgMuted: string;
  fgFaint: string;
  line: string;
  lineStrong: string;
  panel: string;
  panelRaised: string;
  /** Colour for nodes whose sector has none. */
  neutral: string;
  good: string;
  warning: string;
  critical: string;
  font: string;
  monoFont: string;
};

export type SwarmReplayState = {
  /** Time of the last event played (the window's start before any has). */
  at: string;
  /** Events played so far. */
  index: number;
  total: number;
  playing: boolean;
  speed: number;
  /**
   * The viewer left the playhead at the end by hand (paused, then seeked there): the replay holds
   * there until played again or stopped. One that plays to its end goes back to live instead.
   */
  done: boolean;
  /** The state at the playhead: seed plus the events played. */
  snapshot: SwarmReplaySnapshot;
  /** The real length of the idle pause just crossed, if the last event followed one. */
  gapMs: number | null;
};

/**
 * What an event did when it landed, for a host's effects layer: `merge`, `rating` (a rating
 * changed: `delta` says by how much), `rung` (a ladder rung cleared), `milestone` (any other),
 * `bury` (an idea abandoned: shown gently, never as an alarm), `reject` (changes asked), `pass`
 * (a spark crossed a node on its way). `clear` means the replay jumped: drop what is in flight.
 */
export type SwarmEffectKind =
  'merge' | 'rating' | 'rung' | 'milestone' | 'bury' | 'reject' | 'pass' | 'clear';

export type SwarmEffect = {
  kind: SwarmEffectKind;
  /** Where it happened (empty for `clear`). */
  nodeId: string;
  color: string;
  delta: number | null;
  source: 'live' | 'replay';
  flow: SwarmFlow | null;
};

/** A node as an effects layer reads it each frame: graph coordinates, radius, colour. */
export type SwarmNodeView = SwarmNode & { x?: number; y?: number; r: number };

/** The graph's camera for an effects layer: screen px = size / 2 + (x, y) + k · graph. */
export type SwarmViewport = {
  width: number;
  height: number;
  x: number;
  y: number;
  k: number;
  /** The viewer has panned or zoomed away from the fitted view. */
  moved: boolean;
};

/** Where an anchored host element sits: beside its node, or over it as its bounding square. */
export type SwarmAnchorPlacement = 'beside' | 'inside';

export type SwarmGraphRendererOptions = {
  theme?: Partial<SwarmGraphTheme>;
  /** Turns off ambient motion; event sparks and replay still show, without particles. */
  reducedMotion?: boolean;
  /** Pointer over a node (`null` when it leaves). `point` is relative to the container. */
  onHover?: (node: SwarmNode | null, point: { x: number; y: number } | null) => void;
  onSelect?: (node: SwarmNode) => void;
  /** A new event reached the graph (live) or was played back (replay). */
  onFlow?: (flow: SwarmFlow, source: 'live' | 'replay') => void;
  /**
   * The replay's state on every change; `null` once it is over. `ended` says why: `'end'` when it
   * played to its end and the graph went back to live on its own, `'stop'` when it was stopped.
   */
  onReplay?: (state: SwarmReplayState | null, ended?: 'end' | 'stop') => void;
  /** An event landed (or a spark crossed a node): for a host's particle layer. */
  onEffect?: (effect: SwarmEffect) => void;
  /**
   * What a landed event is, for its payoff. The default knows the model's kinds (merge,
   * milestone, rating, reject); a host refines it (a rung cleared, an idea buried).
   */
  effectOf?: (flow: SwarmFlow) => SwarmEffectKind | null;
  /**
   * How the first render appears: `full` unfolds the graph radially from the hub (about 1.4 s),
   * `short` plays a quicker version (about 0.5 s, for coming back to the page), `none` shows the
   * settled layout at once. Reduced motion always means `none`. Later updates never replay it.
   */
  intro?: 'full' | 'short' | 'none';
  /** Accessible name for the SVG. */
  title?: string;
  /**
   * A sector's radius in graph units at full size, from no effort (`min`) to the most (`max`).
   * Default 18 to 48. A host that draws a sector's information inside it (`anchor(…, 'inside')`)
   * raises it so the text fits. Narrow canvases scale it down.
   */
  sectorRadius?: { min: number; max: number };
  /**
   * Each agent's own icon (#200), drawn inside its node instead of the role letter: one path in a
   * `0 0 size size` box, and its name for the accessible label. The role stays on the sub-line,
   * in the hover card and in the label. Absent (or `null` for an agent), the letter is drawn.
   */
  agentIcon?: (agent: SwarmAgent) => SwarmAgentIcon | null;
};

/** An agent's icon: a single SVG path in a `0 0 size size` box. */
export type SwarmAgentIcon = { d: string; name: string; size: number };

export type SwarmUpdateOptions = {
  /**
   * Take the new graph without firing its unseen events: a host that changes which events it
   * shows (a filter) passes this so the newly visible history does not spark as if it were new.
   */
  quiet?: boolean;
  /**
   * The same data seen another way (a preset switch). Every update now keeps the nodes shown
   * before and after where they are (the layout pins them), so this only documents intent.
   */
  view?: boolean;
};

export type SwarmGraphRenderer = {
  update: (graph: SwarmGraph, options?: SwarmUpdateOptions) => void;
  /**
   * Pin a host element to a node: every frame the renderer sets its CSS `transform` (from the
   * container's top left, zoom and pan included). `beside` (the default) puts it beside the node
   * on the side away from the centre, inside the canvas, and sets `data-side` to `left` or
   * `right`. `inside` makes it the node's bounding square (`width` = `height` = the node's
   * diameter on screen, `--node-r` its radius in px), so a host draws the node's information in
   * its circle; the renderer then draws no name, sub-line or count of its own for that node, and
   * keeps edges from showing through its body. It is hidden while the node is not on the graph.
   * `null` releases it.
   */
  anchor: (nodeId: string, el: HTMLElement | null, placement?: SwarmAnchorPlacement) => void;
  /**
   * Play a planned replay (`planReplay`), or the whole history over `durationMs` (default 30 s).
   * The graph starts from the plan's seed state and ends at the live state.
   */
  replay: (plan?: SwarmReplayPlan | number) => void;
  stopReplay: () => void;
  /** Pause or resume the running replay. */
  setPlaying: (playing: boolean) => void;
  setSpeed: (speed: number) => void;
  /** Jump to the state after `index` events have played, and continue from there. */
  seek: (index: number) => void;
  /** Jump to a playback offset (ms) on the plan's schedule. */
  seekTime: (ms: number) => void;
  /** The playhead's offset (ms) on the plan's schedule, for a host animating a scrubber. */
  replayClock: () => number | null;
  /**
   * Emphasise a node as if the pointer were on it, from outside the graph (a list item the
   * host links to it, say). `null` clears it. Does not call `onHover`, so hosts can mirror the
   * graph's hover into their own UI and back without a loop.
   */
  highlight: (nodeId: string | null) => void;
  /** Recentre and reset zoom. */
  reset: () => void;
  /** The camera, for an effects layer drawing in the same space (one reused object). */
  viewport: () => SwarmViewport;
  /** Every node with its position this frame. */
  eachNode: (fn: (node: SwarmNodeView) => void) => void;
  /**
   * Every beam in flight: its head this frame, colour and size. `big` marks the few beams that
   * carry a big moment (a merge, a rung cleared, a rating jump): the only ones allowed to glow.
   * Ambient effort streams are not beams and are not reported.
   */
  eachSpark: (
    fn: (x: number, y: number, color: string, size: number, big: boolean) => void,
  ) => void;
  /** A node's position and radius this frame, or null. */
  nodeAt: (id: string) => SwarmNodeView | null;
  /**
   * A GPU layer draws the trails and bursts: the SVG keeps spark heads, ripples and words but
   * stops drawing its own comet tails and spark bursts, so the two do not double up.
   */
  setLayered: (on: boolean) => void;
  destroy: () => void;
};

/** The model's own reading of what an event is; hosts refine it with `effectOf`. */
export const defaultEffectOf = (f: SwarmFlow): SwarmEffectKind | null =>
  f.kind === 'merge'
    ? 'merge'
    : f.kind === 'milestone'
      ? 'milestone'
      : f.kind === 'rating' && f.delta
        ? 'rating'
        : f.kind === 'reject'
          ? 'reject'
          : null;

/** How long a spark takes per hop, by what it carries: payoffs travel fast, chores unhurried. */
const STEP_MS: Partial<Record<SwarmFlow['kind'], number>> = {
  merge: 650,
  rating: 620,
  milestone: 680,
  reject: 1000,
  plan: 1050,
  claim: 950,
  session: 1000,
  post: 1000,
};

/** Reads the host's CSS variables by default, so the graph follows the page's theme. */
export const DEFAULT_THEME: SwarmGraphTheme = {
  fg: 'var(--fg, #f4f4f6)',
  fgMuted: 'var(--fg-2, #c3c5cc)',
  fgFaint: 'var(--fg-3, #9a9ca6)',
  line: 'var(--line, #34363d)',
  lineStrong: 'var(--line-strong, #474a52)',
  panel: 'var(--panel, #1b1c20)',
  panelRaised: 'var(--panel-raised, #222328)',
  neutral: 'var(--fg-3, #9a9ca6)',
  good: 'var(--good, #0ca30c)',
  warning: 'var(--warning, #fab219)',
  critical: 'var(--critical, #d03b3b)',
  font: 'var(--font-sans, ui-sans-serif, system-ui, sans-serif)',
  monoFont: 'var(--font-mono, ui-monospace, monospace)',
};

/** A node as drawn: `x`/`y` is where it stands this frame (mid-tween, or at its place). */
type SimNode = SwarmNode & { x?: number; y?: number; r: number; ring?: { x: number; y: number } };
type SimLink = Omit<SwarmLink, 'source' | 'target'> & {
  source: SimNode;
  target: SimNode;
};

type Particle = {
  key: number;
  from: SimNode;
  to: SimNode;
  start: number;
  duration: number;
  color: string;
  size: number;
  spark: boolean;
  /** A big moment's beam: a touch brighter, and the only one with a glow. */
  big?: boolean;
  /** The beam's colour, desaturated a little so it reads as a hint of movement. */
  tone?: string;
  onArrive?: () => void;
};

type Ripple = { key: number; node: SimNode; start: number; color: string; big?: boolean };

/** A spark thrown out of a node when work lands there; merges throw the most. */
type Burst = {
  key: number;
  node: SimNode;
  start: number;
  angle: number;
  dist: number;
  size: number;
  color: string;
};

/** A word that rises off a node and fades: "+merged", "approved". */
type Floater = { key: number; node: SimNode; start: number; text: string; color: string };

const SVG_NS = 'http://www.w3.org/2000/svg';
/** Width of the panel-coloured stroke behind label text: wide enough to mask a line through it. */
const LABEL_HALO = 5;
const AMBIENT_MS = 1500;
const RIPPLE_MS = 900;
const BURST_MS = 1100;
const FLOAT_MS = 1600;
/** Head-to-tail length of a beam's short fading tail, as a fraction of the link. */
const TRAIL = 0.1;
/** A beam's line width at 1× zoom, px: thin, so beams never cover labels. */
const BEAM_WIDTH = 1.25;
const BIG_BEAM_WIDTH = 1.6;
/** A beam's head radius: no larger than a small node dot. */
const BEAM_HEAD = 1.8;
const BIG_BEAM_HEAD = 2.4;
/** Peak opacity; a beam fades out over the last third of its flight. */
const BEAM_ALPHA = 0.42;
const BIG_BEAM_ALPHA = 0.6;
/** Opacity over a beam's flight `t` ∈ [0, 1]: full, then fading over the last third. */
const beamFade = (t: number) => (t < 2 / 3 ? 1 : Math.max(0, (1 - t) * 3));

/** How far along the protocol an open work item is, for the arc around it. */
const STAGE_PROGRESS: Partial<Record<SwarmStage, number>> = {
  claimed: 0.25,
  review: 0.5,
  changes: 0.5,
  approved: 0.75,
};

const arcPath = (r0: number, r1: number, from: number, to: number) =>
  to - from <= 0.0005
    ? ''
    : (d3.arc().cornerRadius((r1 - r0) / 2)({
        innerRadius: r0,
        outerRadius: r1,
        startAngle: from * Math.PI * 2,
        endAngle: Math.min(1, to) * Math.PI * 2,
      }) ?? '');

const ROLE_GLYPH: Record<string, string> = {
  worker: 'W',
  reviewer: 'R',
  merger: 'M',
  fixer: 'F',
  improver: 'I',
  planner: 'P',
  janitor: 'J',
  tester: 'T',
  orchestrator: 'O',
  referee: '⚖',
};

const hash = (s: string) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
};

/** Quadratic curve between two nodes; the bend is fixed per pair so links and particles agree. */
const control = (a: SimNode, b: SimNode) => {
  const ax = a.x ?? 0;
  const ay = a.y ?? 0;
  const bx = b.x ?? 0;
  const by = b.y ?? 0;
  const dx = bx - ax;
  const dy = by - ay;
  const [p, q] = a.id < b.id ? [a.id, b.id] : [b.id, a.id];
  const sign = hash(p + q) % 2 ? 1 : -1;
  const flip = a.id < b.id ? 1 : -1;
  const bend = 0.14 * sign * flip;
  return {
    ax,
    ay,
    bx,
    by,
    cx: (ax + bx) / 2 - dy * bend,
    cy: (ay + by) / 2 + dx * bend,
  };
};

const curvePath = (a: SimNode, b: SimNode) => {
  const { ax, ay, bx, by, cx, cy } = control(a, b);
  return `M${ax},${ay}Q${cx},${cy} ${bx},${by}`;
};

const pointAt = (a: SimNode, b: SimNode, t: number) => {
  const { ax, ay, bx, by, cx, cy } = control(a, b);
  const u = 1 - t;
  return {
    x: u * u * ax + 2 * u * t * cx + t * t * bx,
    y: u * u * ay + 2 * u * t * cy + t * t * by,
  };
};

/**
 * Sector size range (#221): bounded, so the largest sector is at most about 1.6× the smallest. A
 * sector's count is drawn as text, not area; size only hints at effort.
 */
const SECTOR_RADIUS = { min: 26, max: 40 };
/** Room a sector keeps beyond its body for its progress arc (out to r + 8.5) and a margin. */
const SECTOR_ROOM = 12;
/** No node label, sub-line or glyph is drawn smaller than this at the default zoom (px). */
export const MIN_LABEL_PX = 11;

const radiusOf = (n: SwarmNode, effort: number, scale = 1, sector = SECTOR_RADIUS) => {
  switch (n.kind) {
    case 'hub':
      return 26;
    case 'sector':
      // Grows with effort, inside the bounded range (the default: 26 to 40).
      return (
        (sector.min + (sector.max - sector.min) * Math.min(1, (Math.sqrt(effort) * 2.6) / 30)) *
        scale
      );
    case 'work':
      // Big enough to hit and to read (#221): never a dot.
      return n.phase === 'pr' || n.phase === 'branch' ? 10 : n.phase === 'issue' ? 8 : 7;
    case 'agent':
      // Room for a 16–20 px icon in the circle (#200).
      return n.active ? 14 : 12;
  }
};

/** Node bodies: circles, except a branch (diamond) and a pull request (rounded square). */
const bodyPath = (n: SwarmNode, r: number) => {
  if (n.kind === 'work' && n.phase === 'branch') {
    const d = r * 1.2;
    return `M0,${-d}L${d},0L0,${d}L${-d},0Z`;
  }
  if (n.kind === 'work' && n.phase === 'pr') {
    const h = r * 0.95;
    const c = Math.min(3, h / 3);
    return `M${-h + c},${-h}H${h - c}Q${h},${-h} ${h},${-h + c}V${h - c}Q${h},${h} ${h - c},${h}H${-h + c}Q${-h},${h} ${-h},${h - c}V${-h + c}Q${-h},${-h} ${-h + c},${-h}Z`;
  }
  return `M${-r},0a${r},${r} 0 1,0 ${2 * r},0a${r},${r} 0 1,0 ${-2 * r},0`;
};

const STAGE_LABEL: Record<SwarmStage, string> = {
  backlog: 'issue',
  held: 'held',
  claimed: 'branch',
  review: 'in review',
  changes: 'changes asked',
  approved: 'approved',
  merged: 'merged',
  closed: 'closed',
};

const shortLabel = (s: string, max = 26) => (s.length > max ? `${s.slice(0, max - 1)}…` : s);

export const createSwarmGraph = (
  container: HTMLElement,
  options: SwarmGraphRendererOptions = {},
): SwarmGraphRenderer => {
  const theme = { ...DEFAULT_THEME, ...options.theme };
  const motion = !options.reducedMotion;
  /** Icons are looked up once per agent id: the host's mapping is pure. */
  const iconCache = new Map<string, SwarmAgentIcon | null>();
  const iconOf = (n: SwarmNode) => {
    if (n.kind !== 'agent' || !n.agent || !options.agentIcon) return null;
    if (!iconCache.has(n.agent.id)) iconCache.set(n.agent.id, options.agentIcon(n.agent));
    return iconCache.get(n.agent.id) ?? null;
  };

  let width = Math.max(200, container.clientWidth);
  let height = Math.max(200, container.clientHeight);

  const svg = d3
    .select(container)
    .append('svg')
    .attr('xmlns', SVG_NS)
    .attr('role', 'img')
    .attr('aria-label', options.title ?? 'Swarm graph')
    .style('display', 'block')
    .style('width', '100%')
    .style('height', '100%')
    .style('touch-action', 'none')
    .style('user-select', 'none');

  // Node names, sub-lines and counts draw in their own SVG stacked above the graph and above any
  // effects canvas the embedder adds over it (#173): no edge, beam, burst or particle ever paints
  // over a label. It shares the graph's viewBox and zoom, and lets every pointer through.
  const labelSvg = d3
    .select(container)
    .append('svg')
    .attr('xmlns', SVG_NS)
    .attr('aria-hidden', 'true')
    .attr('data-slot', 'swarm-labels')
    .style('position', 'absolute')
    .style('inset', '0')
    .style('z-index', '3')
    .style('display', 'block')
    .style('width', '100%')
    .style('height', '100%')
    .style('pointer-events', 'none')
    .style('user-select', 'none');

  const uid = hash(String(Math.random())).toString(36);
  const defs = svg.append('defs');
  const glow = defs
    .append('filter')
    .attr('id', `sg-glow-${uid}`)
    .attr('x', '-100%')
    .attr('y', '-100%')
    .attr('width', '300%')
    .attr('height', '300%');
  glow.append('feGaussianBlur').attr('stdDeviation', 3).attr('result', 'b');
  const merge = glow.append('feMerge');
  merge.append('feMergeNode').attr('in', 'b');
  merge.append('feMergeNode').attr('in', 'SourceGraphic');
  const glowUrl = `url(#${glow.attr('id')})`;

  const root = svg.append('g');
  const gBloom = root.append('g').attr('pointer-events', 'none');
  const gRings = root.append('g').attr('pointer-events', 'none');
  const gLinks = root.append('g').attr('fill', 'none').attr('pointer-events', 'none');
  const gRipples = root.append('g').attr('pointer-events', 'none');
  const gTrails = root
    .append('g')
    .attr('fill', 'none')
    .attr('stroke-linecap', 'round')
    .attr('pointer-events', 'none');
  const gParticles = root.append('g').attr('class', 'sg-beams').attr('pointer-events', 'none');
  const gNodes = root.append('g');
  const gBursts = root.append('g').attr('pointer-events', 'none');
  const gFloaters = root.append('g').attr('pointer-events', 'none');
  const labelRoot = labelSvg.append('g');
  const gTags = labelRoot.append('g');
  /** Each node's label block in the top layer: `g.sg-tag` > glyph (in `g.sg-tag-inner`), name, sub-line. */
  const tagGroups = () => gTags.selectAll<SVGGElement, SimNode>('g.sg-tag');

  let view = d3.zoomIdentity;
  const zoom = d3
    .zoom<SVGSVGElement, unknown>()
    .scaleExtent([0.4, 3])
    .on('zoom', (e) => {
      // A viewer who pans or zooms during the intro takes the camera from it.
      if (intro && e.sourceEvent) intro.camera = false;
      root.attr('transform', e.transform.toString());
      labelRoot.attr('transform', e.transform.toString());
      view = e.transform;
      placeAnchors();
      // The chips keep their screen size, so their room in graph units changes with the zoom.
      layoutLabels();
    });
  svg.call(zoom).on('dblclick.zoom', null);

  const setViewBox = () => {
    const box = [-width / 2, -height / 2, width, height].join(' ');
    svg.attr('viewBox', box);
    labelSvg.attr('viewBox', box);
  };
  setViewBox();

  let graph: SwarmGraph | null = null;
  const nodeById = new Map<string, SimNode>();
  let simLinks: SimLink[] = [];
  const seenFlows = new Set<string>();
  /** Event ids `seenFlows` keeps at most (the graph itself holds a few hundred). */
  const SEEN_CAP = 5_000;
  let particles: Particle[] = [];
  let ripples: Ripple[] = [];
  let bursts: Burst[] = [];
  let floaters: Floater[] = [];
  let nextKey = 0;
  const lastEmit = new Map<string, number>();
  let hovered: SimNode | null = null;
  /** A GPU effects layer draws trails and bursts (see `setLayered`). */
  let layered = false;
  let replayOverride: Map<string, number> | null = null;
  type ReplayRun = {
    plan: SwarmReplayPlan;
    clock: number;
    next: number;
    playing: boolean;
    speed: number;
    done: boolean;
    snap: SwarmReplaySnapshot;
    last: number;
    /** Effort changed since the nodes were last resized. */
    dirty: boolean;
    shownAt: number;
  };
  let run: ReplayRun | null = null;
  /** The beam budget: live, replay and catch-up all draw from it (see `./beams`). */
  const beams = createBeamGate();
  type IntroRun = {
    plan: IntroPlan;
    start: number;
    /** Settled positions, computed off-screen before anything moves. */
    target: Map<string, { x: number; y: number }>;
    /** Scale of each node while it travels out. */
    scale: Map<string, number>;
    /** Whether the intro still drives the camera (false once the viewer has panned). */
    camera: boolean;
    labels: number;
  };
  let intro: IntroRun | null = null;
  /** New nodes fading and growing in at their place (see `lifecycle.ts`). */
  const arrivals = new Map<string, { start: number }>();
  /** Nodes gone from the graph, fading out in place before they leave it. */
  const departures = new Map<string, { start: number }>();
  /** The pose of every arriving or departing node this frame. */
  const life = new Map<string, Pose>();
  /** Nodes whose pose just ended: their styles go back to the defaults once. */
  const settled = new Set<string>();
  /** A dead node winding down (`SwarmNode.fading`) is drawn this much dimmer. */
  const FADING_OPACITY = 0.7;
  const liveTimers = new Set<ReturnType<typeof setTimeout>>();
  /** Each node's place, as the layout engine last gave it: where it rests once its tween ends. */
  const places = new Map<string, LayoutPoint>();
  /**
   * Each place in ring units (divided by the ring's radii), as last laid out at any size: a
   * resize scales these, never the last re-fit, so a round trip brings every node home exactly.
   */
  const homes = new Map<string, LayoutPoint>();
  /** What placed each node there (its sector, phase, ties): when it changes, it is re-placed. */
  const placedBy = new Map<string, string>();
  /** Nodes on their way to a new place: a straight line with one ease-out, nothing else. */
  const moves = new Map<
    string,
    { from: LayoutPoint; to: LayoutPoint; start: number; ms: number }
  >();
  /**
   * A resize waiting for the canvas to stop changing size (#272): when it last changed (0: none
   * pending), and the arrangement the graph was laid out in before it. A page reflow resizes the
   * canvas in a few steps over a few hundred ms, so the graph is re-fitted once, at the size it
   * ends at, rather than once per step (each would turn every glide in flight).
   */
  let resized = 0;
  let resizedFrom: SectorArrangement['kind'] | null = null;
  /** Quiet time before a pending resize is applied (the gaps between reflow steps reach ~80 ms). */
  const RESIZE_QUIET_MS = 90;
  /** The glide of a resize's re-fit: one quick move, so it is over soon after the page settles. */
  const RESIZE_MOVE_MS = 320;
  /**
   * The glide of a ring/grid crossing's re-place: shorter still. The page's reflow to (or from) a
   * wide canvas costs long frames of its own, so this one has to be over sooner to settle in time.
   */
  const CROSSING_MOVE_MS = 180;
  /** The glide the next layout gives its moves. */
  let moveMs: number = MOVE.durationMs;
  /** The canvas size the layout was last fitted to (the first layout, or the last re-fit). */
  let fitted = { width, height };
  /**
   * A re-fit this close to the size the layout is fitted to (px, each way) re-places nothing: the
   * last step of a page's reflow is often a pixel or two, and it can land just after the re-fit
   * started, turning every glide in flight for a stretch of well under 1 % (#272).
   */
  const RESIZE_SNAP_PX = 3;

  const colorOf = (n: SwarmNode) => n.color ?? theme.neutral;
  /** Nodes whose host draws their information inside them (`anchor(…, 'inside')`). */
  const hosted = new Set<string>();
  /** The hosted set as `renderStatic` last drew it, and a pending redraw for a change to it. */
  let drawnHosted = '';
  let restyle = 0;
  const effortOf = (n: SimNode) => (replayOverride ? (replayOverride.get(n.id) ?? 0) : n.effort);
  /**
   * Where the sectors stand and how big they are (`arrangeSectors`): a ring fitted to a wide
   * canvas, a grid on a phone (#272). Decided by the canvas and the sector count only.
   */
  let arranged: { key: string; value: SectorArrangement } | null = null;
  const arrangement = () => {
    const count = graph ? graph.nodes.filter((n) => n.kind === 'sector').length : 0;
    const key = `${width}x${height}:${count}`;
    if (arranged?.key !== key)
      arranged = {
        key,
        value: arrangeSectors({
          count,
          width,
          height,
          maxBody: (options.sectorRadius ?? SECTOR_RADIUS).max,
          ringRoom: SECTOR_ROOM,
          hubRoom: radiusOf({ kind: 'hub' } as SwarmNode, 0) + 4,
        }),
      };
    return arranged.value;
  };
  /** The arrangement's half extent: places are kept relative to it across a resize. */
  const ringRadii = () => arrangement().radii;
  const ringRadius = () => Math.min(ringRadii().x, ringRadii().y);
  /** Sectors shrink on narrow canvases so the ring (or the grid) still fits a phone. */
  const sizeScale = () => arrangement().scale;
  /** A phone's canvas: sectors in a grid, shorter labels. */
  const compact = () => arrangement().kind === 'grid';
  const rOf = (n: SimNode) =>
    radiusOf(n, effortOf(n), sizeScale(), options.sectorRadius ?? SECTOR_RADIUS);
  /** Room for the body plus the progress arc drawn around sectors and open work. */
  const collideOf = (n: SimNode) =>
    n.kind === 'sector'
      ? // A sector keeps room for its largest size, so gaining effort (live, or in a replay)
        // never pushes its neighbours: it grows into space that was already its own.
        Math.max(n.r, (options.sectorRadius ?? SECTOR_RADIUS).max * sizeScale()) + SECTOR_ROOM
      : n.r + (n.kind === 'agent' ? 6 : n.kind === 'work' ? 7 : 4);

  /**
   * Where each node is drawn towards: sectors to their slot on the ring, the work and agents of
   * a sector just outside it (so the middle stays free for gate roles around the hub).
   */
  const anchorOf = (n: SimNode) => {
    if (n.kind === 'sector') return n.ring ?? { x: 0, y: 0 };
    const ring = n.sectorId ? nodeById.get(`sector:${n.sectorId}`)?.ring : undefined;
    if (!ring) return { x: 0, y: 0 };
    if (compact()) {
      // The grid (#272): branches and pull requests in the band through the hub, under their
      // sector; issues and agents in the band outside its row; landed work in the sector.
      const a = arrangement();
      const side = Math.sign(ring.y) || 1;
      const outside = Math.abs(ring.y) + (options.sectorRadius ?? SECTOR_RADIUS).max * a.scale + 26;
      if (n.kind === 'work' && n.phase === 'landed') return ring;
      if (n.kind === 'work' && (n.phase === 'branch' || n.phase === 'pr'))
        return { x: ring.x * 0.8, y: side * 24 };
      return { x: ring.x, y: side * outside };
    }
    // Branches and pull requests live between the integration branch they forked from and the
    // sector they change; issues wait outside the ring; landed work sits in its sector.
    const k =
      n.kind === 'work'
        ? n.phase === 'branch' || n.phase === 'pr'
          ? 0.56
          : n.phase === 'issue'
            ? 1.2
            : 1
        : 1.08;
    return { x: ring.x * k, y: ring.y * k };
  };
  const anchorStrength = (n: SimNode) => {
    if (n.kind === 'sector') return 0.5;
    if (n.kind === 'agent') return n.sectorId ? 0.03 : 0.02;
    if (!n.sectorId) return 0;
    return n.phase === 'landed' ? 0.3 : 0.2;
  };

  const chargeOf = (n: SimNode) => (n.kind === 'sector' ? -420 : n.kind === 'work' ? -50 : -140);
  const linkDistance = (l: SimLink) => {
    if (l.kind === 'target') return l.target.r + 34;
    if (l.kind === 'landed') return l.target.r + 12;
    if (l.kind === 'assignment')
      return l.target.kind === 'work' ? 34 : l.target.kind === 'hub' ? 70 : l.target.r + 46;
    if (l.kind === 'contribution') return 160;
    return ringRadius();
  };
  const linkStrength = (l: SimLink) => {
    // The ring and the anchors place trunk, fork and scope ends; the links are drawn, not pulled.
    if (l.kind === 'trunk' || l.kind === 'fork' || l.kind === 'scope') return 0;
    if (l.kind === 'contribution') return Math.min(0.06, 0.01 * Math.sqrt(l.weight));
    if (l.kind === 'target') return 0.4;
    if (l.kind === 'landed') return 0.8;
    return 0.6;
  };
  /** Half the box a node stays in: the canvas, less room for its label when it draws one. */
  const limitOf = (n: SimNode): LayoutPoint => {
    const pad = 14;
    return {
      // Labelled nodes keep room for their label (about 22 characters at 11px).
      // A hosted node carries its label inside: it needs only room for its body.
      x:
        width / 2 -
        pad -
        Math.max(
          n.r,
          !hosted.has(n.id) && (n.kind === 'sector' || (n.kind === 'agent' && n.active)) ? 62 : 0,
        ),
      y: height / 2 - n.r - pad - (n.kind === 'sector' && !hosted.has(n.id) ? 26 : 0),
    };
  };
  /** What decides a node's place: when this changes (a seat reassigned), the node is re-placed. */
  const placementOf = (n: SimNode) => {
    const ties = simLinks
      // A tie to a node already leaving does not count: it is gone from this view.
      .filter(
        (l) =>
          l.source.id === n.id &&
          l.kind !== 'contribution' &&
          l.kind !== 'fork' &&
          !departures.has(l.target.id),
      )
      .map((l) => `${l.kind}>${l.target.id}`)
      .sort()
      .join(',');
    return `${n.kind}|${n.sectorId ?? ''}|${n.phase ?? ''}|${ties}`;
  };

  /**
   * Ask the layout engine where everything stands, then send each node there. Sectors and the
   * hub are fixed on the ring; every node already placed, whose placement has not changed, is
   * pinned, so it does not move at all. Only new and re-placed nodes are solved for. `refit` (a
   * resized canvas) keeps every node where `places` already has it (stretched with the canvas)
   * and only clears overlaps.
   */
  /** A big batch being solved a slice per frame (see `relayout`), and what it was built from. */
  let pending: { job: LayoutJob; keys: Map<string, string>; refit: boolean } | null = null;
  /** Solve inline up to this much work (free nodes × all nodes); a bigger batch is sliced. */
  const INLINE_WORK = 600;
  /** Main-thread time a frame may spend on a sliced layout. */
  const SLICE_MS = 6;

  const relayout = (refit = false) => {
    if (!graph) return;
    const hubId = graph.hubId;
    const nodes: LayoutNode[] = [];
    const keys = new Map<string, string>();
    const parentOf = new Map<string, string>();
    for (const l of simLinks)
      if (l.kind !== 'contribution' && !parentOf.has(l.source.id))
        parentOf.set(l.source.id, l.target.id);
    for (const n of nodeById.values()) {
      const key = placementOf(n);
      const place = places.get(n.id);
      const keep = place && (refit || departures.has(n.id) || placedBy.get(n.id) === key);
      keys.set(n.id, key);
      nodes.push({
        id: n.id,
        r: collideOf(n),
        anchor: anchorOf(n),
        anchorStrength: anchorStrength(n),
        charge: chargeOf(n),
        fixed: n.id === hubId ? { x: 0, y: 0 } : n.kind === 'sector' ? n.ring : undefined,
        pinned: keep ? place : undefined,
        // A re-placed node starts from where it stands, so it takes the shortest way over.
        start: !keep && n.x !== undefined ? { x: n.x, y: n.y ?? 0 } : undefined,
        parent: parentOf.get(n.id),
        limit: limitOf(n),
      });
    }
    const ties: LayoutLink[] = simLinks.map((l) => ({
      source: l.source.id,
      target: l.target.id,
      distance: linkDistance(l),
      strength: linkStrength(l),
    }));
    const job = startLayout(nodes, ties, { settle: refit });
    // A newer graph supersedes a batch still being solved: it is rebuilt from what stands now.
    pending = { job, keys, refit };
    // The first layout, reduced motion and small changes are solved at once; a big batch (a
    // preset switch, a replay starting) is solved a slice per frame, its new nodes kept hidden
    // until their places are known, so no frame spends more than SLICE_MS on it.
    if (!places.size || !motion || intro || refit || job.free * nodes.length <= INLINE_WORK) {
      runLayout(Infinity);
      return;
    }
    for (const n of nodeById.values())
      if (!places.has(n.id)) {
        const a = arrivals.get(n.id);
        if (a) a.start = Infinity;
        // Hidden until placed; meanwhile it stands on its parent, never at the centre.
        const parent = nodeById.get(parentOf.get(n.id) ?? '');
        if (n.x === undefined && parent?.x !== undefined) {
          n.x = parent.x;
          n.y = parent.y;
        }
      }
  };

  /** Advance the pending layout by up to `budget` ms; apply it once it is done. */
  const runLayout = (budget: number) => {
    const p = pending;
    if (!p) return;
    const began = performance.now();
    let done = false;
    while (!(done = p.job.step(4)) && performance.now() - began < budget);
    // Visible in a performance trace (and to the site's calm check): one entry per slice.
    try {
      performance.measure('swarm-graph layout', {
        start: began,
        end: performance.now(),
        detail: { nodes: nodeById.size, free: p.job.free, done },
      });
    } catch {
      // An older runtime without measure options: the layout still ran.
    }
    if (!done) return;
    pending = null;
    applyLayout(p.job.result().positions, p.keys, p.refit);
  };

  /** Send every node to its new place: a tween for a moved one, a fade-in for a new one. */
  const applyLayout = (
    positions: Map<string, LayoutPoint>,
    keys: Map<string, string>,
    refit: boolean,
  ) => {
    const now = performance.now();
    const R = ringRadii();
    let held = 0;
    for (const n of nodeById.values()) {
      const to = positions.get(n.id);
      if (!to) continue;
      const key = keys.get(n.id);
      if (key !== undefined) placedBy.set(n.id, key);
      places.set(n.id, to);
      if (!refit || !homes.has(n.id)) homes.set(n.id, { x: to.x / R.x, y: to.y / R.y });
      // A new node waiting on a sliced layout starts fading in now, at its place.
      const a = arrivals.get(n.id);
      const waited = a?.start === Infinity;
      if (a && waited) a.start = now + staggerAt(held++, ARRIVAL.staggerMs, ARRIVAL.maxSteps);
      if (waited || n.x === undefined || n.y === undefined || !motion || intro) {
        // New (it fades in right there), or no motion: straight to its place.
        n.x = to.x;
        n.y = to.y;
        moves.delete(n.id);
        continue;
      }
      if (Math.hypot(to.x - n.x, to.y - n.y) < 0.5) {
        if (!moves.has(n.id)) {
          n.x = to.x;
          n.y = to.y;
        }
        continue;
      }
      const going = moves.get(n.id);
      if (going && Math.hypot(going.to.x - to.x, going.to.y - to.y) < 0.5) continue;
      moves.set(n.id, { from: { x: n.x, y: n.y }, to, start: now, ms: moveMs });
    }
  };

  /** One frame of moves. True when anything moved. */
  const stepMoves = (now: number) => {
    if (!moves.size) return false;
    for (const [id, m] of moves) {
      const n = nodeById.get(id);
      if (!n) {
        moves.delete(id);
        continue;
      }
      const p = progressAt(now, m.start, m.ms);
      const at = movePoint(m.from, m.to, p);
      n.x = at.x;
      n.y = at.y;
      if (p >= 1) moves.delete(id);
    }
    return true;
  };

  const placeRing = () => {
    if (!graph) return;
    const sectors = graph.nodes.filter((n) => n.kind === 'sector');
    const { slots } = arrangement();
    sectors.forEach((s, i) => {
      const node = nodeById.get(s.id);
      if (node) node.ring = slots[i]!;
    });
  };

  // ---- drawing -----------------------------------------------------------------------------

  const neighbours = (n: SimNode) => {
    const set = new Set([n.id]);
    for (const l of simLinks)
      if (l.source.id === n.id || l.target.id === n.id) set.add(l.source.id).add(l.target.id);
    return set;
  };

  const linkStyle = (
    l: SimLink,
  ): { stroke: string; width: number; opacity: number; dash: string | null } => {
    const c = colorOf(l.target.kind === 'hub' ? l.source : l.target);
    switch (l.kind) {
      case 'trunk':
        // The sector's paths are part of the integration branch.
        return {
          stroke: colorOf(l.source),
          width: 1 + Math.sqrt(l.weight) * 0.4,
          opacity: 0.2,
          dash: null,
        };
      case 'fork':
        // Branched from the integration branch's tip; animated while an agent works in it.
        return {
          stroke: colorOf(l.target),
          width: 1.6,
          opacity: l.active ? 0.85 : 0.5,
          dash: l.active ? '5 5' : null,
        };
      case 'scope':
        return { stroke: colorOf(l.source), width: 1, opacity: 0.28, dash: '1 4' };
      case 'target':
        return { stroke: colorOf(l.target), width: 1, opacity: 0.35, dash: '3 4' };
      case 'landed':
        return { stroke: colorOf(l.target), width: 1, opacity: 0.4, dash: null };
      case 'assignment':
        return l.active
          ? { stroke: colorOf(l.source), width: 1.8, opacity: 0.9, dash: '3 5' }
          : { stroke: theme.lineStrong, width: 1, opacity: 0.55, dash: null };
      case 'contribution':
        return {
          stroke: c,
          // History, not a path work travels: faint until the agent is hovered.
          width: Math.min(2.5, 0.5 + Math.sqrt(l.weight) * 0.35),
          opacity: Math.min(0.12, 0.04 + l.weight * 0.01),
          dash: '1 3',
        };
    }
  };

  const renderStatic = () => {
    drawnHosted = [...hosted].sort().join('|');
    // Links
    gLinks
      .selectAll<SVGPathElement, SimLink>('path')
      .data(simLinks, (l) => l.id)
      .join((enter) => enter.append('path').attr('stroke-linecap', 'round').attr('opacity', 0))
      .each(function (l) {
        const s = linkStyle(l);
        d3.select(this)
          .style('stroke', s.stroke)
          .attr('stroke-width', s.width)
          .attr('stroke-dasharray', s.dash)
          .attr('data-kind', l.kind)
          .transition()
          .duration(600)
          .attr('opacity', s.opacity);
      });

    // Rings: the halo of every live sector / agent.
    const ringed = [...nodeById.values()].filter(
      (n) => n.active && (n.kind === 'sector' || n.kind === 'agent' || n.kind === 'work'),
    );
    gRings
      .selectAll<SVGCircleElement, SimNode>('circle')
      .data(ringed, (n) => n.id)
      .join((enter) => {
        const c = enter.append('circle').attr('fill', 'none').attr('stroke-width', 1.5);
        if (motion) {
          c.append('animate')
            .attr('attributeName', 'stroke-opacity')
            .attr('values', '0.7;0;0.7')
            .attr('dur', '2.4s')
            .attr('repeatCount', 'indefinite');
          c.append('animate')
            .attr('attributeName', 'stroke-width')
            .attr('values', '1.5;6;1.5')
            .attr('dur', '2.4s')
            .attr('repeatCount', 'indefinite');
        }
        return c;
      })
      .style('stroke', (n) => (n.kind === 'hub' ? theme.fg : colorOf(n)))
      .attr('stroke-opacity', 0.5);

    // Nodes
    const groups = gNodes
      .selectAll<SVGGElement, SimNode>('g.sg-node')
      .data([...nodeById.values()], (n) => n.id)
      .join(
        (enter) => {
          const g = enter
            .append('g')
            .attr('class', 'sg-node')
            .attr('tabindex', 0)
            .attr('role', 'button')
            .style('cursor', 'pointer')
            .style('outline', 'none')
            .attr('opacity', 0);
          // The inner group scales (pops) without fighting the per-tick translate. Its opacity is
          // the dimming of a dead node winding down (`FADING_OPACITY`).
          const inner = g
            .append('g')
            .attr('class', 'sg-inner')
            .attr('opacity', (n) => (n.fading ? FADING_OPACITY : 1));
          inner.append('path').attr('class', 'sg-track').attr('stroke', 'none');
          inner.append('path').attr('class', 'sg-arc-flight').attr('stroke', 'none');
          inner.append('path').attr('class', 'sg-arc').attr('stroke', 'none');
          const orbit = inner
            .append('circle')
            .attr('class', 'sg-orbit')
            .attr('fill', 'none')
            .attr('stroke-dasharray', '2 6')
            .attr('stroke-linecap', 'round');
          if (motion)
            orbit
              .append('animateTransform')
              .attr('attributeName', 'transform')
              .attr('type', 'rotate')
              .attr('from', '0')
              .attr('to', '360')
              .attr('dur', '40s')
              .attr('repeatCount', 'indefinite');
          inner.append('path').attr('class', 'sg-body');
          // Arrivals (and reduced motion) are posed per frame instead; see `stepLife`.
          const posed = (n: SimNode) => !motion || arrivals.has(n.id);
          g.filter(posed).attr('opacity', 1);
          g.filter((n) => !posed(n))
            .transition()
            .duration(500)
            .attr('opacity', 1);
          // New nodes grow in from nothing.
          if (motion)
            inner
              .filter((n) => !arrivals.has(n.id))
              .attr('transform', 'scale(0.01)')
              .transition()
              .duration(500)
              // One ease-out, no spring: it grows to full size and stops there (#221).
              .ease(d3.easeCubicOut)
              .attr('transform', 'scale(1)');
          return g;
        },
        (update) => update,
        // A node leaves only after its departure faded it out (at once with reduced motion).
        (exit) => exit.remove(),
      );

    // The label layer mirrors the nodes one-for-one, appearing and leaving with them.
    const tags = tagGroups()
      .data([...nodeById.values()], (n) => n.id)
      .join(
        (enter) => {
          const g = enter.append('g').attr('class', 'sg-tag').attr('opacity', 0);
          const inner = g.append('g').attr('class', 'sg-tag-inner');
          inner
            .append('text')
            .attr('class', 'sg-glyph')
            .attr('text-anchor', 'middle')
            .attr('dominant-baseline', 'central');
          inner.append('path').attr('class', 'sg-icon').attr('aria-hidden', 'true');
          g.append('text').attr('class', 'sg-label').attr('text-anchor', 'middle');
          g.append('text').attr('class', 'sg-sub').attr('text-anchor', 'middle');
          const posed = (n: SimNode) => !motion || arrivals.has(n.id);
          g.filter(posed).attr('opacity', 1);
          g.filter((n) => !posed(n))
            .transition()
            .duration(500)
            .attr('opacity', 1);
          if (motion)
            inner
              .filter((n) => !arrivals.has(n.id))
              .attr('transform', 'scale(0.01)')
              .transition()
              .duration(500)
              // One ease-out, no spring: it grows to full size and stops there (#221).
              .ease(d3.easeCubicOut)
              .attr('transform', 'scale(1)');
          return g;
        },
        (update) => update,
        (exit) => exit.remove(),
      );

    // A dead node winding down is drawn dimmer before it leaves.
    const dim = (n: SimNode) => (n.fading ? FADING_OPACITY : 1);
    groups
      .select<SVGGElement>('g.sg-inner')
      .transition('dim')
      .duration(motion ? 800 : 0)
      .attr('opacity', dim);
    tags
      .transition('dim')
      .duration(motion ? 800 : 0)
      .attr('opacity', dim);

    groups.attr('aria-label', (n) => {
      if (n.kind !== 'agent') return `${n.kind} ${n.label}`;
      const icon = iconOf(n);
      return [n.label, n.agent?.role, icon?.name.toLowerCase()].filter(Boolean).join(', ');
    });
    groups.select<SVGPathElement>('path.sg-body').each(function (n) {
      const el = d3.select(this);
      const c = colorOf(n);
      el.attr('d', bodyPath(n, n.r)).attr('stroke-dasharray', null);
      if (n.kind === 'hub') {
        el.style('fill', theme.panelRaised)
          .style('stroke', theme.fg)
          .attr('stroke-width', 1.5)
          .attr('fill-opacity', 1)
          .attr('filter', n.active ? glowUrl : null);
      } else if (n.kind === 'sector') {
        // A hosted sector's body is opaque (its tint mixed into the panel), so no edge passing
        // behind it shows through the text drawn inside (#173, #199).
        el.style(
          'fill',
          hosted.has(n.id) ? `color-mix(in srgb, ${c} ${n.active ? 30 : 16}%, ${theme.panel})` : c,
        )
          .attr('fill-opacity', hosted.has(n.id) ? 1 : n.active ? 0.3 : 0.16)
          .style('stroke', c)
          .attr('stroke-width', n.active ? 2 : 1.25)
          .attr('filter', n.active ? glowUrl : null);
      } else if (n.kind === 'work') {
        const stage = n.workItem?.stage;
        const stroke =
          stage === 'approved'
            ? theme.good
            : stage === 'changes'
              ? theme.warning
              : stage === 'held'
                ? theme.fgFaint
                : c;
        if (n.phase === 'issue')
          el.style('fill', theme.panel)
            .attr('fill-opacity', 1)
            .style('stroke', stroke)
            .attr('stroke-width', 1.25)
            .attr('stroke-dasharray', '2 2')
            .attr('filter', null);
        else if (n.phase === 'landed')
          el.style('fill', c)
            .attr('fill-opacity', 0.55)
            .style('stroke', 'none')
            .attr('stroke-width', 0)
            .attr('filter', null);
        else
          el.style('fill', n.phase === 'pr' || n.active ? c : theme.panel)
            .attr('fill-opacity', n.phase === 'pr' ? 0.3 : n.active ? 0.35 : 1)
            .style('stroke', stroke)
            .attr('stroke-width', stage === 'approved' || stage === 'changes' ? 2.2 : 1.6)
            .attr('filter', n.active ? glowUrl : null);
      } else {
        el.style('fill', theme.panelRaised)
          .attr('fill-opacity', 1)
          .style('stroke', n.active ? c : theme.lineStrong)
          .attr('stroke-width', n.active ? 2 : 1.25)
          .attr('filter', n.active ? glowUrl : null);
      }
    });

    renderArcs(groups);

    groups
      .select<SVGCircleElement>('circle.sg-orbit')
      .attr('display', (n) => (n.kind === 'hub' ? null : 'none'))
      .attr('r', (n) => n.r + 7)
      .style('stroke', theme.fgFaint)
      .attr('stroke-opacity', 0.6);

    // A soft bloom under every sector; brighter, and breathing, while an agent works there.
    const sectors = [...nodeById.values()].filter((n) => n.kind === 'sector');
    defs
      .selectAll<SVGRadialGradientElement, SimNode>('radialGradient.sg-bloom')
      .data(sectors, (n) => n.id)
      .join((enter) => {
        const g = enter.append('radialGradient').attr('class', 'sg-bloom');
        g.append('stop').attr('offset', '0%').attr('stop-opacity', 0.55);
        g.append('stop').attr('offset', '45%').attr('stop-opacity', 0.14);
        g.append('stop').attr('offset', '100%').attr('stop-opacity', 0);
        return g;
      })
      .attr('id', (n) => `sg-bloom-${uid}-${hash(n.id)}`)
      .each(function (n) {
        d3.select(this).selectAll('stop').style('stop-color', colorOf(n));
      });
    gBloom
      .selectAll<SVGCircleElement, SimNode>('circle')
      .data(sectors, (n) => n.id)
      .join((enter) => {
        const c = enter.append('circle').attr('opacity', 0);
        if (motion)
          c.append('animate')
            .attr('attributeName', 'r')
            .attr('dur', '3.2s')
            .attr('repeatCount', 'indefinite');
        return c;
      })
      .attr('fill', (n) => `url(#sg-bloom-${uid}-${hash(n.id)})`)
      .each(function (n) {
        const el = d3.select(this);
        el.transition()
          .duration(800)
          .attr('opacity', n.active ? 0.9 : 0.4);
        el.select('animate').attr(
          'values',
          n.active ? `${n.r * 2.4};${n.r * 3};${n.r * 2.4}` : `${n.r * 2.2};${n.r * 2.2}`,
        );
        if (!motion || !n.active) el.attr('r', n.r * 2.2);
      });

    tags
      .select<SVGTextElement>('text.sg-glyph')
      .style('font-family', (n) => (n.kind === 'agent' ? theme.font : theme.monoFont))
      .attr('font-size', (n) =>
        n.kind === 'sector'
          ? Math.max(MIN_LABEL_PX, Math.min(15, n.r * 0.5))
          : n.kind === 'agent'
            ? 12
            : MIN_LABEL_PX,
      )
      .attr('font-weight', 600)
      .style('fill', (n) => (n.kind === 'agent' && !n.active ? theme.fgFaint : theme.fg))
      .text((n) => {
        if (n.kind === 'agent')
          return iconOf(n)
            ? ''
            : (ROLE_GLYPH[n.agent?.role ?? ''] ??
                (n.agent?.role ?? n.label).charAt(0).toUpperCase());
        if (n.kind === 'sector')
          return hosted.has(n.id) ? '' : countLabel(shownNumber.get(n.id) ?? countOf(n));
        if (n.kind === 'hub') return n.label;
        return '';
      });
    countUp();

    // An agent's own icon fills most of its circle, in the colour its letter had.
    tags
      .select<SVGPathElement>('path.sg-icon')
      .attr('d', (n) => iconOf(n)?.d ?? '')
      .attr('transform', (n) => {
        const icon = iconOf(n);
        if (!icon) return null;
        const px = n.r * 1.3;
        return `translate(${-px / 2},${-px / 2}) scale(${px / icon.size})`;
      })
      .style('fill', (n) => (n.kind === 'agent' && !n.active ? theme.fgFaint : theme.fg));

    // A wide halo in the panel colour masks anything passing behind the text, in both themes.
    tags
      .select<SVGTextElement>('text.sg-label')
      .style('font-family', (n) =>
        n.kind === 'work' && (n.phase === 'branch' || n.phase === 'pr')
          ? theme.monoFont
          : theme.font,
      )
      .attr('font-size', (n) => (n.kind === 'sector' ? 13 : MIN_LABEL_PX))
      .attr('font-weight', (n) => (n.kind === 'sector' ? 600 : 500))
      .style('fill', (n) => (n.kind === 'sector' || n.active ? theme.fg : theme.fgFaint))
      .style('paint-order', 'stroke')
      .style('stroke', theme.panel)
      .attr('stroke-width', LABEL_HALO)
      .attr('stroke-linejoin', 'round')
      .text((n) => labelOf(n));

    tags
      .select<SVGTextElement>('text.sg-sub')
      .style('font-family', theme.font)
      .attr('font-size', MIN_LABEL_PX)
      .style('fill', theme.fgFaint)
      .style('paint-order', 'stroke')
      .style('stroke', theme.panel)
      .attr('stroke-width', LABEL_HALO)
      .attr('stroke-linejoin', 'round')
      .text((n) => subOf(n));

    groups
      .on('pointerenter', (e: PointerEvent, n) => {
        hovered = n;
        applyHover();
        const rect = container.getBoundingClientRect();
        options.onHover?.(n, {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top,
        });
      })
      .on('pointermove', (e: PointerEvent, n) => {
        const rect = container.getBoundingClientRect();
        options.onHover?.(n, {
          x: e.clientX - rect.left,
          y: e.clientY - rect.top,
        });
      })
      .on('pointerleave', () => {
        hovered = null;
        applyHover();
        options.onHover?.(null, null);
      })
      .on('focus', function (_e, n) {
        hovered = n;
        applyHover();
        const rect = container.getBoundingClientRect();
        const box = (this as SVGGElement).getBoundingClientRect();
        options.onHover?.(n, {
          x: box.left + box.width / 2 - rect.left,
          y: box.top - rect.top,
        });
      })
      .on('blur', () => {
        hovered = null;
        applyHover();
        options.onHover?.(null, null);
      })
      .on('keydown', (e: KeyboardEvent, n) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          options.onSelect?.(n);
        }
      })
      .on('click', (e: MouseEvent, n) => {
        if (e.defaultPrevented) return;
        options.onSelect?.(n);
      })
      .call(
        d3
          .drag<SVGGElement, SimNode>()
          .clickDistance(4)
          // Dragging moves only the dragged node; nothing else responds. On release it stays
          // where it was dropped: that is its place now, so later updates keep it there too.
          .on('start', (_e, n) => {
            if (n.kind === 'hub') return;
            moves.delete(n.id);
          })
          .on('drag', (e, n) => {
            if (n.kind === 'hub') return;
            const lim = limitOf(n);
            n.x = Math.max(-lim.x, Math.min(lim.x, e.x));
            n.y = Math.max(-lim.y, Math.min(lim.y, e.y));
            places.set(n.id, { x: n.x, y: n.y });
            const R = ringRadii();
            homes.set(n.id, { x: n.x / R.x, y: n.y / R.y });
            draw();
          }),
      );

    applyHover();
  };

  /**
   * Progress arcs. A sector's ring fills with its merged work (solid) and the work in flight
   * (faint) out of everything aimed at it; an open branch or pull request's ring shows how far
   * along the protocol it is. Arcs ease to their new value, so progress is something you watch.
   */
  const arcShown = new Map<string, { done: number; flight: number }>();
  const arcTarget = (n: SimNode) => {
    if (n.kind === 'sector') {
      const t = n.tally;
      if (!t || !t.total) return { done: 0, flight: 0 };
      return { done: t.landed / t.total, flight: (t.branch + t.pr) / t.total };
    }
    if (n.kind === 'work' && n.workItem)
      return { done: STAGE_PROGRESS[n.workItem.stage] ?? 0, flight: 0 };
    return { done: 0, flight: 0 };
  };
  const arcRadii = (n: SimNode): [number, number] =>
    n.kind === 'sector' ? [n.r + 5, n.r + 8.5] : [n.r + 3.5, n.r + 5.5];
  const hasArc = (n: SimNode) =>
    n.kind === 'sector' ||
    (n.kind === 'work' && (n.phase === 'branch' || n.phase === 'pr') && !replayOverride);
  const arcColor = (n: SimNode) => {
    const stage = n.workItem?.stage;
    return stage === 'approved' ? theme.good : stage === 'changes' ? theme.warning : colorOf(n);
  };
  const drawArcs = (el: SVGGElement, n: SimNode, v: { done: number; flight: number }) => {
    const [r0, r1] = arcRadii(n);
    const g = d3.select(el);
    const on = hasArc(n);
    g.select('path.sg-track')
      .attr('d', on ? arcPath(r0, r1, 0, 1) : '')
      .style('fill', theme.line)
      .attr('fill-opacity', 0.55);
    g.select('path.sg-arc-flight')
      .attr('d', on ? arcPath(r0, r1, v.done, v.done + v.flight) : '')
      .style('fill', colorOf(n))
      .attr('fill-opacity', 0.38);
    g.select('path.sg-arc')
      .attr('d', on ? arcPath(r0, r1, 0, v.done) : '')
      .style('fill', arcColor(n))
      .attr('fill-opacity', 1);
  };
  const renderArcs = (groups: d3.Selection<SVGGElement, SimNode, SVGGElement, unknown>) => {
    groups.select<SVGGElement>('g.sg-inner').each(function (n) {
      const to = arcTarget(n);
      const from = arcShown.get(n.id) ?? { done: 0, flight: 0 };
      arcShown.set(n.id, to);
      if (!motion || (from.done === to.done && from.flight === to.flight)) {
        drawArcs(this, n, to);
        return;
      }
      const done = d3.interpolateNumber(from.done, to.done);
      const flight = d3.interpolateNumber(from.flight, to.flight);
      d3.select(this)
        .transition('arc')
        .duration(1400)
        .ease(d3.easeCubicOut)
        .tween('arc', () => (t) => drawArcs(this, n, { done: done(t), flight: flight(t) }));
    });
  };

  /**
   * The number inside a sector is the host's stable count (`SwarmSector.count`: merged pull
   * requests, landed versions), not effort, so it does not move with the events a view shows. It
   * counts up (or down) to a new value instead of jumping, and a sector with nothing shows nothing.
   */
  const shownNumber = new Map<string, number>();
  const countOf = (n: SimNode) => n.sector?.count?.value ?? 0;
  const countLabel = (v: number) => (v > 0 ? String(Math.round(v)) : '');
  const countUp = () => {
    tagGroups()
      .filter((n) => n.kind === 'sector' && !hosted.has(n.id))
      .select<SVGTextElement>('text.sg-glyph')
      .each(function (n) {
        const to = countOf(n);
        const from = shownNumber.get(n.id) ?? to;
        shownNumber.set(n.id, to);
        const el = d3.select(this);
        if (!motion || from === to) {
          el.interrupt('count').text(countLabel(to));
          return;
        }
        el.transition('count')
          .duration(Math.min(1600, 300 + Math.abs(to - from) * 40))
          .ease(d3.easeCubicOut)
          .textTween(() => (t) => countLabel(from + (to - from) * t));
      });
  };

  /** A quick elastic bump on a node: something just happened to it. */
  const pop = (node: SimNode, strength = 1) => {
    if (!motion) return;
    gNodes
      .selectAll<SVGGElement, SimNode>('g.sg-node')
      .filter((n) => n === node)
      .select<SVGGElement>('g.sg-inner')
      .merge(
        tagGroups()
          .filter((n) => n === node)
          .select<SVGGElement>('g.sg-tag-inner'),
      )
      .interrupt('pop')
      .transition('pop')
      .duration(130)
      .ease(d3.easeQuadOut)
      .attr('transform', `scale(${1 + 0.16 * strength})`)
      .transition()
      .duration(450)
      // Back to size with one ease-out: a pulse, never a wobble (#221).
      .ease(d3.easeCubicOut)
      .attr('transform', 'scale(1)');
  };

  /** Sparks thrown out of a node, and a word rising off it. */
  const celebrate = (node: SimNode, color: string, count: number, text: string | null) => {
    const now = performance.now();
    if (motion && !layered)
      for (let i = 0; i < count; i++)
        bursts.push({
          key: nextKey++,
          node,
          start: now + Math.random() * 60,
          angle: (i / count) * Math.PI * 2 + Math.random() * 0.5,
          dist: node.r + 14 + Math.random() * 26,
          size: 1.4 + Math.random() * 2,
          color,
        });
    if (text) floaters.push({ key: nextKey++, node, start: now, text, color });
  };

  /** Sectors, live agents, branches and pull requests are always named; the rest on hover. */
  const labelOf = (n: SimNode) => {
    // A hosted node's host draws its name inside it.
    if (hosted.has(n.id)) return '';
    if (n.kind === 'sector') return n.label;
    // Narrow canvases (phones) get shorter names so there is room to place them.
    const narrow = width < 560;
    if (n.kind === 'agent')
      return n.active || n === hovered ? shortLabel(n.label, narrow ? 16 : 22) : '';
    if (n.kind === 'work') {
      if (n.phase === 'branch' || n.phase === 'pr')
        // Truncated, never shrunk: the full name shows on hover.
        return shortLabel(n.label, n === hovered ? (narrow ? 30 : 48) : narrow ? 16 : 24);
      return n === hovered ? shortLabel(n.label, narrow ? 24 : 34) : '';
    }
    return '';
  };

  const subOf = (n: SimNode) => {
    if (hosted.has(n.id)) return '';
    if (n.kind === 'hub') return 'integration branch';
    if (n.kind === 'sector') {
      const live = [...nodeById.values()].filter(
        (a) => a.kind === 'agent' && a.active && a.sectorId === n.sectorId,
      ).length;
      // What the number inside counts, so it is never a bare figure.
      const c = n.sector?.count;
      const count =
        c && c.value > 0
          ? c.recent
            ? `${c.unit} · ${c.recent} ${c.recentUnit ?? 'recent'}`
            : c.unit
          : null;
      return [count, live ? `${live} live` : null].filter(Boolean).join(' · ');
    }
    // The role, now that the node shows the agent's animal rather than a role letter (#200).
    if (n.kind === 'agent' && (n.active || n === hovered)) return n.agent?.role ?? '';
    if (n.kind === 'work' && n.phase === 'pr' && n.workItem) return STAGE_LABEL[n.workItem.stage];
    return '';
  };

  /**
   * Text widths for the label layout: measured once per string on a canvas in the page's own
   * fonts (cached), so a placed label's box is the label (#272). Without a canvas (tests), an
   * estimate from the character count.
   */
  const widths = new Map<string, number>();
  let measurer: CanvasRenderingContext2D | null | undefined;
  const fontFamily = (css: string) => {
    // `var(--name, fallback)`: the page's value of the variable, else the fallback.
    const m = /^var\((--[\w-]+),\s*(.*)\)$/.exec(css.trim());
    if (!m) return css;
    const v = getComputedStyle(container).getPropertyValue(m[1]!).trim();
    return v || m[2]!;
  };
  const textWidth = (text: string, px: number, weight: number, mono: boolean, estimate: number) => {
    if (!text) return 0;
    const key = `${weight} ${px} ${mono ? 'm' : 's'} ${text}`;
    const known = widths.get(key);
    if (known !== undefined) return known;
    if (measurer === undefined) {
      try {
        measurer = document.createElement('canvas').getContext('2d');
      } catch {
        measurer = null;
      }
    }
    let w = text.length * estimate;
    if (measurer) {
      measurer.font = `${weight} ${px}px ${fontFamily(mono ? theme.monoFont : theme.font)}`;
      const measured = measurer.measureText(text).width;
      if (measured > 0) w = Math.ceil(measured) + 1;
    }
    if (widths.size > 2000) widths.clear();
    widths.set(key, w);
    return w;
  };

  /** Who gets first pick of label room: the hovered node, sectors, live agents, PRs, branches. */
  const labelRank = (n: SimNode) =>
    n === hovered
      ? 0
      : n.kind === 'sector' || (n.kind === 'hub' && !compact())
        ? 1
        : n.kind === 'agent'
          ? 2
          : n.phase === 'pr'
            ? 3
            : // On a phone the hub's "integration branch" gives way to the agents and their work.
              4;

  /**
   * Place every visible label (name + sub-line) where it collides with nothing placed before it:
   * below the node, else above, right, left. Text widths are estimated from character counts, so
   * this runs every tick without forcing a layout.
   */
  const lastSpot = new Map<string, number>();
  /** Which of a node's texts the label layout shows: 2 both, 1 the name only, 0 neither. */
  const shown = new Map<string, 0 | 1 | 2>();
  const layoutLabels = () => {
    type Box = { x0: number; y0: number; x1: number; y1: number };
    type Candidate = { box: Box; anchor: string; x: number; top: number };
    const hit = (a: Box, b: Box) => a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
    // A node's box takes in its progress arc: a label never covers a node, its ring or its icon.
    const bodies = [...nodeById.values()].map((n) => ({
      n,
      x: n.x ?? 0,
      y: n.y ?? 0,
      r: hasArc(n) ? arcRadii(n)[1] : n.r,
    }));
    /** Whether a box touches a circle: the box's nearest point to the centre is inside it. */
    const touches = (b: Box, o: { x: number; y: number; r: number }) =>
      Math.hypot(
        o.x - Math.max(b.x0, Math.min(o.x, b.x1)),
        o.y - Math.max(b.y0, Math.min(o.y, b.y1)),
      ) < o.r;
    // The HTML chips beside a node (rating, agents) are obstacles too: a label never hides under one.
    const chips = [...chipBoxes.values()];
    const placed: Box[] = [];
    const ordered = [...nodeById.values()]
      .filter((n) => labelOf(n) || subOf(n))
      .sort((a, b) => labelRank(a) - labelRank(b) || a.id.localeCompare(b.id));
    const spot = new Map<string, { anchor: string; x: number; label: number; sub: number }>();
    // Below the node, else above, right, left.
    const candidatesOf = (n: SimNode, w: number, h: number): Candidate[] => {
      const cx = n.x ?? 0;
      const cy = n.y ?? 0;
      const r = hasArc(n) ? arcRadii(n)[1] : n.r;
      const gap = 4;
      return [
        {
          box: { x0: cx - w / 2, y0: cy + r + gap, x1: cx + w / 2, y1: cy + r + gap + h },
          anchor: 'middle',
          x: 0,
          top: r + gap,
        },
        {
          box: { x0: cx - w / 2, y0: cy - r - gap - h, x1: cx + w / 2, y1: cy - r - gap },
          anchor: 'middle',
          x: 0,
          top: -r - gap - h,
        },
        {
          box: { x0: cx + r + 4, y0: cy - h / 2, x1: cx + r + 4 + w, y1: cy + h / 2 },
          anchor: 'start',
          x: r + 4,
          top: -h / 2,
        },
        {
          box: { x0: cx - r - 4 - w, y0: cy - h / 2, x1: cx - r - 4, y1: cy + h / 2 },
          anchor: 'end',
          x: -r - 4,
          top: -h / 2,
        },
      ];
    };
    const inside = (c: Candidate) =>
      c.box.x0 >= -width / 2 + 2 &&
      c.box.x1 <= width / 2 - 2 &&
      c.box.y0 >= -height / 2 + 2 &&
      c.box.y1 <= height / 2 - 2;
    const clashes = (n: SimNode, c: Candidate) =>
      placed.filter((b) => hit(b, c.box)).length +
      chips.filter((b) => hit(b, c.box)).length +
      bodies.filter((o) => o.n !== n && touches(c.box, o)).length;
    const free = (n: SimNode, c: Candidate) => inside(c) && clashes(n, c) === 0;
    const block = (n: SimNode, label: string, sub: string) => {
      const big = n.kind === 'sector';
      const mono = n.kind === 'work' && (n.phase === 'branch' || n.phase === 'pr');
      const lw = textWidth(
        label,
        big ? 13 : MIN_LABEL_PX,
        big ? 600 : 500,
        mono,
        big ? 7.6 : mono ? 6.7 : 6.1,
      );
      const sw = textWidth(sub, MIN_LABEL_PX, 400, false, 5.4);
      const lh = label ? (big ? 16 : 14) : 0;
      return { w: Math.max(lw, sw), lh, h: lh + (sub ? 13 : 0) };
    };
    for (const n of ordered) {
      const label = labelOf(n);
      const sub = subOf(n);
      const big = n.kind === 'sector';
      // Each label is tried whole, then without its sub-line, and is hidden when even its name
      // has nowhere clear to go (#272): a label never sits on another label, a node or an icon.
      // The hovered node and the sectors always show theirs; the hover card has the rest.
      const must = n === hovered || big;
      const tries: { label: string; sub: string; show: 1 | 2 }[] = [{ label, sub, show: 2 }];
      if (!must && label && sub) tries.push({ label, sub: '', show: 1 });
      const prev = lastSpot.get(n.id);
      let chosen: { pick: Candidate; at: number; lh: number; show: 0 | 1 | 2 } | null = null;
      for (const t of tries) {
        const { w, lh, h } = block(n, t.label, t.sub);
        const cands = candidatesOf(n, w, h);
        const at =
          prev !== undefined && free(n, cands[prev]!) ? prev : cands.findIndex((c) => free(n, c));
        if (at >= 0) {
          chosen = { pick: cands[at]!, at, lh, show: t.show };
          break;
        }
      }
      if (!chosen && must) {
        const { w, lh, h } = block(n, label, sub);
        const cands = candidatesOf(n, w, h);
        // Nowhere clear: the on-canvas spot with the fewest collisions.
        const best = cands
          .map((c, at) => ({ c, at }))
          .filter(({ c }) => inside(c))
          .sort((a, b) => clashes(n, a.c) - clashes(n, b.c))[0] ?? { c: cands[0]!, at: 0 };
        chosen = { pick: best.c, at: best.at, lh, show: 2 };
      }
      if (!chosen) {
        shown.set(n.id, 0);
        continue;
      }
      const { pick, at, lh, show } = chosen;
      lastSpot.set(n.id, at);
      shown.set(n.id, show);
      placed.push(pick.box);
      spot.set(n.id, {
        anchor: pick.anchor,
        x: pick.x,
        label: pick.top + lh - (big ? 4 : 3),
        sub: pick.top + lh + 10,
      });
    }
    const visible = (n: SimNode, part: 1 | 2) => (shown.get(n.id) ?? 2) >= part;
    const groups = tagGroups();
    groups
      .select<SVGTextElement>('text.sg-label')
      .attr('display', (n) => (visible(n, 1) ? null : 'none'))
      .attr('text-anchor', (n) => spot.get(n.id)?.anchor ?? 'middle')
      .attr('x', (n) => spot.get(n.id)?.x ?? 0)
      .attr('y', (n) => spot.get(n.id)?.label ?? 0);
    groups
      .select<SVGTextElement>('text.sg-sub')
      .attr('display', (n) => (visible(n, 2) ? null : 'none'))
      .attr('text-anchor', (n) => spot.get(n.id)?.anchor ?? 'middle')
      .attr('x', (n) => spot.get(n.id)?.x ?? 0)
      .attr('y', (n) => spot.get(n.id)?.sub ?? 0);
  };

  const applyHover = () => {
    const near = hovered ? neighbours(hovered) : null;
    const groups = gNodes.selectAll<SVGGElement, SimNode>('g.sg-node');
    groups
      .select<SVGPathElement>('path.sg-body')
      .attr('d', (n) => bodyPath(n, n === hovered ? n.r + 4 : n.r));
    const dim = (n: SimNode) => (!near || near.has(n.id) ? 1 : 0.2);
    groups.attr('opacity', dim);
    const tagged = tagGroups().attr('opacity', dim);
    tagged.select<SVGTextElement>('text.sg-label').text((n) => labelOf(n));
    tagged.select<SVGTextElement>('text.sg-sub').text((n) => subOf(n));
    layoutLabels();
    gLinks
      .selectAll<SVGPathElement, SimLink>('path')
      .interrupt()
      .attr('opacity', (l) => {
        const base = linkStyle(l).opacity;
        if (!near || !hovered) return base;
        return l.source.id === hovered.id || l.target.id === hovered.id
          ? Math.max(base, 0.85)
          : base * 0.15;
      });
  };

  const anchors = new Map<string, HTMLElement>();
  /** Where each anchored chip sits, in graph units, for the label layout to keep clear of. */
  const chipBoxes = new Map<string, { x0: number; y0: number; x1: number; y1: number }>();
  const placeAnchors = () => {
    chipBoxes.clear();
    // Read every size first, then write every position: one layout per frame, not one per badge.
    // An inside element's size is the node's, so it is never read.
    const placed = [...anchors].map(([id, el]) => ({
      el,
      n: nodeById.get(id),
      w: hosted.has(id) ? 0 : el.offsetWidth,
      h: hosted.has(id) ? 0 : el.offsetHeight,
    }));
    const pad = 4;
    for (const { el, n, w, h } of placed) {
      if (!n) {
        el.style.visibility = 'hidden';
        continue;
      }
      const cx = width / 2 + view.x + view.k * (n.x ?? 0);
      const cy = height / 2 + view.y + view.k * (n.y ?? 0);
      if (hosted.has(n.id)) {
        // The node's bounding square, on whole pixels with its centre on the node's (rounded)
        // centre: what the host draws at a fixed place in it stays put whatever its text does.
        const R = Math.max(1, Math.round(view.k * n.r));
        const size = `${2 * R}px`;
        if (el.style.width !== size) {
          el.style.width = size;
          el.style.height = size;
          el.style.setProperty('--node-r', `${R}px`);
        }
        el.dataset.side = 'inside';
        el.style.visibility = 'visible';
        el.style.opacity = intro ? String(intro.labels) : '';
        el.style.transform = `translate(${Math.round(cx) - R}px, ${Math.round(cy) - R}px)`;
        continue;
      }
      const r = view.k * n.r + 8;
      // Beside the node, on the side away from the centre, so the middle of the graph stays
      // clear; the other side when that one has no room. Kept inside the canvas vertically.
      const outward = (n.x ?? 0) < 0 ? 'left' : 'right';
      const fits = (side: string) =>
        side === 'right' ? cx + r + w <= width - pad : cx - r - w >= pad;
      const side = fits(outward) ? outward : outward === 'left' ? 'right' : 'left';
      const x = side === 'right' ? cx + r : cx - r - w;
      const y = Math.max(pad, Math.min(height - h - pad, cy - h / 2));
      el.dataset.side = side;
      el.style.visibility = 'visible';
      el.style.opacity = intro ? String(intro.labels) : '';
      const left = Math.max(pad, Math.min(width - w - pad, x));
      el.style.transform = `translate(${Math.round(left)}px, ${Math.round(y)}px)`;
      if (w > 0 && h > 0) {
        const gx = (sx: number) => (sx - width / 2 - view.x) / view.k;
        const gy = (sy: number) => (sy - height / 2 - view.y) / view.k;
        chipBoxes.set(n.id, { x0: gx(left), y0: gy(y), x1: gx(left + w), y1: gy(y + h) });
      }
    }
  };
  const anchor = (
    nodeId: string,
    el: HTMLElement | null,
    placement: SwarmAnchorPlacement = 'beside',
  ) => {
    if (el) anchors.set(nodeId, el);
    else anchors.delete(nodeId);
    const inside = Boolean(el) && placement === 'inside';
    if (inside !== hosted.has(nodeId)) {
      if (inside) hosted.add(nodeId);
      else hosted.delete(nodeId);
      if (el && !inside) {
        el.style.width = '';
        el.style.height = '';
        el.style.removeProperty('--node-r');
      }
      // The node's own name, sub-line, count and body change hands. Once per frame at most: a
      // host that re-attaches its element (a ref released and set again) costs nothing.
      if (graph && !restyle) restyle = requestAnimationFrame(applyHosting);
    }
    placeAnchors();
  };
  const applyHosting = () => {
    restyle = 0;
    const now = [...hosted].sort().join('|');
    if (now === drawnHosted || !graph) return;
    renderStatic();
  };

  const draw = () => {
    // The layout keeps every place on the canvas (`limitOf`); drawing never moves a node.
    const scaleOf = intro?.scale;
    const place = (n: SimNode) => {
      const k = scaleOf?.get(n.id) ?? life.get(n.id)?.scale;
      return `translate(${n.x ?? 0},${n.y ?? 0})${k !== undefined && k < 1 ? ` scale(${k})` : ''}`;
    };
    gNodes.selectAll<SVGGElement, SimNode>('g.sg-node').attr('transform', place);
    tagGroups().attr('transform', place);
    gLinks
      .selectAll<SVGPathElement, SimLink>('path')
      .attr('d', (l) => curvePath(l.source, l.target));
    gBloom
      .selectAll<SVGCircleElement, SimNode>('circle')
      .attr('cx', (n) => n.x ?? 0)
      .attr('cy', (n) => n.y ?? 0);
    gRings
      .selectAll<SVGCircleElement, SimNode>('circle')
      .attr('cx', (n) => n.x ?? 0)
      .attr('cy', (n) => n.y ?? 0)
      .attr('r', (n) => n.r + 5);
    layoutLabels();
    placeAnchors();
  };

  // ---- motion ------------------------------------------------------------------------------

  const spawn = (p: Omit<Particle, 'key' | 'start'> & { delay?: number }, now: number) => {
    particles.push({ ...p, key: nextKey++, start: now + (p.delay ?? 0) });
  };

  const ripple = (node: SimNode, color: string, now: number, big = false) => {
    ripples.push({ key: nextKey++, node, start: now, color, big });
  };

  /**
   * Fire one event onto the graph: a spark along its path, node by node, and a ripple where it
   * lands. A merge passes through the integration branch on its way into its sector.
   */
  const fireFlow = (flow: SwarmFlow, source: 'live' | 'replay', now: number) => {
    const path = flow.path.map((id) => nodeById.get(id)).filter((n): n is SimNode => Boolean(n));
    if (path.length < 2) return;
    const coloured = (flow.kind === 'merge' ? path : [...path].reverse()).find(
      (n) => n.kind !== 'hub' && n.color,
    );
    const effect = (options.effectOf ?? defaultEffectOf)(flow);
    // A buried idea fades out gently in its own colour; only a request for changes is red.
    const color =
      effect === 'bury'
        ? theme.fgMuted
        : flow.kind === 'reject'
          ? theme.critical
          : coloured
            ? colorOf(coloured)
            : theme.fg;
    const last = path[path.length - 1]!;
    const emit = (kind: SwarmEffectKind, node: SimNode, c: string) =>
      options.onEffect?.({ kind, nodeId: node.id, color: c, delta: flow.delta, source, flow });
    const tier = beamTier(flow, effect);
    const step = STEP_MS[flow.kind] ?? 850;
    // Ask the beam budget before anything moves: routine events never beam, and a burst or a
    // crowded moment folds into one beam with a count.
    const offer =
      motion && tier !== 'none'
        ? beams.offer(`${flow.sector ?? ''}|${flow.kind}`, now, step * (path.length - 1))
        : null;
    /** Events this beam carries by the time it lands (a burst folds in while it flies). */
    const carried = () => (offer?.fire ? beams.count(offer.id) : 1);
    const times = (n: number) => (n > 1 ? ` ×${n}` : '');
    const land = () => {
      const n = carried();
      if (effect) emit(effect, last, effect === 'bury' && coloured ? colorOf(coloured) : color);
      if (effect === 'bury') {
        ripple(last, color, performance.now());
        pop(last, 0.3);
        celebrate(last, color, 0, 'buried');
        return;
      }
      ripple(last, color, performance.now(), flow.kind === 'merge');
      pop(last, flow.kind === 'merge' ? 1.6 : 0.7);
      if (flow.kind === 'merge') {
        celebrate(last, color, 18, n > 1 ? `${n} merged` : `+${flow.weight} merged`);
        const hub = graph ? nodeById.get(graph.hubId) : undefined;
        if (hub) pop(hub, 0.8);
      } else if (flow.kind === 'milestone')
        celebrate(
          last,
          color,
          10,
          `${effect === 'rung' ? 'rung cleared' : 'milestone'}${times(n)}`,
        );
      else if (flow.kind === 'rating' && flow.delta) {
        pop(last, flow.delta > 0 ? 1.4 : 0.6);
        celebrate(
          last,
          flow.delta > 0 ? theme.good : theme.fgMuted,
          flow.delta > 0 ? 10 : 0,
          `${flow.delta > 0 ? '+' : ''}${flow.delta}`,
        );
      } else if (flow.kind === 'reject') celebrate(last, color, 0, `changes asked${times(n)}`);
      else if (n > 1) celebrate(last, color, 0, `×${n}`);
    };
    options.onFlow?.(flow, source);
    if (!motion) {
      land();
      return;
    }
    if (!offer?.fire) {
      // No beam: a routine event, or one folded into a beam already flying (or the next one).
      // A soft pulse on its node at most; a big moment over the cap keeps a quiet ripple.
      pop(last, 0.25);
      if (tier === 'big') ripple(last, color, now);
      return;
    }
    const big = tier === 'big';
    const tone = `color-mix(in srgb, ${color} 72%, ${theme.fgMuted})`;
    for (let i = 0; i < path.length - 1; i++) {
      const final = i === path.length - 2;
      const via = path[i + 1]!;
      spawn(
        {
          from: path[i]!,
          to: via,
          duration: step,
          color,
          tone,
          big,
          size: big ? BIG_BEAM_HEAD : BEAM_HEAD,
          spark: true,
          delay: i * step,
          onArrive: final
            ? land
            : () => {
                ripple(via, color, performance.now());
                pop(via, 0.5);
                emit('pass', via, color);
              },
        },
        now,
      );
    }
  };

  /** Re-derive radii (effort changes during replay) without restarting the layout. */
  const resize = () => {
    for (const n of nodeById.values()) n.r = rOf(n);
    gNodes
      .selectAll<SVGGElement, SimNode>('g.sg-node')
      .select<SVGPathElement>('path.sg-body')
      .attr('d', (n) => bodyPath(n, n.r));
    tagGroups()
      .select<SVGTextElement>('text.sg-glyph')
      .filter((n) => n.kind === 'sector')
      .attr('font-size', (n) => Math.max(MIN_LABEL_PX, Math.min(15, n.r * 0.5)));
    countUp();
    renderArcs(gNodes.selectAll<SVGGElement, SimNode>('g.sg-node'));
    gBloom
      .selectAll<SVGCircleElement, SimNode>('circle')
      .filter((n) => !motion || !n.active)
      .attr('r', (n) => n.r * 2.2);
    layoutLabels();
  };

  /** Live agents stream effort into what they are on: their branch's worktree, or the PR they gate. */
  const ambient = (now: number) => {
    if (!motion || replayOverride) return;
    for (const l of simLinks) {
      if (!l.active || l.kind !== 'assignment') continue;
      const last = lastEmit.get(l.id) ?? 0;
      if (now - last < AMBIENT_MS + (hash(l.id) % 700)) continue;
      lastEmit.set(l.id, now);
      spawn(
        {
          from: l.source,
          to: l.target,
          duration: 1100,
          color: colorOf(l.source),
          size: 1.4,
          spark: false,
        },
        now,
      );
    }
  };

  let dashOffset = 0;
  const timer = d3.timer(() => {
    const now = performance.now();
    if (intro) stepIntro(now);
    if (resized && now - resized >= RESIZE_QUIET_MS) refit();
    if (pending) runLayout(SLICE_MS);
    const moved = stepMoves(now);
    if (stepLife(now) || moved) draw();
    ambient(now);
    advanceReplay(now);

    const alive: Particle[] = [];
    for (const p of particles) {
      const t = (now - p.start) / p.duration;
      if (t >= 1) {
        p.onArrive?.();
        continue;
      }
      alive.push(p);
    }
    particles = alive;
    ripples = ripples.filter((r) => now - r.start < (r.big ? RIPPLE_MS * 1.6 : RIPPLE_MS));
    bursts = bursts.filter((b) => now - b.start < BURST_MS);
    floaters = floaters.filter((f) => now - f.start < FLOAT_MS);

    const visible = particles.filter((p) => now >= p.start);

    // Sparks drag a comet tail behind them along the curve they travel.
    gTrails
      .selectAll<SVGPathElement, Particle>('path')
      .data(layered ? [] : visible.filter((p) => p.spark), (p) => p.key)
      .join((enter) => enter.append('path'))
      .each(function (p) {
        const t = Math.max(0, Math.min(1, (now - p.start) / p.duration));
        const head = d3.easeCubicInOut(t);
        const tail = Math.max(0, head - TRAIL);
        const pts: string[] = [];
        for (let i = 0; i <= 10; i++) {
          const q = pointAt(p.from, p.to, tail + ((head - tail) * i) / 10);
          pts.push(`${q.x.toFixed(1)},${q.y.toFixed(1)}`);
        }
        d3.select(this)
          .attr('d', `M${pts.join('L')}`)
          .style('stroke', p.tone ?? p.color)
          .attr('stroke-width', p.big ? BIG_BEAM_WIDTH : BEAM_WIDTH)
          .attr('stroke-linecap', 'round')
          .attr('stroke-opacity', (p.big ? BIG_BEAM_ALPHA : BEAM_ALPHA) * 0.8 * beamFade(t));
      });
    gParticles
      .selectAll<SVGCircleElement, Particle>('circle')
      .data(visible, (p) => p.key)
      .join((enter) => enter.append('circle'))
      .each(function (p) {
        const t = Math.max(0, Math.min(1, (now - p.start) / p.duration));
        const e = d3.easeCubicInOut(t);
        const pos = pointAt(p.from, p.to, e);
        d3.select(this)
          .attr('cx', pos.x)
          .attr('cy', pos.y)
          .attr('r', p.size * (p.spark ? 1 : 0.6 + 0.4 * Math.sin(Math.PI * t)))
          .style('fill', p.tone ?? p.color)
          .attr(
            'fill-opacity',
            p.spark
              ? (p.big ? BIG_BEAM_ALPHA : BEAM_ALPHA) * beamFade(t)
              : 0.3 * Math.sin(Math.PI * t),
          )
          // Only big moments glow; every other beam is a quiet line.
          .attr('filter', p.big ? glowUrl : null);
      });

    gRipples
      .selectAll<SVGCircleElement, Ripple>('circle')
      .data(ripples, (r) => r.key)
      .join((enter) => enter.append('circle').attr('fill', 'none'))
      .each(function (r) {
        const t = (now - r.start) / RIPPLE_MS;
        d3.select(this)
          .attr('cx', r.node.x ?? 0)
          .attr('cy', r.node.y ?? 0)
          .attr('r', r.node.r + 4 + d3.easeCubicOut(t) * (r.big ? 64 : 26))
          .style('stroke', r.color)
          .attr('stroke-width', (r.big ? 4 : 2.5) * (1 - t))
          .attr('stroke-opacity', 1 - t);
      });

    gBursts
      .selectAll<SVGCircleElement, Burst>('circle')
      .data(
        bursts.filter((b) => now >= b.start),
        (b) => b.key,
      )
      .join((enter) => enter.append('circle'))
      .each(function (b) {
        const t = (now - b.start) / BURST_MS;
        const e = d3.easeCubicOut(t);
        const d = b.node.r * 0.6 + e * b.dist;
        d3.select(this)
          .attr('cx', (b.node.x ?? 0) + Math.cos(b.angle) * d)
          .attr('cy', (b.node.y ?? 0) + Math.sin(b.angle) * d + t * t * 10)
          .attr('r', b.size * (1 - t * 0.7))
          .style('fill', b.color)
          .attr('fill-opacity', 1 - t);
      });

    gFloaters
      .selectAll<SVGTextElement, Floater>('text')
      .data(floaters, (f) => f.key)
      .join((enter) =>
        enter
          .append('text')
          .attr('text-anchor', 'middle')
          .attr('font-size', 12)
          .attr('font-weight', 700)
          .style('font-family', theme.monoFont)
          .style('paint-order', 'stroke')
          .style('stroke', theme.panel)
          .attr('stroke-width', 3)
          .text((f) => f.text),
      )
      .each(function (f) {
        const t = (now - f.start) / FLOAT_MS;
        const rise = d3.easeCubicOut(t) * 34;
        d3.select(this)
          .attr('x', f.node.x ?? 0)
          .attr('y', (f.node.y ?? 0) - f.node.r - 12 - rise)
          .style('fill', f.color)
          .attr('opacity', t < 0.15 ? t / 0.15 : 1 - Math.max(0, (t - 0.55) / 0.45));
      });

    if (motion && !intro) {
      dashOffset = (dashOffset - 0.4) % 1000;
      gLinks
        .selectAll<SVGPathElement, SimLink>('path')
        .filter((l) => l.active && !life.has(l.source.id) && !life.has(l.target.id))
        .attr('stroke-dashoffset', dashOffset);
    }
  });

  // ---- intro -------------------------------------------------------------------------------

  const linkPaths = () => gLinks.selectAll<SVGPathElement, SimLink>('path');
  const labelTexts = () => gTags.selectAll<SVGTextElement, SimNode>('text.sg-label, text.sg-sub');

  const startIntro = (mode: 'full' | 'short') => {
    const hubId = graph?.hubId;
    const target = new Map<string, { x: number; y: number }>();
    for (const n of nodeById.values()) target.set(n.id, { x: n.x ?? 0, y: n.y ?? 0 });
    const plan = planIntro(
      [...nodeById.values()].map((n) => ({
        id: n.id,
        role: n.id === hubId ? 'hub' : n.kind === 'sector' ? 'sector' : 'other',
        sectorId: n.sectorId ? `sector:${n.sectorId}` : null,
        x: n.x ?? 0,
        y: n.y ?? 0,
      })),
      mode === 'short' ? SHORT_INTRO : FULL_INTRO,
    );
    // Only on a view nobody has moved yet: open zoomed in on the hub and pull back.
    const camera = view.k === 1 && view.x === 0 && view.y === 0;
    intro = { plan, start: performance.now(), target, scale: new Map(), camera, labels: 0 };
    // Edges draw on from source to target: a unit-length dash slid along the path.
    linkPaths()
      .interrupt()
      .attr('pathLength', 1)
      .attr('stroke-dasharray', '1 1')
      .attr('stroke-dashoffset', 1)
      .attr('opacity', (l) => linkStyle(l).opacity);
    stepIntro(intro.start);
  };

  const stepIntro = (now: number) => {
    if (!intro) return;
    const t = now - intro.start;
    if (t >= intro.plan.totalMs) {
      finishIntro();
      return;
    }
    const { plan, target, scale } = intro;
    for (const n of nodeById.values()) {
      const to = target.get(n.id);
      if (!to) continue;
      const pose = introPose(to, plan.timing.get(n.id), t);
      n.x = pose.x;
      n.y = pose.y;
      scale.set(n.id, pose.scale);
    }
    const fade = (n: SimNode) => {
      const to = target.get(n.id);
      return to ? introPose(to, plan.timing.get(n.id), t).opacity : 1;
    };
    gNodes.selectAll<SVGGElement, SimNode>('g.sg-node').style('opacity', fade);
    tagGroups().style('opacity', fade);
    linkPaths().attr(
      'stroke-dashoffset',
      (l) => 1 - introEdge(plan.timing.get(l.source.id), plan.timing.get(l.target.id), t),
    );
    intro.labels = introLabels(plan, t);
    labelTexts().style('opacity', intro.labels);
    const halo = easeOut(t / Math.max(1, plan.totalMs));
    gBloom.style('opacity', halo);
    gRings.style('opacity', halo);
    if (intro.camera) svg.call(zoom.transform, d3.zoomIdentity.scale(introCamera(plan, t)));
    draw();
  };

  /** Land the intro: every node at its place, styles back. Nothing moves after it. */
  const finishIntro = () => {
    if (!intro) return;
    const { target, camera } = intro;
    intro = null;
    for (const n of nodeById.values()) {
      const to = target.get(n.id);
      if (!to) continue;
      n.x = to.x;
      n.y = to.y;
    }
    gNodes.selectAll<SVGGElement, SimNode>('g.sg-node').style('opacity', null);
    tagGroups().style('opacity', null);
    labelTexts().style('opacity', null);
    gBloom.style('opacity', null);
    gRings.style('opacity', null);
    linkPaths()
      .attr('pathLength', null)
      .attr('stroke-dasharray', (l) => linkStyle(l).dash)
      .attr('stroke-dashoffset', null);
    if (camera) svg.call(zoom.transform, d3.zoomIdentity);
    draw();
  };

  // ---- arriving and leaving ---------------------------------------------------------------

  const linksOf = (ids: Set<string>) =>
    linkPaths().filter((l) => ids.has(l.source.id) || ids.has(l.target.id));

  /** One frame of arrivals and departures: sizes, opacities, edges. True when anything changed. */
  const stepLife = (now: number) => {
    if (!arrivals.size && !departures.size && !settled.size) return false;
    const gone: string[] = [];
    for (const [id, a] of arrivals) {
      if (!nodeById.has(id)) {
        arrivals.delete(id);
        life.delete(id);
        continue;
      }
      const p = progressAt(now, a.start, ARRIVAL.durationMs);
      const pose = arrivalPose(p);
      if (p >= 1) {
        arrivals.delete(id);
        life.delete(id);
        settled.add(id);
      } else life.set(id, pose);
    }
    for (const [id, d] of departures) {
      const p = progressAt(now, d.start, DEPARTURE.durationMs);
      life.set(id, departurePose(p));
      if (p >= 1) gone.push(id);
    }

    const posed = (n: SimNode) => life.has(n.id) || settled.has(n.id);
    const pose = (n: SimNode) => life.get(n.id);
    gNodes
      .selectAll<SVGGElement, SimNode>('g.sg-node')
      .filter(posed)
      .style('opacity', (n) => (pose(n) ? String(pose(n)!.opacity) : null));
    tagGroups()
      .filter(posed)
      .each(function (n) {
        const p = pose(n);
        const g = d3.select(this);
        g.select('g.sg-tag-inner').style('opacity', () => (p ? String(p.opacity) : null));
        g.selectAll('text.sg-label, text.sg-sub').style('opacity', () =>
          p ? String(Math.max(0, p.label)) : null,
        );
      });
    const touched = new Set([...life.keys(), ...settled]);
    linksOf(touched).each(function (l) {
      const el = d3.select(this);
      const leaving = departures.has(l.source.id) || departures.has(l.target.id);
      const arriving = arrivals.has(l.source.id) || arrivals.has(l.target.id);
      const base = linkStyle(l);
      if (leaving) {
        const k = Math.min(life.get(l.source.id)?.edge ?? 1, life.get(l.target.id)?.edge ?? 1);
        el.attr('pathLength', null)
          .style('stroke-dasharray', null)
          .style('stroke-dashoffset', null)
          .style('opacity', String(base.opacity * k))
          .style('stroke-width', `${base.width * k}px`);
      } else if (arriving) {
        // Edges draw on from the parent's end: the end that is not arriving.
        const k = Math.min(life.get(l.source.id)?.edge ?? 1, life.get(l.target.id)?.edge ?? 1);
        const fromTarget = arrivals.has(l.source.id) && !arrivals.has(l.target.id);
        el.attr('pathLength', 1)
          .style('stroke-dasharray', '1 1')
          .style('stroke-dashoffset', String(fromTarget ? k - 1 : 1 - k))
          .style('opacity', String(base.opacity))
          .style('stroke-width', null);
      } else
        el.attr('pathLength', null)
          .style('stroke-dasharray', null)
          .style('stroke-dashoffset', null)
          .style('opacity', null)
          .style('stroke-width', null);
    });
    settled.clear();
    if (gone.length) finishDepartures(gone);
    return true;
  };

  /** A node leaves the renderer's books. */
  const forget = (id: string) => {
    nodeById.delete(id);
    departures.delete(id);
    life.delete(id);
    arrivals.delete(id);
    moves.delete(id);
    places.delete(id);
    homes.delete(id);
    placedBy.delete(id);
    arcShown.delete(id);
    shownNumber.delete(id);
  };

  /** Faded out: the nodes leave the graph. Nothing else moves into the room they leave. */
  const finishDepartures = (ids: string[]) => {
    for (const id of ids) forget(id);
    simLinks = simLinks.filter((l) => nodeById.has(l.source.id) && nodeById.has(l.target.id));
    renderStatic();
  };

  // ---- public API --------------------------------------------------------------------------

  const update = (next: SwarmGraph, updateOptions: SwarmUpdateOptions = {}) => {
    // A live refresh mid-intro lands the intro at once.
    finishIntro();
    const first = graph === null;
    const quiet = first || Boolean(updateOptions.quiet);
    graph = next;
    const keep = new Set(next.nodes.map((n) => n.id));
    const now = performance.now();
    // Gone nodes fade out in place (staggered) and leave after; at once without motion.
    let leaving = 0;
    for (const [id, n] of [...nodeById]) {
      if (keep.has(id)) continue;
      if (!motion || first) {
        forget(id);
        continue;
      }
      if (departures.has(id)) continue;
      arrivals.delete(id);
      departures.set(id, {
        start: now + staggerAt(leaving++, DEPARTURE.staggerMs, DEPARTURE.maxSteps),
      });
      n.active = false;
    }
    let arriving = 0;

    const advanced: { node: SimNode; stage: SwarmStage }[] = [];
    for (const n of next.nodes) {
      const existing = nodeById.get(n.id);
      if (existing && departures.has(n.id)) {
        // Back before it finished leaving: it stays where it is and comes back to full.
        departures.delete(n.id);
        life.delete(n.id);
        settled.add(n.id);
      }
      if (existing) {
        const was = existing.workItem?.stage;
        Object.assign(existing, n);
        existing.r = rOf(existing);
        const now = n.workItem?.stage;
        if (!first && was && now && was !== now) advanced.push({ node: existing, stage: now });
      } else {
        // No position yet: the layout gives it one, and it fades in right there.
        const node: SimNode = { ...n, r: 0 };
        node.r = rOf(node);
        nodeById.set(n.id, node);
        if (motion && !first)
          arrivals.set(n.id, {
            start: now + staggerAt(arriving++, ARRIVAL.staggerMs, ARRIVAL.maxSteps),
          });
      }
    }
    placeRing();

    // Departing nodes keep their edges until they have faded with them.
    const nextLinks = new Set(next.links.map((l) => l.id));
    const fadingLinks = simLinks.filter(
      (l) =>
        !nextLinks.has(l.id) &&
        (departures.has(l.source.id) || departures.has(l.target.id)) &&
        nodeById.has(l.source.id) &&
        nodeById.has(l.target.id),
    );
    simLinks = next.links
      .filter((l) => nodeById.has(l.source) && nodeById.has(l.target))
      .map((l) => ({
        ...l,
        source: nodeById.get(l.source)!,
        target: nodeById.get(l.target)!,
      }))
      .concat(fadingLinks);

    const introMode = motion ? (options.intro ?? 'full') : 'none';
    // Every place is worked out off-screen before anything moves.
    relayout();

    renderStatic();
    if (first && introMode !== 'none' && nodeById.size > 0) startIntro(introMode);
    // Pose arrivals before drawing, so a new node (or one waiting on a sliced layout) and its
    // edges never show for a frame before they fade in.
    stepLife(performance.now());
    draw();

    // A work item moving to its next stage (branch → pull request → approved) gets its moment.
    for (const { node, stage } of advanced) {
      const color =
        stage === 'approved' ? theme.good : stage === 'changes' ? theme.warning : colorOf(node);
      ripple(node, color, performance.now(), stage === 'merged');
      pop(node, 1.2);
      celebrate(
        node,
        color,
        stage === 'approved' || stage === 'merged' ? 12 : 6,
        STAGE_LABEL[stage],
      );
    }

    // Events new since the last update spark across the graph; the first load only marks them.
    let delay = 0;
    for (const f of next.flows) {
      if (seenFlows.has(f.id)) continue;
      seenFlows.add(f.id);
      if (quiet || replayOverride) continue;
      const t = setTimeout(() => {
        liveTimers.delete(t);
        fireFlow(f, 'live', performance.now());
      }, delay);
      liveTimers.add(t);
      delay = Math.min(delay + 220, 4000);
    }
    // Forget the oldest ids past the cap, so a page open for days does not keep every id it
    // ever drew (#197). Ids still in the graph are kept, so none sparks a second time.
    if (seenFlows.size > SEEN_CAP) {
      const current = new Set(next.flows.map((f) => f.id));
      for (const id of seenFlows) {
        if (seenFlows.size <= SEEN_CAP) break;
        if (!current.has(id)) seenFlows.delete(id);
      }
    }
  };

  const clearEffects = () =>
    options.onEffect?.({
      kind: 'clear',
      nodeId: '',
      color: '',
      delta: null,
      source: 'replay',
      flow: null,
    });

  const replayState = (r: ReplayRun): SwarmReplayState => {
    const i = r.next;
    const gap = r.plan.gaps.find((g) => g.index === i - 1);
    return {
      at: r.plan.flows[i - 1]?.at ?? r.plan.startAt ?? new Date().toISOString(),
      index: i,
      total: r.plan.flows.length,
      playing: r.playing,
      speed: r.speed,
      done: r.done,
      snapshot: r.snap,
      gapMs: gap ? gap.ms : null,
    };
  };
  const emitReplay = () => {
    if (run) options.onReplay?.(replayState(run));
  };

  /** Show a snapshot's effort on the nodes (sectors and hub grow as work lands). */
  const showSnapshot = (snap: SwarmReplaySnapshot) => {
    replayOverride = new Map(Object.entries(snap.effort));
    resize();
  };

  /** Most events a single frame sparks; a bigger jump (a hidden tab) lands the rest silently. */
  const FRAME_SPARKS = 6;
  /** Node sizes follow the playback at most this often: resizing every node is the costly part. */
  const RESIZE_MS = 160;

  /** One frame of playback: move the clock and fire what it passed. */
  const advanceReplay = (now: number) => {
    const r = run;
    if (!r) return;
    const dt = Math.min(250, Math.max(0, now - r.last));
    r.last = now;
    if (!r.playing) return;
    const step = stepPlayhead(r, r.plan.total, dt);
    r.clock = step.clock;
    const due = indexAtTime(r.plan, r.clock);
    if (due > r.next) {
      const from = Math.max(r.next, due - FRAME_SPARKS);
      for (let i = r.next; i < due; i++) {
        const f = r.plan.flows[i]!;
        applyFlow(r.snap, f, r.plan.hubId);
        if (i >= from && sparksAt(r.plan, i)) fireFlow(f, 'replay', now);
        else if (i >= from) options.onFlow?.(f, 'replay');
      }
      r.next = due;
      r.dirty = true;
    }
    // Hosts re-render on every state; the playhead itself glides on `replayClock()`.
    if (r.dirty && (now - r.shownAt >= RESIZE_MS || r.clock >= r.plan.total)) {
      r.dirty = false;
      r.shownAt = now;
      showSnapshot(r.snap);
      emitReplay();
    }
    if (step.ended) finishReplay();
  };

  /**
   * The replay played to its end, which is now: hand the graph back to live (#278). The last frame
   * is the live state, so nothing jumps: sizes go back to live effort (the same at the end), and
   * whatever is still in flight lands on its own instead of being swept away.
   */
  const finishReplay = () => {
    run = null;
    replayOverride = null;
    resize();
    renderStatic();
    options.onReplay?.(null, 'end');
  };

  const stopReplay = () => {
    run = null;
    if (replayOverride) {
      replayOverride = null;
      particles = [];
      bursts = [];
      floaters = [];
      beams.reset();
      clearEffects();
      resize();
      renderStatic();
      options.onReplay?.(null, 'stop');
    }
  };

  const replay = (planOrDuration: SwarmReplayPlan | number = 30_000) => {
    if (!graph) return;
    finishIntro();
    stopReplay();
    const plan =
      typeof planOrDuration === 'number'
        ? planReplay(graph.flows, graph.hubId, { mode: 'all', durationMs: planOrDuration })
        : planOrDuration;
    if (!plan.flows.length) return;
    run = {
      plan,
      clock: 0,
      next: 0,
      playing: true,
      speed: 1,
      done: false,
      snap: stateAt(plan.seed, [], 0, plan.hubId),
      last: performance.now(),
      dirty: false,
      shownAt: 0,
    };
    particles = [];
    showSnapshot(run.snap);
    renderStatic();
    emitReplay();
  };

  const setPlaying = (playing: boolean) => {
    if (!run) return;
    if (playing && run.done) {
      // Play after the end starts over from the window's beginning.
      seek(0);
      run.done = false;
    }
    run.playing = playing;
    run.last = performance.now();
    emitReplay();
  };

  const setSpeed = (speed: number) => {
    if (!run) return;
    run.speed = Math.max(0.25, Math.min(8, speed));
    emitReplay();
  };

  const jump = (index: number, clock: number) => {
    const r = run;
    if (!r) return;
    const i = Math.max(0, Math.min(index, r.plan.flows.length));
    r.next = i;
    r.clock = clock;
    r.done = parkedAtEnd(r, r.plan.total);
    r.snap = stateAt(r.plan.seed, r.plan.flows, i, r.plan.hubId);
    r.last = performance.now();
    r.dirty = false;
    r.shownAt = r.last;
    particles = [];
    bursts = [];
    floaters = [];
    beams.reset();
    clearEffects();
    showSnapshot(r.snap);
    emitReplay();
  };

  const seek = (index: number) => {
    if (!run) return;
    const to = seekIndex(run.plan, index);
    jump(to.index, to.clock);
  };

  const seekTime = (ms: number) => {
    if (!run) return;
    const to = seekOffset(run.plan, ms);
    jump(to.index, to.clock);
  };

  const replayClock = () => (run ? Math.max(0, run.clock) : null);

  const highlight = (nodeId: string | null) => {
    const next = nodeId ? (nodeById.get(nodeId) ?? null) : null;
    if (next === hovered) return;
    hovered = next;
    applyHover();
  };

  const reset = () => {
    svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
  };

  const port: SwarmViewport = { width, height, x: 0, y: 0, k: 1, moved: false };
  const viewport = () => {
    port.width = width;
    port.height = height;
    port.x = view.x;
    port.y = view.y;
    port.k = view.k;
    port.moved = view.k !== 1 || view.x !== 0 || view.y !== 0;
    return port;
  };
  const eachNode = (fn: (node: SwarmNodeView) => void) => {
    for (const n of nodeById.values()) fn(n);
  };
  const eachSpark = (
    fn: (x: number, y: number, color: string, size: number, big: boolean) => void,
  ) => {
    const now = performance.now();
    for (const p of particles) {
      if (now < p.start || !p.spark) continue;
      const t = Math.max(0, Math.min(1, (now - p.start) / p.duration));
      const pos = pointAt(p.from, p.to, d3.easeCubicInOut(t));
      fn(pos.x, pos.y, p.color, p.size, Boolean(p.big));
    }
  };
  const nodeAt = (id: string) => nodeById.get(id) ?? null;
  const setLayered = (on: boolean) => {
    layered = on;
    if (on) bursts = [];
  };

  /** Take the container's current size, if it changed: true when it did. */
  const takeSize = () => {
    const w = Math.max(200, container.clientWidth);
    const h = Math.max(200, container.clientHeight);
    if (w === width && h === height) return false;
    resizedFrom ??= arrangement().kind;
    width = w;
    height = h;
    finishIntro();
    setViewBox();
    placeRing();
    resize();
    return true;
  };

  /** Apply a resize once its reflow is over: the one re-fit it makes. */
  const refit = () => {
    // A step of the reflow its ResizeObserver has not reported yet (observers run after this
    // frame's tick): taken now, so the re-fit is laid out at the size the page ends at instead of
    // being followed by a second one that restarts every glide.
    takeSize();
    const from = resizedFrom;
    resized = 0;
    resizedFrom = null;
    const kind = arrangement().kind;
    if (
      kind === from &&
      Math.abs(width - fitted.width) <= RESIZE_SNAP_PX &&
      Math.abs(height - fitted.height) <= RESIZE_SNAP_PX
    ) {
      // Next to the fitted size: the viewBox follows the canvas, and every node stays where it is.
      // The sectors keep standing where they were placed, so a later layout does not nudge them.
      for (const n of nodeById.values())
        if (n.kind === 'sector') n.ring = places.get(n.id) ?? n.ring;
      return;
    }
    fitted = { width, height };
    if (kind !== from) {
      moveMs = CROSSING_MOVE_MS;
      // Ring to grid or back (#272): the sectors stand somewhere else, so everything is placed
      // afresh around them, each node gliding from where it stands.
      places.clear();
      homes.clear();
      placedBy.clear();
      relayout();
    } else {
      moveMs = RESIZE_MOVE_MS;
      // The layout stretches with the canvas, once: every place scales with the ring, overlaps
      // the new sizes make are cleared, and each node glides there. Back to the old size, back
      // home.
      const R = ringRadii();
      for (const [id, h] of homes)
        if (places.has(id)) places.set(id, { x: h.x * R.x, y: h.y * R.y });
      relayout(true);
    }
    moveMs = MOVE.durationMs;
  };

  const observer = new ResizeObserver(() => {
    if (!takeSize()) return;
    // The nodes move once the canvas stops changing size (`refit`, from the timer).
    resized = performance.now();
  });
  observer.observe(container);

  const destroy = () => {
    cancelAnimationFrame(restyle);
    intro = null;
    run = null;
    liveTimers.forEach(clearTimeout);
    timer.stop();
    pending = null;
    observer.disconnect();
    svg.remove();
    labelSvg.remove();
  };

  return {
    update,
    anchor,
    replay,
    stopReplay,
    setPlaying,
    setSpeed,
    seek,
    seekTime,
    replayClock,
    highlight,
    reset,
    viewport,
    eachNode,
    eachSpark,
    nodeAt,
    setLayered,
    destroy,
  };
};

/**
 * Replay planning: pure, framework-free, game-agnostic. A host picks a window of a graph's
 * flows (the last 24 actively worked hours, or the whole run), seeds the state the graph had
 * when the window opens, and gets a schedule that plays the window back in about a minute.
 *
 * Active time: a gap between two consecutive events longer than the idle threshold counts as
 * at most that threshold, so an overnight pause or a stopped loop does not eat the window.
 */
import { sectorNodeId, type SwarmFlow } from './model';

const HOUR = 3_600_000;
const MINUTE = 60_000;

export const DEFAULT_ACTIVE_MS = 24 * HOUR;
export const DEFAULT_IDLE_MS = 15 * MINUTE;

const timeOf = (f: SwarmFlow) => Date.parse(f.at);

/** A pause between two events longer than the idle threshold. */
export type SwarmIdleGap = {
  /** Index (in the window's flows) of the event after the pause. */
  index: number;
  /** Its real length in milliseconds. */
  ms: number;
};

export type SwarmActiveWindow = {
  /** Index into the flows of the first event in the window. */
  start: number;
  /** Active time the window covers (gaps capped at the idle threshold). */
  activeMs: number;
  /** Idle pauses inside the window, indexed relative to `start`. */
  gaps: SwarmIdleGap[];
};

/**
 * The window of the last `activeMs` of active time, walking back from the newest event. The
 * replay starts at the earliest event that keeps the active time within `activeMs`. An empty or
 * short history gives the whole of it (`start` 0).
 */
export const activeWindow = (
  flows: SwarmFlow[],
  activeMs = DEFAULT_ACTIVE_MS,
  idleMs = DEFAULT_IDLE_MS,
): SwarmActiveWindow => {
  let start = flows.length ? flows.length - 1 : 0;
  let active = 0;
  for (let i = flows.length - 1; i > 0; i--) {
    const gap = Math.max(0, timeOf(flows[i]!) - timeOf(flows[i - 1]!));
    const counted = Math.min(gap, idleMs);
    if (active + counted > activeMs) break;
    active += counted;
    start = i - 1;
  }
  const gaps: SwarmIdleGap[] = [];
  for (let i = start + 1; i < flows.length; i++) {
    const ms = timeOf(flows[i]!) - timeOf(flows[i - 1]!);
    if (ms > idleMs) gaps.push({ index: i - start, ms });
  }
  return { start, activeMs: active, gaps };
};

/** What the graph shows at a moment of a replay: effort per node, ratings, tallies. */
export type SwarmReplaySnapshot = {
  /** Effort landed per node id (sectors and the hub). */
  effort: Record<string, number>;
  /** Sum of rating deltas per sector id. */
  rating: Record<string, number>;
  merges: number;
  milestones: number;
  rejects: number;
  events: number;
};

export const emptySnapshot = (): SwarmReplaySnapshot => ({
  effort: {},
  rating: {},
  merges: 0,
  milestones: 0,
  rejects: 0,
  events: 0,
});

const cloneSnapshot = (s: SwarmReplaySnapshot): SwarmReplaySnapshot => ({
  ...s,
  effort: { ...s.effort },
  rating: { ...s.rating },
});

/** One event onto a snapshot (mutates it): what landing that event adds. */
export const applyFlow = (s: SwarmReplaySnapshot, f: SwarmFlow, hubId: string) => {
  s.events++;
  if (f.sector) {
    const id = sectorNodeId(f.sector);
    s.effort[id] = (s.effort[id] ?? 0) + f.weight;
  }
  if (f.kind === 'merge') {
    s.effort[hubId] = (s.effort[hubId] ?? 0) + f.weight;
    s.merges++;
  }
  if (f.kind === 'milestone') s.milestones++;
  if (f.kind === 'reject') s.rejects++;
  if (f.kind === 'rating' && f.sector && f.delta)
    s.rating[f.sector] = (s.rating[f.sector] ?? 0) + f.delta;
  return s;
};

/** The state after the first `index` of `flows` have landed on top of `seed`. Pure. */
export const stateAt = (
  seed: SwarmReplaySnapshot,
  flows: SwarmFlow[],
  index: number,
  hubId: string,
): SwarmReplaySnapshot => {
  const s = cloneSnapshot(seed);
  const end = Math.max(0, Math.min(index, flows.length));
  for (let i = 0; i < end; i++) applyFlow(s, flows[i]!, hubId);
  return s;
};

/** Events a replay dwells on: merges, rungs and matches decided, rating changes. */
export const isMilestone = (f: SwarmFlow) =>
  f.kind === 'merge' || f.kind === 'milestone' || (f.kind === 'rating' && Boolean(f.delta));

export type SwarmReplayMode = 'window' | 'all';

export type SwarmReplayPlanOptions = {
  mode?: SwarmReplayMode;
  /** Playback length. Default 60 s. */
  durationMs?: number;
  activeMs?: number;
  idleMs?: number;
  /** Time a squeezed idle gap takes on screen. Default 450 ms. */
  beatMs?: number;
  /** Extra hold after a milestone. Default 500 ms. */
  holdMs?: number;
  /** Which events the replay dwells on. Default `isMilestone`. */
  isMilestone?: (f: SwarmFlow) => boolean;
  /**
   * Step between the events of one burst (the games of a match, say: flows sharing a `group`
   * back to back). A burst plays as one beat, as the live graph coalesces it. Default 70 ms.
   */
  burstStepMs?: number;
};

export type SwarmReplayPlan = {
  mode: SwarmReplayMode;
  hubId: string;
  /** The window's flows, in time order. */
  flows: SwarmFlow[];
  /** The state before the window's first event. */
  seed: SwarmReplaySnapshot;
  /** Playback offset (ms) at which each flow fires. */
  times: number[];
  /** Whole playback length, ms. */
  total: number;
  /** Squeezed idle pauses, indexed into `flows`. */
  gaps: SwarmIdleGap[];
  /** Indexes into `flows` of milestones. */
  milestones: number[];
  /**
   * For each flow, the index of the first flow of the burst it belongs to (flows sharing a
   * `group` back to back), or -1 when it is not part of one. A burst's first flow points at
   * itself. Renderers spark a burst sparingly and land its last flow.
   */
  burst: number[];
  startAt: string | null;
  endAt: string | null;
};

/**
 * Plan a replay: pick the window, seed the state before it, and schedule its events. Routine
 * events share time in proportion to their (capped) real gaps; the step into a milestone
 * slows down and a milestone holds briefly; an idle gap is a short beat.
 */
export const planReplay = (
  flows: SwarmFlow[],
  hubId: string,
  options: SwarmReplayPlanOptions = {},
): SwarmReplayPlan => {
  const mode = options.mode ?? 'window';
  const durationMs = options.durationMs ?? 60_000;
  const idleMs = options.idleMs ?? DEFAULT_IDLE_MS;
  const beatMs = options.beatMs ?? 450;
  const holdMs = options.holdMs ?? 500;
  const win =
    mode === 'window'
      ? activeWindow(flows, options.activeMs ?? DEFAULT_ACTIVE_MS, idleMs)
      : activeWindow(flows, Number.POSITIVE_INFINITY, idleMs);
  const shown = flows.slice(win.start);
  const seed = stateAt(emptySnapshot(), flows, win.start, hubId);
  const dwell = options.isMilestone ?? isMilestone;
  const milestones = shown.flatMap((f, i) => (dwell(f) ? [i] : []));
  const isMs = new Set(milestones);
  const gapAt = new Set(win.gaps.map((g) => g.index));
  const burst = burstsOf(shown);
  const burstStep = options.burstStepMs ?? 70;
  /** A burst's later events (not milestones, not after an idle gap) ride on its first beat. */
  const rides = (i: number) => burst[i]! >= 0 && burst[i]! < i && !isMs.has(i) && !gapAt.has(i);

  // Fixed costs first (beats, holds, a floor per event), then real time shares the rest.
  const floor = 30;
  let fixed = 0;
  const weight: number[] = shown.map((f, i) => {
    if (i === 0) return 0;
    if (gapAt.has(i)) {
      fixed += beatMs;
      return 0;
    }
    if (rides(i)) {
      fixed += burstStep;
      return 0;
    }
    fixed += floor;
    const gap = Math.max(0, Date.parse(f.at) - Date.parse(shown[i - 1]!.at));
    return Math.min(gap, idleMs) * (isMs.has(i) ? 3 : 1);
  });
  fixed += milestones.length * holdMs;
  const budget = Math.max(0, durationMs - 1500 - fixed);
  const span = weight.reduce((a, b) => a + b, 0);
  // Without fixed room to spare, everything scales down together.
  const squeeze = fixed > durationMs - 1500 && fixed > 0 ? (durationMs - 1500) / fixed : 1;
  const times: number[] = [];
  let at = 0;
  shown.forEach((_, i) => {
    if (i > 0) {
      const share = span > 0 ? (weight[i]! / span) * budget : budget / Math.max(1, shown.length);
      const step = gapAt.has(i) ? beatMs : rides(i) ? burstStep : floor + share;
      at += step * squeeze + (isMs.has(i - 1) ? holdMs * squeeze : 0);
    }
    times.push(at);
  });
  const total = (times.at(-1) ?? 0) + (isMs.has(shown.length - 1) ? holdMs : 0) + 1500;

  return {
    mode,
    hubId,
    flows: shown,
    seed,
    times,
    total,
    gaps: win.gaps,
    milestones,
    burst,
    startAt: shown[0]?.at ?? null,
    endAt: shown.at(-1)?.at ?? null,
  };
};

/**
 * Bursts: runs of consecutive flows that share a `group` id. Each flow maps to the index of its
 * run's first flow, or -1 when its run is a single flow (or it has no group).
 */
export const burstsOf = (flows: SwarmFlow[]): number[] => {
  const out = new Array<number>(flows.length).fill(-1);
  let i = 0;
  while (i < flows.length) {
    const id = flows[i]!.group?.id;
    let j = i + 1;
    if (id) while (j < flows.length && flows[j]!.group?.id === id) j++;
    if (j - i > 1) for (let k = i; k < j; k++) out[k] = i;
    i = j;
  }
  return out;
};

/** Whether the replay should spark flow `i` (a burst sparks its first, every fourth and last). */
export const sparksAt = (plan: Pick<SwarmReplayPlan, 'burst'>, i: number) => {
  const b = plan.burst[i] ?? -1;
  if (b < 0) return true;
  const last = plan.burst[i + 1]! !== b;
  return last || (i - b) % 4 === 0;
};

/** The playback offset → how many events have fired by then (binary search). */
export const indexAtTime = (plan: SwarmReplayPlan, ms: number) => {
  let lo = 0;
  let hi = plan.times.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (plan.times[mid]! <= ms) lo = mid + 1;
    else hi = mid;
  }
  return lo;
};

/** The playhead of a running replay: its offset (ms) on the plan's schedule, and how it moves. */
export type SwarmPlayhead = { clock: number; playing: boolean; speed: number };

/**
 * One frame of playback: the playhead after `dt` ms of wall time, and whether it played to the
 * end of the schedule (`total`). A replay that plays to its end is over: the host goes back to
 * live (#278). A paused playhead never moves and never ends, even parked at the end by a seek.
 */
export const stepPlayhead = (p: SwarmPlayhead, total: number, dt: number) => {
  if (!p.playing) return { clock: p.clock, ended: false };
  const clock = Math.min(total, p.clock + dt * p.speed);
  return { clock, ended: clock >= total };
};

/**
 * A playhead the viewer left at the end by hand (paused, then seeked there) holds the end card
 * instead of going live: they are looking at it. Playing from there starts the window over.
 */
export const parkedAtEnd = (p: SwarmPlayhead, total: number) => !p.playing && p.clock >= total;

/**
 * Where a seek to "after `index` events" puts the playhead. Seeking past the last event (the
 * scrubber's End key) is the end of the schedule, `total`, not the last event's time: the end
 * holds a beat after it, and only `total` parks the replay at its end card (#278).
 */
export const seekIndex = (plan: SwarmReplayPlan, index: number) => {
  const i = Math.max(0, Math.min(index, plan.flows.length));
  const clock = i >= plan.flows.length && i > 0 ? plan.total : i > 0 ? plan.times[i - 1]! : -1;
  return { index: i, clock };
};

/** Where a seek to a playback offset (ms) puts the playhead, clamped to the schedule. */
export const seekOffset = (plan: SwarmReplayPlan, ms: number) => {
  const clock = Math.max(-1, Math.min(ms, plan.total));
  return { index: indexAtTime(plan, clock), clock };
};

/**
 * The playback offset (ms) at a point on the timeline, `fraction` of its width: its right edge is
 * the end of the schedule exactly, so dragging there reaches the end card (#278).
 */
export const offsetAtFraction = (plan: SwarmReplayPlan, fraction: number) =>
  Math.max(0, Math.min(1, fraction)) * plan.total;

/** What changed over the whole window, for the end card. */
export type SwarmReplaySummary = {
  events: number;
  merges: number;
  /** Events the plan dwelt on. */
  milestones: number;
  /** Rating changes (versions rated). */
  ratings: number;
  rejects: number;
  /** Rating change per sector over the window. */
  rating: Record<string, number>;
};

export const summarizeReplay = (plan: SwarmReplayPlan): SwarmReplaySummary => {
  const end = stateAt(emptySnapshot(), plan.flows, plan.flows.length, plan.hubId);
  return {
    events: end.events,
    merges: end.merges,
    milestones: plan.milestones.length,
    ratings: plan.flows.filter((f) => f.kind === 'rating' && f.delta).length,
    rejects: end.rejects,
    rating: end.rating,
  };
};

/**
 * The shape of `app/swarm/swarm.config.ts`, the one project-owned file that
 * holds every project-specific word, colour and route of the swarm UI.
 *
 * GENERATION (what `rallypoint add swarm-ui` / `add swarm-dashboard` writes,
 * only when the file is absent; it never overwrites it):
 *
 *   swarmConfig field          <- `.rallypoint/swarm.json` field
 *   ------------------------------------------------------------------------
 *   project.name               <- ui.project.name, else the repository name
 *   project.tagline            <- ui.project.tagline, else goal.pitch, else ""
 *   goal.title                 <- goal.title
 *   goal.statement             <- goal.statement
 *   measure.mode               <- measure.mode ("score" | "checks" | "review")
 *   measure.label              <- measure.label, else "Score" in score mode,
 *                                 "Checks" in checks mode, "Review" in review
 *                                 mode
 *   measure.unit               <- measure.unit
 *   measure.direction          <- measure.direction ("higher" | "lower")
 *   targets[i].id              <- targets[i].id
 *   targets[i].name            <- targets[i].name, else targets[i].id
 *   targets[i].description     <- targets[i].description, else ""
 *   targets[i].color           <- ui.targets[<id>].color, else the i-th
 *                                 colour of DEFAULT_TARGET_COLORS below
 *   vocabulary                 <- DEFAULT_VOCABULARY, then ui.vocabulary
 *                                 merged over it key by key
 *   nav                        <- DEFAULT_NAV (not read from swarm.json)
 *   theme.cssVars              <- {} (not read from swarm.json)
 *   integrationBranch          <- not generated (optional). The fleet graph's
 *                                 trunk: set it to `.rallypoint/config.json`'s
 *                                 `integrationBranch`. Absent, the GitHub
 *                                 repository's default branch, else "main"
 *   branchPrefix               <- not generated (optional). Rallypoint's
 *                                 `branchPrefix`; absent, "agent/"
 *
 * A `ui` target added by `ui.includeUiTarget` is an ordinary entry in
 * `targets` and is generated like any other.
 *
 * Everything the UI reads at runtime from Supabase (`swarm_settings.goal`,
 * the measure command, visibility) stays live; this file only decides how
 * it is presented. Where both exist, a non-empty value here wins.
 */

export type MeasureDirection = "higher" | "lower";

/**
 * How the referee judges a change (CONTRACT.md, "Measure modes").
 * - score: a number that must beat the baseline; /swarm draws a score chart.
