/**
 * The adapter from Rallypoint's own state onto the fleet graph's input
 * (`../_graph`, a copy of Swarm Arena's `@rallypoint/swarm-graph`). It is the
 * only file that knows how this scaffold's rows map onto the graph:
 *
 *   sectors     <- the configured targets (swarm.config.ts), with their
 *                  colours, plus any target id found in the data
 *   agents      <- one per agent name in `swarm_sessions`: its latest
 *                  session's role, target, issue, PR and progress note.
 *                  `working` only while that session says so and was seen
 *                  in the last two hours (the `swarm_fleet` rule)
 *   workItems   <- GitHub issues and pull requests, staged by their
 *                  `status:*` / `review:*` labels (`laneOf`), joined by
 *                  "Closes #N", on the `agent/<issue>-<slug>` branch
 *                  `claim.mjs` prescribes. Without GitHub, the issues the
 *                  sessions name
 *   events      <- memory (sessions starting and ending, progress notes,
 *                  referee results, shipped versions, buried ideas,
 *                  protocol changes) and GitHub (issues opened and claimed,
 *                  pull requests opened, reviewed and merged), each at its
 *                  own timestamp, so a replay can play the whole history
 *
 * Pure and deterministic: no reads, no clock. `queries.ts` reads the rows and
 * calls `toSwarmInput`. Every source may be empty; the graph then shows what
 * there is (at least the integration branch and the targets).
 */

import { rallypointBranch } from "../_graph/model";
import type {
  SwarmAgent,
  SwarmCount,
  SwarmEvent,
  SwarmInput,
  SwarmOutcome,
  SwarmSector,
  SwarmStage,
  SwarmWorkItem,
} from "../_graph/model";
import type { SwarmTarget } from "./config-types";
import { laneOf, targetsOf, type GithubItem } from "./github";
import type {
  BuriedRow,
  ProgressRow,
  ProtocolChangeRow,
  ResultRow,
  SessionRow,
  VersionRow,
} from "./types";

/** A session counts as working only if it was seen this recently (the `swarm_fleet` view's window). */
export const LIVE_WINDOW_MS = 2 * 3_600_000;
/** The recent part of a sector's count. */
const RECENT_MS = 24 * 3_600_000;
/** Where work with no target goes when more than one target is configured. */
export const OTHER_SECTOR = "_other";

export type FleetGraphSource = {
  /** The clock (ms) the rows were read at. */
  now: number;
  integrationBranch: string;
  /** Rallypoint's `branchPrefix` (`.rallypoint/config.json`). Default `agent/`. */
  branchPrefix?: string;
  /** Configured targets first, then any found in data (`resolveTargets`). */
  targets: SwarmTarget[];
  sessions: SessionRow[];
  progress: ProgressRow[];
  results: ResultRow[];
  versions: VersionRow[];
  buried: BuriedRow[];
  protocolChanges: ProtocolChangeRow[];
  /** Issues and pull requests, or null when GitHub could not be read. */
  github: GithubItem[] | null;
  /** The word for a shipped version, for sector counts without GitHub. Default `shipped`. */
  shippedUnit?: string;
};

const ms = (iso: string | null | undefined) => {
  const t = iso ? Date.parse(iso) : NaN;
  return Number.isFinite(t) ? t : null;
};

const clip = (text: string, max = 140) => {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;
};

/** The agent a session belongs to: its name, or the session itself when it has none. */
export function agentIdOf(session: Pick<SessionRow, "agent" | "id">): string {
  return session.agent?.trim() || session.id;
}

function lastSeenOf(session: SessionRow): string {
  return session.last_seen_at ?? session.ended_at ?? session.started_at;
}

/** A pull request's stage from its labels; an issue's from its labels and closing state. */
export function stageOf(item: GithubItem): SwarmStage {
  const lane = laneOf(item);
  if (lane) return lane;
  if (item.isPullRequest) return "closed";
  return item.stateReason === "not_planned" ? "closed" : "merged";
}

export function toSwarmInput(source: FleetGraphSource): SwarmInput {
  const { now, github } = source;
  const prefix = source.branchPrefix ?? "agent/";

  /* ── Sectors: the targets, and a fallback for untargeted work ── */
  const targetIds = new Set(source.targets.map((target) => target.id));
  const fallback = source.targets.length === 1 ? source.targets[0]!.id : OTHER_SECTOR;
  let usesOther = false;
  const known = (id: string | null | undefined) => (id && targetIds.has(id) ? id : null);
  const orFallback = (id: string | null) => {
    if (id) return id;
    if (fallback === OTHER_SECTOR) usesOther = true;
    return fallback;
  };

  /* ── Sessions, by agent and by what they hold ── */
  const sessionById = new Map(source.sessions.map((session) => [session.id, session]));
  const targetOfIssue = new Map<number, string>();
  const targetOfPr = new Map<number, string>();
  for (const session of [...source.sessions].sort((a, b) => a.started_at.localeCompare(b.started_at))) {
    const target = known(session.target);
    if (!target) continue;
    if (session.issue !== null) targetOfIssue.set(session.issue, target);
    if (session.pr !== null) targetOfPr.set(session.pr, target);
  }

  /* ── Work items ── */
  const workItems: SwarmWorkItem[] = [];
  const workByIssue = new Map<number, string>();
  const workByPr = new Map<number, string>();
  const itemsByNumber = new Map<number, GithubItem>();

  if (github) {
    for (const item of github) itemsByNumber.set(item.number, item);
    const issues = github.filter((item) => !item.isPullRequest);
    const issueNumbers = new Set(issues.map((item) => item.number));
    const prs = github.filter((item) => item.isPullRequest);
    // The pull request that delivers an issue: an open or merged one, newest first.
    const prFor = (issue: number) =>
      prs
        .filter((pr) => pr.closes.includes(issue) && (pr.state === "open" || pr.mergedAt))
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
    const sectorOf = (item: GithubItem, pr?: GithubItem) =>
      orFallback(
        known(targetsOf(item)[0]) ??
          (pr ? known(targetsOf(pr)[0]) : null) ??
          (item.isPullRequest ? targetOfPr.get(item.number) : targetOfIssue.get(item.number)) ??
          (pr ? targetOfPr.get(pr.number) : undefined) ??
          null,
      );
    const delivered = new Set<number>();
    for (const issue of issues) {
      const pr = prFor(issue.number);
      if (pr) delivered.add(pr.number);
      const id = `issue-${issue.number}`;
      workByIssue.set(issue.number, id);
      if (pr) workByPr.set(pr.number, id);
      workItems.push({
        id,
        sector: sectorOf(issue, pr),
        title: issue.title,
        stage: pr ? stageOf(pr) : stageOf(issue),
        issue: issue.number,
        pr: pr?.number ?? null,
        branch: rallypointBranch(issue.number, issue.title, prefix),
        at: pr?.mergedAt ?? issue.closedAt ?? issue.updatedAt,
      });
    }
    // Pull requests that close no issue in the read (or none at all) are work of their own.
    for (const pr of prs) {
      if (delivered.has(pr.number) || workByPr.has(pr.number)) continue;
      if (pr.closes.some((issue) => issueNumbers.has(issue))) {
        // A superseded or abandoned PR of an issue already drawn: its events go to that issue.
        workByPr.set(pr.number, workByIssue.get(pr.closes.find((n) => issueNumbers.has(n))!)!);
        continue;
      }
      const id = `pr-${pr.number}`;
      workByPr.set(pr.number, id);
      workItems.push({
        id,
        sector: sectorOf(pr),
        title: pr.title,
        stage: stageOf(pr),
        issue: pr.closes[0] ?? null,
        pr: pr.number,
        branch: null,
        at: pr.mergedAt ?? pr.closedAt ?? pr.updatedAt,
      });
    }
  }

  // Without GitHub (or for issues it did not return): the issues sessions hold right now, and
  // those a shipped version names by pull request.
  const shippedPrs = new Set(source.versions.map((row) => row.pr).filter((pr): pr is number => pr !== null));
  const liveSession = (session: SessionRow) =>
    session.status === "working" && now - (ms(lastSeenOf(session)) ?? -Infinity) <= LIVE_WINDOW_MS;
  for (const session of source.sessions) {
    if (session.issue === null || workByIssue.has(session.issue)) continue;
    const shipped = session.pr !== null && shippedPrs.has(session.pr);
    if (!shipped && !liveSession(session)) continue;
    const id = `issue-${session.issue}`;
    workByIssue.set(session.issue, id);
    if (session.pr !== null) workByPr.set(session.pr, id);
    const title = `Issue #${session.issue}`;
    workItems.push({
      id,
      sector: orFallback(known(session.target) ?? targetOfIssue.get(session.issue) ?? null),
      title,
      stage: shipped ? "merged" : session.pr !== null ? "review" : "claimed",
      issue: session.issue,
      pr: session.pr,
      branch: rallypointBranch(session.issue, title, prefix),
      at: lastSeenOf(session),
    });
  }

  const workOf = (issue: number | null | undefined, pr: number | null | undefined) =>
    (pr !== null && pr !== undefined ? workByPr.get(pr) : undefined) ??
    (issue !== null && issue !== undefined ? workByIssue.get(issue) : undefined) ??
    null;
  const sectorOfWork = new Map(workItems.map((item) => [item.id, item.sector]));

  /* ── Agents: one per name, from its latest session ── */
  const latestByAgent = new Map<string, SessionRow>();
  for (const session of source.sessions) {
    const id = agentIdOf(session);
    const current = latestByAgent.get(id);
    if (!current || lastSeenOf(session).localeCompare(lastSeenOf(current)) > 0) latestByAgent.set(id, session);
  }
  const latestNote = new Map<string, ProgressRow>();
  for (const note of source.progress) {
    const current = latestNote.get(note.session_id);
    if (!current || note.created_at.localeCompare(current.created_at) > 0) latestNote.set(note.session_id, note);
  }
  const agents: SwarmAgent[] = [...latestByAgent.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([id, session]) => {
      const note = latestNote.get(session.id);
      return {
        id,
        label: session.agent?.trim() || `session ${session.id.slice(0, 8)}`,
        role: session.role?.trim() || "agent",
        status: liveSession(session) ? "working" : session.status === "working" ? "idle" : "stopped",
        sector: known(session.target),
        workItem: workOf(session.issue, session.pr),
        pr: session.pr,
        activity: note ? clip(note.note) : session.summary ? clip(session.summary) : null,
        lastSeen: lastSeenOf(session),
      };
    });

  /* ── Events ── */
  const events: SwarmEvent[] = [];
  const fromSession = (sessionId: string | null | undefined) => {
    const session = sessionId ? sessionById.get(sessionId) : undefined;
    if (!session) return { agent: null, sector: null, workItem: null };
    const workItem = workOf(session.issue, session.pr);
    return {
      agent: agentIdOf(session),
      sector: known(session.target) ?? (workItem ? sectorOfWork.get(workItem) ?? null : null),
      workItem,
    };
  };

  for (const session of source.sessions) {
    const who = fromSession(session.id);
    const name = session.agent?.trim() || "An agent";
    const role = session.role?.trim();
    events.push({
      ...who,
      id: `session:${session.id}:start`,
      at: session.started_at,
      kind: "session",
      sub: "session-started",
      title: `${name} started a ${role ? `${role} ` : ""}session`,
    });
    if (session.ended_at) {
      events.push({
        ...who,
        id: `session:${session.id}:end`,
        at: session.ended_at,
        kind: "session",
        sub: session.status === "abandoned" ? "session-abandoned" : "session-ended",
        title: `${name} ${session.status === "abandoned" ? "abandoned" : "ended"} the session`,
      });
    }
  }

  for (const note of source.progress) {
    events.push({
      ...fromSession(note.session_id),
      id: `progress:${note.id}`,
      at: note.created_at,
      kind: "progress",
      sub: "progress",
      title: clip(note.note),
    });
  }

  for (const row of source.results) {
    const who = fromSession(row.session_id);
    const workItem = workOf(row.issue, row.pr) ?? who.workItem;
    const outcome: SwarmOutcome | null = row.passed === true ? "win" : row.passed === false ? "loss" : null;
    const ref = row.pr !== null ? ` on #${row.pr}` : row.issue !== null ? ` for #${row.issue}` : "";
    events.push({
      ...who,
      id: `result:${row.id}`,
      at: row.created_at,
      kind: "result",
      sub: "referee",
      sector: known(row.target) ?? who.sector,
      workItem,
      outcome,
      delta: row.delta,
      title: `Referee ${row.passed === true ? "passed" : row.passed === false ? "failed" : "ran"}${ref}`,
    });
  }

  for (const row of source.versions) {
    events.push({
      agent: null,
      id: `version:${row.id}`,
      at: row.created_at,
      kind: "milestone",
      sub: "version",
      sector: known(row.target),
      workItem: workOf(null, row.pr),
      title: `${row.target ? `${row.target} ` : ""}${row.version} shipped`,
    });
  }

  for (const row of source.buried) {
    events.push({
      agent: null,
      id: `buried:${row.id}`,
      at: row.created_at,
      kind: "reject",
      sub: "buried",
      sector: known(row.target),
      workItem: workOf(row.issue, row.pr),
      title: `Buried: ${clip(row.idea, 120)}`,
    });
  }

  for (const row of source.protocolChanges) {
    events.push({
      agent: null,
      id: `protocol:${row.id}`,
      at: row.created_at,
      kind: "protocol",
      sub: "protocol-change",
      sector: null,
      workItem: null,
      title: `Protocol ${row.version}: ${clip(row.summary, 120)}`,
    });
  }

  if (github) {
    for (const item of github) {
      const workItem = workOf(item.isPullRequest ? null : item.number, item.isPullRequest ? item.number : null);
      const base = { agent: null, workItem, sector: workItem ? sectorOfWork.get(workItem) ?? null : null };
      if (item.isPullRequest) {
        events.push({
          ...base,
          id: `gh:pr:${item.number}:opened`,
          at: item.createdAt,
          kind: "pr",
          sub: "pr-opened",
          title: `Pull request #${item.number} opened: ${item.title}`,
        });
        const lane = laneOf(item);
        if (lane === "approved" || lane === "changes") {
          events.push({
            ...base,
            id: `gh:pr:${item.number}:${lane}`,
            at: item.updatedAt,
            kind: lane === "approved" ? "review" : "reject",
            sub: lane === "approved" ? "pr-approved" : "pr-changes",
            title: lane === "approved" ? `Pull request #${item.number} approved` : `Changes asked on pull request #${item.number}`,
          });
        }
        if (item.mergedAt) {
          events.push({
            ...base,
            id: `gh:pr:${item.number}:merged`,
            at: item.mergedAt,
            kind: "merge",
            sub: "pr-merged",
            title: `Pull request #${item.number} merged: ${item.title}`,
          });
        }
      } else {
        if (item.state === "closed" && item.stateReason === "not_planned") continue;
        events.push({
          ...base,
          id: `gh:issue:${item.number}:opened`,
          at: item.createdAt,
          kind: "plan",
          sub: "issue-opened",
          title: `Issue #${item.number} opened: ${item.title}`,
        });
        if (laneOf(item) === "claimed") {
          events.push({
            ...base,
            id: `gh:issue:${item.number}:claimed`,
            at: item.updatedAt,
            kind: "claim",
            sub: "issue-claimed",
            title: `Issue #${item.number} claimed: ${item.title}`,
          });
        }
      }
    }
  }

  // An event with no usable timestamp cannot be placed on the timeline.
  const timed = events.filter((event) => ms(event.at) !== null);

  /* ── Sector counts: merged pull requests (GitHub), else shipped versions (memory) ── */
  const counts = new Map<string, SwarmCount>();
  const since = now - RECENT_MS;
  const add = (sector: string, unit: string, at: string | null) => {
    const count = counts.get(sector) ?? { value: 0, unit, recent: 0, recentUnit: "today" };
    count.value += 1;
    if ((ms(at) ?? -Infinity) >= since) count.recent = (count.recent ?? 0) + 1;
    counts.set(sector, count);
  };
  if (github) {
    for (const item of github) {
      if (!item.isPullRequest || !item.mergedAt) continue;
      const workItem = workByPr.get(item.number);
      const sector = workItem ? sectorOfWork.get(workItem) : undefined;
      if (sector) add(sector, "merged", item.mergedAt);
    }
  } else {
    for (const row of source.versions) {
      const sector = known(row.target);
      if (sector) add(sector, source.shippedUnit ?? "shipped", row.created_at);
    }
  }

  const sectors: SwarmSector[] = source.targets.map((target) => ({
    id: target.id,
    label: target.name,
    color: target.color,
    count: counts.get(target.id) ?? (github || source.versions.length > 0 ? zero(github ? "merged" : source.shippedUnit ?? "shipped") : null),
  }));
  if (usesOther) {
    sectors.push({
      id: OTHER_SECTOR,
      // The only sector when no target is configured or recorded: the whole codebase.
      label: source.targets.length === 0 ? "Codebase" : "Other",
      color: "var(--rp-ink-soft)",
      count: counts.get(OTHER_SECTOR) ?? (github ? zero("merged") : null),
    });
  }

  return {
    integrationBranch: source.integrationBranch,
    asOf: new Date(now).toISOString(),
    sectors,
    agents,
    workItems,
    events: timed,
  };
}

function zero(unit: string): SwarmCount {
  return { value: 0, unit, recent: 0, recentUnit: "today" };
}

import { swarmConfig } from "../swarm.config";
import type { SwarmVocabulary } from "./config-types";
import type { CheckOutcome, Json, ResultRow } from "./types";

/** A vocabulary word, optionally capitalised: `word("shipped", true)` → "Shipped". */
export function word(key: keyof SwarmVocabulary, capitalise = false): string {
  const value = swarmConfig.vocabulary[key] ?? key;
  return capitalise ? cap(value) : value;
}

export function cap(value: string): string {
  return value ? value.charAt(0).toUpperCase() + value.slice(1) : value;
}

const numberFormat = new Intl.NumberFormat("en", { maximumFractionDigits: 2 });

export function formatNumber(value: number | null | undefined): string {
  return value === null || value === undefined || Number.isNaN(value) ? "—" : numberFormat.format(value);
}

export function formatScore(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  const unit = swarmConfig.measure.unit;
  return unit ? `${formatNumber(value)} ${unit}` : formatNumber(value);
}

export function formatDelta(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  const sign = value > 0 ? "+" : value < 0 ? "−" : "±";
  return `${sign}${formatNumber(Math.abs(value))}`;
}

export function formatPercent(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  const ratio = value > 1 ? value / 100 : value;
  return `${Math.round(ratio * 100)}%`;
}

export function formatMinutes(minutes: number | null | undefined): string {
  if (minutes === null || minutes === undefined) return "—";
  if (minutes < 60) return `${Math.round(minutes)} min`;
  const hours = minutes / 60;
  if (hours < 48) return `${formatNumber(Math.round(hours * 10) / 10)} h`;
  return `${formatNumber(Math.round((hours / 24) * 10) / 10)} d`;
}

export function formatDuration(ms: number | null | undefined): string {
  if (ms === null || ms === undefined) return "—";
  if (ms < 1000) return `${Math.round(ms)} ms`;
  const seconds = ms / 1000;
  if (seconds < 120) return `${formatNumber(Math.round(seconds * 10) / 10)} s`;
  return `${formatNumber(Math.round(seconds / 6) / 10)} min`;
}

const dateFormat = new Intl.DateTimeFormat("en", {
  day: "numeric",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  timeZone: "UTC",
  timeZoneName: "short",
});

const shortDate = new Intl.DateTimeFormat("en", { day: "numeric", month: "short", timeZone: "UTC" });

export function formatDate(iso: string | null | undefined): string {
  if (!iso) return "—";
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? iso : dateFormat.format(date);
}

export function formatShortDate(iso: string | number): string {
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? String(iso) : shortDate.format(date);
}

export function timeAgo(iso: string | null | undefined, now = Date.now()): string {
  if (!iso) return "never";
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return iso;
  const seconds = Math.round((now - then) / 1000);
  if (seconds < 45) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 36) return `${hours} h ago`;
  const days = Math.round(hours / 24);
  if (days < 45) return `${days} d ago`;
  return formatShortDate(iso);
}

export function shortSha(sha: string | null | undefined): string {
  return sha ? sha.slice(0, 7) : "—";
}

/** `details.checks` from a checks-mode referee run, when present and well formed. */
export function checksOf(result: Pick<ResultRow, "details">): CheckOutcome[] {
  const details = result.details;
  if (!details || typeof details !== "object" || Array.isArray(details)) return [];
  const checks = (details as Record<string, Json>).checks;
  if (!Array.isArray(checks)) return [];
  return checks.flatMap((check) => {
    if (!check || typeof check !== "object" || Array.isArray(check)) return [];
    const record = check as Record<string, Json>;
    if (typeof record.name !== "string") return [];
    return [
      {
        name: record.name,
        passed: record.passed === true,
        exitCode: typeof record.exitCode === "number" ? record.exitCode : null,
        durationMs: typeof record.durationMs === "number" ? record.durationMs : null,
      },
    ];
  });
}

/** The mode a result row was judged in, falling back to details.mode. */
export function resultMode(result: Pick<ResultRow, "mode" | "details" | "candidate_score">): string {
  if (result.mode) return result.mode;
  const details = result.details;
  if (details && typeof details === "object" && !Array.isArray(details)) {
    const mode = (details as Record<string, Json>).mode;
    if (typeof mode === "string") return mode;
  }
  return result.candidate_score !== null ? "score" : "checks";
}

/** A flat list of key/value pairs from a jsonb object, for display. */
export function jsonEntries(value: Json | null): [string, string][] {
  if (!value || typeof value !== "object" || Array.isArray(value)) return [];
  return Object.entries(value).map(([key, entry]) => [
    key,
    typeof entry === "number" ? formatNumber(entry) : typeof entry === "string" ? entry : JSON.stringify(entry),
  ]);
}

/**
 * A server-side, READ-ONLY GitHub REST reader. GitHub owns the work: issues,
 * labels and pull requests. Reads `RALLYPOINT_GITHUB_REPO` ("owner/name")
 * and the optional `RALLYPOINT_GITHUB_TOKEN` (raises rate limits, reads
 * private repositories). The token never reaches the browser. Responses are
 * cached for 120 seconds. `RALLYPOINT_GITHUB_API_URL` (optional) points at a
 * GitHub Enterprise Server API, e.g. https://ghe.example.com/api/v3.
 */

export const ENV_REPO = "RALLYPOINT_GITHUB_REPO";
export const ENV_TOKEN = "RALLYPOINT_GITHUB_TOKEN";

const API = (process.env.RALLYPOINT_GITHUB_API_URL?.trim() || "https://api.github.com").replace(/\/+$/, "");
/** The web host for links: github.com, or the Enterprise host of the API URL. */
const WEB = API === "https://api.github.com" ? "https://github.com" : API.replace(/\/api\/v3$/, "");
const REVALIDATE_SECONDS = 120;
/** Pages of 100 issues/PRs read per request (most recently updated first). */
const MAX_PAGES = 3;

/**
 * The label names the board sorts by. These are the defaults
 * `rallypoint init` creates (`.rallypoint/config.json`); change them here
 * if your repository renamed any.
 */
export const LABELS = {
  ready: "status:ready",
  claimed: "status:claimed",
  blocked: "status:blocked",
  deferred: "status:deferred",
  human: "needs:human",
  changesRequested: "status:changes-requested",
  approved: "review:approved",
  targetPrefix: "target:",
} as const;

export type GithubLabel = { name: string; color: string };

export type GithubItem = {
  number: number;
  title: string;
  url: string;
  isPullRequest: boolean;
  state: "open" | "closed";
  /** "completed" | "not_planned" | null, for issues. */
  stateReason: string | null;
  mergedAt: string | null;
  labels: GithubLabel[];
  author: string | null;
  updatedAt: string;
  createdAt: string;
  closedAt: string | null;
  /** For PRs: issue numbers named by "Closes #N" / "Fixes #N" / "Resolves #N". */
  closes: number[];
};

export type GithubReadResult<T> =
  | { ok: true; data: T; truncated: boolean }
  | { ok: false; reason: "no-repo" | "error"; message: string };

export function readGithubRepo(): string | null {
  const repo = process.env.RALLYPOINT_GITHUB_REPO?.trim() ?? "";
  return /^[\w.-]+\/[\w.-]+$/.test(repo) ? repo : null;
}

/** A link to an issue or PR. GitHub redirects /issues/N to /pull/N for PRs. */
export function githubRefUrl(ref: number | string | null | undefined): string | null {
  const repo = readGithubRepo();
  if (!repo || ref === null || ref === undefined) return null;
  const number = typeof ref === "number" ? ref : Number(String(ref).replace(/^#/, ""));
  if (!Number.isInteger(number) || number <= 0) return null;
  return `${WEB}/${repo}/issues/${number}`;
}

export function githubRepoUrl(path = ""): string | null {
  const repo = readGithubRepo();
  return repo ? `${WEB}/${repo}${path}` : null;
}

function githubHeaders(accept = "application/vnd.github+json"): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: accept,
    "X-GitHub-Api-Version": "2022-11-28",
    "User-Agent": "rallypoint-swarm-ui",
  };
  const token = process.env.RALLYPOINT_GITHUB_TOKEN?.trim();
  if (token) headers.Authorization = `Bearer ${token}`;
  return headers;
}

async function githubFetch(path: string, accept?: string): Promise<Response> {
  return fetch(`${API}${path}`, {
    headers: githubHeaders(accept),
    next: { revalidate: REVALIDATE_SECONDS },
  });
}

function failure(res: Response): { ok: false; reason: "error"; message: string } {
  if (res.status === 403 || res.status === 429) {
    return {
      ok: false,
      reason: "error",
      message: `GitHub rate limit or permission refusal (${res.status}). Set ${ENV_TOKEN} to raise the limit.`,
    };
  }
  if (res.status === 404) {
    return {
      ok: false,
      reason: "error",
      message: `GitHub returned 404. Check ${ENV_REPO}; a private repository needs ${ENV_TOKEN}.`,
    };
  }
  return { ok: false, reason: "error", message: `GitHub returned ${res.status}.` };
}

type RawIssue = {
  number: number;
  title: string;
  html_url: string;
  state: "open" | "closed";
  state_reason?: string | null;
  labels: ({ name?: string; color?: string } | string)[];
  user?: { login?: string } | null;
  updated_at: string;
  created_at: string;
  closed_at: string | null;
  body?: string | null;
  pull_request?: { merged_at?: string | null } | null;
};

const CLOSING = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s*:?\s+#(\d+)/gi;

function closingRefs(body: string | null | undefined): number[] {
  if (!body) return [];
  return [...body.matchAll(CLOSING)].map((match) => Number(match[1]));
}

function toItem(raw: RawIssue): GithubItem {
  return {
    closes: raw.pull_request ? closingRefs(raw.body) : [],
    number: raw.number,
    title: raw.title,
    url: raw.html_url,
    isPullRequest: Boolean(raw.pull_request),
    state: raw.state,
    stateReason: raw.state_reason ?? null,
    mergedAt: raw.pull_request?.merged_at ?? null,
    labels: raw.labels.map((label) =>
      typeof label === "string"
        ? { name: label, color: "ededed" }
        : { name: label.name ?? "", color: label.color ?? "ededed" },
    ),
    author: raw.user?.login ?? null,
    updatedAt: raw.updated_at,
    createdAt: raw.created_at,
    closedAt: raw.closed_at,
  };
}

/**
 * Issues and pull requests (GitHub's issues endpoint returns both), most
 * recently updated first, up to MAX_PAGES × 100. `truncated` is true when
 * more exist than were read.
 */
export async function listItems(): Promise<GithubReadResult<GithubItem[]>> {
  const repo = readGithubRepo();
  if (!repo) {
    return { ok: false, reason: "no-repo", message: `Set ${ENV_REPO} to owner/name.` };
  }
  const items: GithubItem[] = [];
  try {
    for (let page = 1; page <= MAX_PAGES; page += 1) {
      const res = await githubFetch(
        `/repos/${repo}/issues?state=all&sort=updated&direction=desc&per_page=100&page=${page}`,
      );
      if (!res.ok) return failure(res);
      const batch = (await res.json()) as RawIssue[];
      items.push(...batch.map(toItem));
      if (batch.length < 100) return { ok: true, data: items, truncated: false };
    }
    return { ok: true, data: items, truncated: true };
  } catch (cause) {
    return {
      ok: false,
      reason: "error",
      message: cause instanceof Error ? cause.message : "Could not reach GitHub.",
    };
  }
}

/**
 * The repository's default branch (`GET /repos/{repo}`), which is where most
 * Rallypoint projects integrate. Null when GitHub cannot be read.
 */
export async function readDefaultBranch(): Promise<string | null> {
  const repo = readGithubRepo();
  if (!repo) return null;
  try {
    const res = await githubFetch(`/repos/${repo}`);
    if (!res.ok) return null;
    const body = (await res.json()) as { default_branch?: unknown };
    return typeof body.default_branch === "string" && body.default_branch ? body.default_branch : null;
  } catch {
    return null;
  }
}

export type RepoEntry = {
  name: string;
  path: string;
  type: "file" | "dir";
  url: string;
};

/** `GET /repos/{repo}/contents/{dir}`: one directory listing. */
export async function listDirectory(dir: string): Promise<GithubReadResult<RepoEntry[]>> {
  const repo = readGithubRepo();
  if (!repo) {
    return { ok: false, reason: "no-repo", message: `Set ${ENV_REPO} to owner/name.` };
  }
  try {
    const res = await githubFetch(`/repos/${repo}/contents/${encodePath(dir)}`);
    if (res.status === 404) return { ok: true, data: [], truncated: false };
    if (!res.ok) return failure(res);
    const body = (await res.json()) as
      | { name: string; path: string; type: string; html_url: string }[]
      | Record<string, unknown>;
    if (!Array.isArray(body)) return { ok: true, data: [], truncated: false };
    return {
      ok: true,
      truncated: false,
      data: body
        .filter((entry) => entry.type === "file" || entry.type === "dir")
        .map((entry) => ({
          name: entry.name,
          path: entry.path,
          type: entry.type as "file" | "dir",
          url: entry.html_url,
        })),
    };
  } catch (cause) {
    return {
      ok: false,
      reason: "error",
      message: cause instanceof Error ? cause.message : "Could not reach GitHub.",
    };
  }
}

/** One file's raw text through the contents API. */
export async function readFile(path: string): Promise<GithubReadResult<string>> {
  const repo = readGithubRepo();
  if (!repo) {
    return { ok: false, reason: "no-repo", message: `Set ${ENV_REPO} to owner/name.` };
  }
  try {
    const res = await githubFetch(
      `/repos/${repo}/contents/${encodePath(path)}`,
      "application/vnd.github.raw+json",
    );
    if (!res.ok) return failure(res);
    return { ok: true, data: await res.text(), truncated: false };
  } catch (cause) {
    return {
      ok: false,
      reason: "error",
      message: cause instanceof Error ? cause.message : "Could not reach GitHub.",
    };
  }
}

function encodePath(path: string): string {
  return path
    .split("/")
    .filter(Boolean)
    .map((part) => encodeURIComponent(part))
    .join("/");
}

/* ───────────────────────── Lanes and delivery ───────────────────────── */

export const LANES = [
  { id: "backlog", label: "Backlog", description: "Open issues ready to claim." },
  { id: "claimed", label: "Claimed", description: "Reserved by one worker right now." },
  { id: "held", label: "Held", description: "Blocked, deferred or waiting on a human." },
  { id: "review", label: "In review", description: "Pull requests waiting for an independent verdict." },
  { id: "changes", label: "Changes asked", description: "Sent back to a fixer." },
  { id: "approved", label: "Approved", description: "Approved at the head SHA, waiting for a merger." },
  { id: "merged", label: "Merged", description: "Landed lately." },
] as const;

export type LaneId = (typeof LANES)[number]["id"];

const hasLabel = (item: GithubItem, name: string) =>
  item.labels.some((label) => label.name === name);

export function laneOf(item: GithubItem): LaneId | null {
  if (item.isPullRequest) {
    if (item.mergedAt) return "merged";
    if (item.state === "closed") return null;
    if (hasLabel(item, LABELS.approved)) return "approved";
    if (hasLabel(item, LABELS.changesRequested)) return "changes";
    return "review";
  }
  if (item.state === "closed") return null;
  if (
    hasLabel(item, LABELS.blocked) ||
    hasLabel(item, LABELS.deferred) ||
    hasLabel(item, LABELS.human)
  ) {
    return "held";
  }
  if (hasLabel(item, LABELS.claimed)) return "claimed";
  return "backlog";
}

export function targetsOf(item: GithubItem): string[] {
  return item.labels
    .filter((label) => label.name.startsWith(LABELS.targetPrefix))
    .map((label) => label.name.slice(LABELS.targetPrefix.length));
}

/**
 * Delivery progress: every issue counted once, in the furthest state it has
 * reached. Pull requests are linked to issues by "Closes #N" in their body.
 */
export type Delivery = {
  /** Issues counted: every issue except those closed as not planned. */
  total: number;
  /** Issues closed as completed. */
  merged: number;
  /** Open issues whose linked open PR is approved. */
  approved: number;
  /** Open issues with a linked open PR and no approval yet. */
  inReview: number;
  /** Open issues claimed by a worker, with no PR yet. */
  inBranch: number;
  /** Open issues nobody has claimed. */
  open: number;
};

/** Delivery progress, optionally for one `target:<id>` label. */
export function deliveryOf(items: GithubItem[], target?: string): Delivery {
  const openPrs = new Map<number, GithubItem>();
  for (const item of items) {
    if (!item.isPullRequest || item.state !== "open") continue;
    for (const issue of item.closes) {
      const known = openPrs.get(issue);
      if (!known || hasLabel(item, LABELS.approved)) openPrs.set(issue, item);
    }
  }
  const delivery: Delivery = { total: 0, merged: 0, approved: 0, inReview: 0, inBranch: 0, open: 0 };
  for (const item of items) {
    if (item.isPullRequest) continue;
    if (target && !hasLabel(item, `${LABELS.targetPrefix}${target}`)) continue;
    if (item.state === "closed") {
      if (item.stateReason === "not_planned") continue;
      delivery.total += 1;
      delivery.merged += 1;
      continue;
    }
    delivery.total += 1;
    const pr = openPrs.get(item.number);
    if (pr && hasLabel(pr, LABELS.approved)) delivery.approved += 1;
    else if (pr) delivery.inReview += 1;
    else if (hasLabel(item, LABELS.claimed)) delivery.inBranch += 1;
    else delivery.open += 1;
  }
  return delivery;
}

