/** The tunable folders the Skills page lists (CONTRACT.md `tunablePaths`). */
export const SKILL_FOLDERS = [
  { path: ".rallypoint/roles", label: "Role prompts" },
  { path: ".rallypoint/swarm/skills", label: "Skills" },
  { path: ".rallypoint/swarm/playbooks", label: "Playbooks" },
] as const;

export type SkillFolder = {
  path: string;
  label: string;
  entries: RepoEntry[];
  error: string | null;
};

export async function getSkills(selected?: string) {
  const repo = readGithubRepo();
  const folders: SkillFolder[] = await Promise.all(
    SKILL_FOLDERS.map(async (folder) => {
      const read = await listDirectory(folder.path);
      return {
        ...folder,
        entries: read.ok ? read.data.filter((entry) => entry.type === "file") : [],
        error: read.ok ? null : read.message,
      };
    }),
  );
  let file: { path: string; text: string | null; error: string | null } | null = null;
  // Only files the listing returned can be opened, so the query string cannot
  // read anything else in the repository.
  const allowed = folders.flatMap((folder) => folder.entries.map((entry) => entry.path));
  if (selected && allowed.includes(selected)) {
    const read = await readFile(selected);
    file = { path: selected, text: read.ok ? read.data : null, error: read.ok ? null : read.message };
  }
  return { repo, folders, file };
}

import { cookies } from "next/headers";

import type { SwarmTable, SwarmTables } from "./types";

/**
 * A zero-dependency, server-side, READ-ONLY PostgREST reader for the
 * project's own Supabase. It never writes: there is no insert, update,
 * delete or RPC-with-side-effects call anywhere in the swarm UI.
 *
 * Token: the signed-in user's access token (cookie `rp-swarm-token`, private
 * mode) or else the publishable key. RLS decides what each can read.
 */

export const TOKEN_COOKIE = "rp-swarm-token";

export const ENV_URL = "NEXT_PUBLIC_RALLYPOINT_SUPABASE_URL";
export const ENV_KEY = "NEXT_PUBLIC_RALLYPOINT_SUPABASE_KEY";

export type SupabaseEnv = { url: string; key: string };

export function readSupabaseEnv(): { env: SupabaseEnv | null; missing: string[] } {
  // Read at runtime (indexed access is not inlined at build), so a deploy can
  // change these without a rebuild. Only server code reads them.
  const url = process.env[ENV_URL]?.trim() ?? "";
  const key = process.env[ENV_KEY]?.trim() ?? "";
  const missing: string[] = [];
  if (!url) missing.push(ENV_URL);
  if (!key) missing.push(ENV_KEY);
  if (missing.length > 0) return { env: null, missing };
  return { env: { url: url.replace(/\/+$/, ""), key }, missing };
}

export async function readSessionToken(): Promise<string | null> {
  const jar = await cookies();
  const value = jar.get(TOKEN_COOKIE)?.value;
  return value ? value : null;
}

export type ReadError = {
  /** HTTP status, or 0 when the request never got a response. */
  status: number;
  /** PostgREST / Postgres error code when present (e.g. PGRST205, 42P01). */
  code: string | null;
  message: string;
  table: string;
};

export type ReadResult<T> = { ok: true; data: T } | { ok: false; error: ReadError };

export type SelectOptions = {
  select?: string;
  /** PostgREST order, e.g. "created_at.desc". */
  order?: string;
  limit?: number;
  /** Extra PostgREST filters, e.g. { status: "eq.working", id: "in.(1,2)" }. */
  filters?: Record<string, string>;
  /** Force the anon key even when a session token exists. */
  anon?: boolean;
};

function headers(env: SupabaseEnv, token: string | null): Record<string, string> {
  return {
    apikey: env.key,
    Authorization: `Bearer ${token ?? env.key}`,
    Accept: "application/json",
  };
}

async function toError(res: Response, table: string): Promise<ReadError> {
  let code: string | null = null;
  let message = `${res.status} ${res.statusText}`.trim();
  try {
    const body = (await res.json()) as { code?: string; message?: string };
    if (body.code) code = String(body.code);
    if (body.message) message = body.message;
  } catch {
    // Not JSON; keep the status line.
  }
  return { status: res.status, code, message, table };
}

/** True when an error means the swarm schema has not been applied. */
export function isMissingSchema(error: ReadError): boolean {
  return error.status === 404 || error.code === "PGRST205" || error.code === "42P01";
}

/** True when an error means the token was refused (expired or invalid). */
export function isAuthError(error: ReadError): boolean {
  return error.status === 401 || error.code === "PGRST301" || error.code === "PGRST303";
}

export async function selectRows<K extends SwarmTable>(
  table: K,
  options: SelectOptions = {},
): Promise<ReadResult<SwarmTables[K][]>> {
  const { env } = readSupabaseEnv();
  if (!env) {
    return {
      ok: false,
      error: { status: 0, code: "ENV", message: "Supabase env is not set.", table },
    };
  }
  const token = options.anon ? null : await readSessionToken();
  const params = new URLSearchParams();
  params.set("select", options.select ?? "*");
  if (options.order) params.set("order", options.order);
  if (options.limit !== undefined) params.set("limit", String(options.limit));
  for (const [column, filter] of Object.entries(options.filters ?? {})) {
    params.set(column, filter);
  }
  try {
    const res = await fetch(`${env.url}/rest/v1/${table}?${params.toString()}`, {
      headers: headers(env, token),
      cache: "no-store",
    });
    if (!res.ok) return { ok: false, error: await toError(res, table) };
    const data = (await res.json()) as SwarmTables[K][];
    return { ok: true, data: Array.isArray(data) ? data : [] };
  } catch (cause) {
    return {
      ok: false,
      error: {
        status: 0,
        code: null,
        message: cause instanceof Error ? cause.message : "Network error",
        table,
      },
    };
  }
}

/** Exact row count through `Prefer: count=exact` and `Content-Range`. */
export async function countRows(
  table: SwarmTable,
  filters: Record<string, string> = {},
): Promise<ReadResult<number>> {
  const { env } = readSupabaseEnv();
  if (!env) {
    return {
      ok: false,
      error: { status: 0, code: "ENV", message: "Supabase env is not set.", table },
    };
  }
  const token = await readSessionToken();
  const params = new URLSearchParams({ select: "*", limit: "1" });
  for (const [column, filter] of Object.entries(filters)) params.set(column, filter);
  try {
    const res = await fetch(`${env.url}/rest/v1/${table}?${params.toString()}`, {
      method: "HEAD",
      headers: { ...headers(env, token), Prefer: "count=exact" },
      cache: "no-store",
    });
    if (!res.ok) {
      return {
        ok: false,
        error: { status: res.status, code: null, message: res.statusText, table },
      };
    }
    const range = res.headers.get("content-range") ?? "";
    const total = Number(range.split("/")[1]);
    return { ok: true, data: Number.isFinite(total) ? total : 0 };
  } catch (cause) {
    return {
      ok: false,
      error: {
        status: 0,
        code: null,
        message: cause instanceof Error ? cause.message : "Network error",
        table,
      },
    };
  }
}

/* ───────────── Supabase Auth (private mode). Reads and session only. ───────────── */

export type AuthResult = { ok: true; token: string; expiresIn: number } | { ok: false; message: string };

function authMessage(body: unknown, fallback: string): string {
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    for (const key of ["error_description", "msg", "message", "error"]) {
      if (typeof record[key] === "string") return record[key] as string;
    }
  }
  return fallback;
}

/** `POST /auth/v1/token?grant_type=password` */
export async function passwordSignIn(email: string, password: string): Promise<AuthResult> {
  const { env } = readSupabaseEnv();
  if (!env) return { ok: false, message: "Supabase env is not set." };
  try {
    const res = await fetch(`${env.url}/auth/v1/token?grant_type=password`, {
      method: "POST",
      headers: { apikey: env.key, "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
      cache: "no-store",
    });
    const body = (await res.json().catch(() => null)) as
      | { access_token?: string; expires_in?: number }
      | null;
    if (!res.ok || !body?.access_token) {
      return { ok: false, message: authMessage(body, "Sign-in failed.") };
    }
    return { ok: true, token: body.access_token, expiresIn: body.expires_in ?? 3600 };
  } catch {
    return { ok: false, message: "Could not reach Supabase Auth." };
  }
}

/** `POST /auth/v1/otp`: sends a magic link to an existing user. */
export async function sendMagicLink(
  email: string,
  redirectTo: string,
): Promise<{ ok: true } | { ok: false; message: string }> {
  const { env } = readSupabaseEnv();
  if (!env) return { ok: false, message: "Supabase env is not set." };
  try {
    const res = await fetch(
      `${env.url}/auth/v1/otp?redirect_to=${encodeURIComponent(redirectTo)}`,
      {
        method: "POST",
        headers: { apikey: env.key, "Content-Type": "application/json" },
        body: JSON.stringify({ email, create_user: false }),
        cache: "no-store",
      },
    );
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      return { ok: false, message: authMessage(body, "Could not send the link.") };
    }
    return { ok: true };
  } catch {
    return { ok: false, message: "Could not reach Supabase Auth." };
  }
}

/** `GET /auth/v1/user`: true when the access token is valid. */
export async function verifyToken(token: string): Promise<boolean> {
  const { env } = readSupabaseEnv();
  if (!env) return false;
  try {
    const res = await fetch(`${env.url}/auth/v1/user`, {
      headers: { apikey: env.key, Authorization: `Bearer ${token}` },
      cache: "no-store",
    });
    return res.ok;
  } catch {
    return false;
  }
}

/**
 * Row types for every table and view in Rallypoint Swarm's Supabase schema
 * (`.rallypoint/swarm/schema.sql`). Names and columns follow
 * docs/swarm/CONTRACT.md exactly. PostgREST returns timestamps as ISO
 * strings, bigint ids as numbers and jsonb as parsed JSON.
 */

export type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

export type Visibility = "public" | "private";

export type MeasureMode = "score" | "checks" | "review";

export type GoalMeasure = {
  mode?: MeasureMode;
  label?: string;
  command?: string;
  checks?: { name: string; command?: string }[];
  direction?: "higher" | "lower";
  margin?: number;
  unit?: string;
};

export type GoalSetting = {
  title?: string;
  pitch?: string;
  statement?: string;
  measure?: GoalMeasure;
};

/** `swarm_settings(key text pk, value jsonb)` */
export type SettingRow = {
  key: "visibility" | "protocol_version" | "goal" | (string & {});
  value: Json;
};

/** The settings rows folded into one object. */
export type SwarmSettings = {
  visibility?: Visibility;
  protocol_version?: string;
  goal?: GoalSetting;
};

export type SessionStatus = "working" | "ended" | "abandoned";

/** `swarm_sessions` */
export type SessionRow = {
  id: string;
  agent: string | null;
  role: string | null;
  target: string | null;
  issue: number | null;
  pr: number | null;
  status: SessionStatus;
  summary: string | null;
  started_at: string;
  last_seen_at: string | null;
  ended_at: string | null;
};

/** `swarm_progress` */
export type ProgressRow = {
  id: number;
  session_id: string;
  note: string;
  created_at: string;
};

/** `swarm_retros` */
export type RetroRow = {
  id: number;
  session_id: string;
  role: string | null;
  protocol_version: string | null;
  went_well: string | null;
  friction: string | null;
  suggestion: string | null;
  created_at: string;
};

export type MessageKind = "question" | "proposal" | "handoff" | "answer" | "note";

/** `swarm_messages` */
export type MessageRow = {
  id: number;
  thread_id: number | null;
  session_id: string | null;
  author: string | null;
  kind: MessageKind;
  ref: string | null;
  topic: string | null;
  body: string;
  created_at: string;
};

/** One entry of `swarm_results.details.checks` in `checks` mode. */
export type CheckOutcome = {
  name: string;
  passed: boolean;
  exitCode?: number | null;
  durationMs?: number | null;
};

/** `swarm_results`: one referee run. Never assume a score exists. */
export type ResultRow = {
  id: number;
  session_id: string | null;
  target: string | null;
  issue: number | null;
  pr: number | null;
  commit_sha: string | null;
  baseline_sha: string | null;
  /** 'score' | 'checks' | 'review'. Null on rows written before modes existed. */
  mode: MeasureMode | null;
  candidate_score: number | null;
  baseline_score: number | null;
  delta: number | null;
  direction: string | null;
  margin: number | null;
  passed: boolean | null;
  details: Json | null;
  created_at: string;
};

/** `swarm_versions`: shipped versions. */
export type VersionRow = {
  id: number;
  target: string | null;
  version: string;
  score: number | null;
  pr: number | null;
  commit_sha: string | null;
  notes: string | null;
  created_at: string;
};

/** `swarm_buried` */
export type BuriedRow = {
  id: number;
  target: string | null;
  issue: number | null;
  pr: number | null;
  idea: string;
  concept: string | null;
  reason: string | null;
  lesson: string | null;
  numbers: Json | null;
  created_at: string;
};

/** `swarm_concepts` */
export type ConceptRow = {
  id: string;
  name: string;
  description: string | null;
  created_at: string;
};

export type TrialOutcome = "gained" | "lost" | "neutral";

/** `swarm_concept_trials` */
export type ConceptTrialRow = {
  id: number;
  concept_id: string;
  target: string;
  outcome: TrialOutcome;
  delta: number | null;
  ref: string | null;
  created_at: string;
};

/** `swarm_protocol_changes` */
export type ProtocolChangeRow = {
  id: number;
  version: string;
  issue: number | null;
  pr: number | null;
  summary: string;
  kept: boolean | null;
  created_at: string;
};

/** View `swarm_metrics`: one row. */
export type MetricsRow = {
  protocol_version: string | null;
  shipped: number | null;
  buried: number | null;
  ship_rate: number | null;
  median_claim_to_close_minutes: number | null;
  progress_per_session: number | null;
  retros_since_change: number | null;
  sessions_working: number | null;
};

/** View `swarm_fleet`: working sessions seen in the last 2 h. */
export type FleetRow = SessionRow & {
  latest_note: string | null;
  latest_note_at: string | null;
};

/** Every table and view the UI reads, by name. */
export type SwarmTables = {
  swarm_settings: SettingRow;
  swarm_sessions: SessionRow;
  swarm_progress: ProgressRow;
  swarm_retros: RetroRow;
  swarm_messages: MessageRow;
  swarm_results: ResultRow;
  swarm_versions: VersionRow;
  swarm_buried: BuriedRow;
  swarm_concepts: ConceptRow;
  swarm_concept_trials: ConceptTrialRow;
  swarm_protocol_changes: ProtocolChangeRow;
  swarm_metrics: MetricsRow;
  swarm_fleet: FleetRow;
};

export type SwarmTable = keyof SwarmTables;

import type { Metadata } from "next";
import Link from "next/link";

import { IssuePr, KindChip, Ref, TargetChip, Verdict } from "../_components/chips";
import { ResultOutcome } from "../_components/results";
import { Empty, FilterBar, Gate, PageHead, QueryErrors, TimeAgo } from "../_components/states";
import { cap, formatScore, word } from "../_lib/format";
import { BOARD_KINDS, getBoard, getSwarmContext, type BoardEntry, type BoardKind } from "../_lib/queries";
import { swarmConfig } from "../swarm.config";

export const metadata: Metadata = { title: "Board" };
export const dynamic = "force-dynamic";

const kindLabel = (kind: BoardKind): string =>
  ({
    result: cap(word("results")),
    version: cap(word("versions")),
    buried: cap(word("buried")),
    protocol: "Protocol",
    message: cap(word("messages")),
  })[kind];

function Entry({ entry }: { entry: BoardEntry }) {
  switch (entry.kind) {
    case "result":
      return (
        <>
          <span className="rp-tag">{cap(word("result"))}</span>{" "}
          <Link className="rp-mono" href={`/swarm/results/${entry.row.id}`}>
            #{entry.row.id}
          </Link>{" "}
          <TargetChip id={entry.row.target} /> <IssuePr issue={entry.row.issue} pr={entry.row.pr} />{" "}
          <Verdict passed={entry.row.passed} /> <ResultOutcome result={entry.row} />
        </>
      );
    case "version":
      return (
        <>
          <span className="rp-tag">{cap(word("shipped"))}</span> <TargetChip id={entry.row.target} />{" "}
          <span className="rp-mono">{entry.row.version}</span>
          {entry.row.score !== null ? <> · {formatScore(entry.row.score)}</> : null} · PR <Ref value={entry.row.pr} />
        </>
      );
    case "buried":
      return (
        <>
          <span className="rp-tag">{cap(word("buried"))}</span> <TargetChip id={entry.row.target} /> {entry.row.idea}{" "}
          <IssuePr issue={entry.row.issue} pr={entry.row.pr} />
          {entry.row.lesson ? <p className="rp-soft">{entry.row.lesson}</p> : null}
        </>
      );
    case "protocol":
      return (
        <>
          <span className="rp-tag">Protocol {entry.row.version}</span> {entry.row.summary}{" "}
          <IssuePr issue={entry.row.issue} pr={entry.row.pr} />
        </>
      );
    case "message":
      return (
        <>
          <KindChip kind={entry.row.kind} /> <span className="rp-mono">{entry.row.author ?? "—"}</span>
          {entry.row.ref ? (
            <>
              {" "}
              on <Ref value={entry.row.ref} />
            </>
          ) : null}
          : {entry.row.body}
        </>
      );
  }
}

function href(params: { kind?: string; target?: string }) {
  const query = new URLSearchParams();
  if (params.kind) query.set("kind", params.kind);
  if (params.target) query.set("target", params.target);
  const text = query.toString();
  return text ? `/swarm/board?${text}` : "/swarm/board";
}

export default async function BoardPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const params = await searchParams;
  const kind = BOARD_KINDS.find((entry) => entry === params.kind);
  const target = typeof params.target === "string" ? params.target : undefined;
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const { entries, errors } = await getBoard({ kind, target });

  return (
    <>
      <PageHead
        title="Board"
        lede={`The full record from memory, newest first: ${word("results")}, ${word("versions")}, ${word("ideas")} ${word("buried")}, protocol changes and ${word("messages")}.`}
      />
      <QueryErrors errors={errors} />
      <FilterBar
        label="Kind"
        options={[
          { href: href({ target }), label: "All", current: !kind },
          ...BOARD_KINDS.map((entry) => ({ href: href({ kind: entry, target }), label: kindLabel(entry), current: kind === entry })),
        ]}
      />
      <FilterBar
        label={cap(word("target"))}
        options={[
          { href: href({ kind }), label: "All", current: !target },
          ...swarmConfig.targets.map((entry) => ({
            href: href({ kind, target: entry.id }),
            label: entry.name,
            current: target === entry.id,
          })),
        ]}
      />
      {entries.length === 0 ? (
        <Empty>
          {kind || target ? (
            "Nothing recorded for this filter yet."
          ) : (
            <>
              Nothing recorded yet. The board fills as agents run the referee, ship{" "}
              {word("versions")}, bury losing {word("ideas")} and post {word("messages")}. Start by opening issues with{" "}
              <code>npx rallypoint swarm plan plan.json</code>.
            </>
          )}
        </Empty>
      ) : (
        <ol className="rp-feed">
          {entries.map((entry) => (
            <li key={`${entry.kind}-${entry.row.id}`}>
              <TimeAgo at={entry.at} />
              <div>
                <Entry entry={entry} />
              </div>
            </li>
          ))}
        </ol>
      )}
    </>
  );
}

