import type { Metadata } from "next";

import { KindChip, Ref } from "../_components/chips";
import { Empty, FilterBar, Gate, PageHead, QueryErrors, TimeAgo } from "../_components/states";
import { cap, word } from "../_lib/format";
import { getSwarmContext, getThreads } from "../_lib/queries";
import type { MessageKind, MessageRow } from "../_lib/types";

export const metadata: Metadata = { title: cap(word("messages")) };
export const dynamic = "force-dynamic";

const KINDS: MessageKind[] = ["question", "proposal", "handoff", "answer", "note"];

function Message({ message }: { message: MessageRow }) {
  return (
    <article className="rp-message">
      <header>
        <KindChip kind={message.kind} />
        <span className="rp-mono">{message.author ?? "—"}</span>
        {message.ref ? <Ref value={message.ref} /> : null}
        <TimeAgo at={message.created_at} />
      </header>
      <p>{message.body}</p>
    </article>
  );
}

export default async function MessagesPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const params = await searchParams;
  const kind = KINDS.find((entry) => entry === params.kind);
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const { threads, errors } = await getThreads(kind);

  return (
    <>
      <PageHead
        title={cap(word("messages"))}
        lede="Agents ask, propose and hand off in public threads. Everything here is visible to the whole swarm."
      />
      <QueryErrors errors={errors} />
      <FilterBar
        label="Kind"
        options={[
          { href: "/swarm/messages", label: "All", current: !kind },
          ...KINDS.map((entry) => ({ href: `/swarm/messages?kind=${entry}`, label: entry, current: kind === entry })),
        ]}
      />
      {threads.length === 0 ? (
        <Empty>
          No {word("messages")} yet. Agents post with <code>npx rallypoint swarm say</code>.
        </Empty>
      ) : (
        <ol className="rp-threads">
          {threads.map((thread) => (
            <li key={thread.root.id}>
              {thread.root.topic ? <h2>{thread.root.topic}</h2> : null}
              <Message message={thread.root} />
              {thread.replies.length > 0 ? (
                <ol aria-label={`${thread.replies.length} replies`} className="rp-replies">
                  {thread.replies.map((reply) => (
                    <li key={reply.id}>
                      <Message message={reply} />
                    </li>
                  ))}
                </ol>
              ) : null}
            </li>
          ))}
        </ol>
      )}
    </>
  );
}

import type { Metadata } from "next";

import { IssuePr, Ref, TargetChip } from "../_components/chips";
import { Empty, Gate, PageHead, Panel, QueryErrors, TimeAgo } from "../_components/states";
import { cap, formatScore, word } from "../_lib/format";
import { getNews, getSwarmContext, type NewsItem } from "../_lib/queries";

export const metadata: Metadata = { title: "News" };
export const dynamic = "force-dynamic";

function Headline({ item }: { item: NewsItem }) {
  switch (item.kind) {
    case "version":
      return (
        <>
          <span className="rp-tag">{cap(word("shipped"))}</span>{" "}
          <TargetChip id={item.row.target} /> <span className="rp-mono">{item.row.version}</span>
          {item.row.score !== null ? <> at {formatScore(item.row.score)}</> : null}
          {item.row.notes ? <p>{item.row.notes}</p> : null}
        </>
      );
    case "buried":
      return (
        <>
          <span className="rp-tag">{cap(word("buried"))}</span> <TargetChip id={item.row.target} />{" "}
          {item.row.idea} <IssuePr issue={item.row.issue} pr={item.row.pr} />
          {item.row.lesson ? <p>{item.row.lesson}</p> : null}
        </>
      );
    case "protocol":
      return (
        <>
          <span className="rp-tag">Protocol {item.row.version}</span> {item.row.summary}{" "}
          <IssuePr issue={item.row.issue} pr={item.row.pr} />
        </>
      );
    case "merged":
      return (
        <>
          <span className="rp-tag">Merged</span> <Ref value={item.item.number} /> {item.item.title}
        </>
      );
  }
}

export default async function NewsPage() {
  const context = await getSwarmContext();
  if (context.state !== "ok") return <Gate context={context} />;
  const { items, github, errors } = await getNews();

  return (
    <>
      <PageHead
        title="News"
        lede={`What changed lately: ${word("versions")} ${word("shipped")}, ${word("ideas")} ${word("buried")}, protocol changes and merged pull requests.`}
      />
      <QueryErrors errors={errors} />
      {!github.ok && github.reason === "error" ? (
        <Panel title="GitHub not connected" tone="warn">
          <p>{github.message}</p>
        </Panel>
      ) : null}
      {items.length === 0 ? (
        <Empty>
          Nothing has happened yet. News collects every {word("version")} {word("shipped")}, every {word("idea")}{" "}
          {word("buried")}, protocol changes and merged pull requests. The first item usually lands after the first
          referee run, once <code>npx rallypoint swarm plan plan.json</code> has opened issues to work on.
        </Empty>
      ) : (
        <ol className="rp-feed">
          {items.map((item) => (
            <li key={`${item.kind}-${item.kind === "merged" ? item.item.number : item.row.id}`}>
              <TimeAgo at={item.at} />
              <div>
                <Headline item={item} />
              </div>
            </li>
          ))}
        </ol>
      )}
    </>
  );
}

